def _recover_low_border_side_mini_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    recovered = list(detections)
    added: list[Detection] = []

    for y in range(0, ROOM_HEIGHT - 16 + 1, 16):
        for x in range(0, ROOM_WIDTH - 16 + 1, 16):
            patch = _patch_features(image, room, x, y, 16)
            block = _classify_block(patch)
            best_score = max(
                _triangle_direction_score(patch, direction)[0]
                for direction in ("up", "right", "down", "left")
            )
            if _is_low_border_side_mini_spike_patch(patch, block, best_score):
                for kind, type_id, direction in (
                    ("mini_spike_right", OBJ_MINI_SPIKE_RIGHT, "right"),
                    ("mini_spike_left", OBJ_MINI_SPIKE_LEFT, "left"),
                ):
                    score, _outline_delta = _triangle_direction_score(patch, direction)
                    if not _is_low_border_side_mini_spike_candidate(score):
                        continue
                    if not _has_low_border_side_mini_spike_support(
                        recovered,
                        x,
                        y,
                        type_id,
                    ):
                        continue
                    if _has_nearby_same_mini_spike(recovered, added, type_id, x, y):
                        continue
                    added.append(
                        _geometry_detection(
                            kind,
                            type_id,
                            x,
                            y,
                            score,
                            image,
                            room,
                            16,
                        )
                    )

            score, outline_delta = _triangle_direction_score(patch, "left")
            if _is_ultra_faint_left_mini_spike_candidate(
                patch,
                block,
                score,
                outline_delta,
                best_score,
            ) and _has_ultra_faint_left_mini_spike_support(recovered, x, y):
                if not _has_nearby_same_mini_spike(
                    recovered,
                    added,
                    OBJ_MINI_SPIKE_LEFT,
                    x,
                    y,
                ):
                    added.append(
                        _geometry_detection(
                            "mini_spike_left",
                            OBJ_MINI_SPIKE_LEFT,
                            x,
                            y,
                            score,
                            image,
                            room,
                            16,
                        )
                    )

    if added:
        recovered.extend(added)
    return recovered


def _is_low_border_side_mini_spike_patch(
    patch: _PatchFeatures,
    block: _GeometryClass,
    best_score: float,
) -> bool:
    return (
        patch.edge_density >= LOW_BORDER_SIDE_MINI_RECOVERY_MIN_EDGE_DENSITY
        and patch.edge_density <= LOW_BORDER_SIDE_MINI_RECOVERY_MAX_EDGE_DENSITY
        and patch.center_score >= LOW_BORDER_SIDE_MINI_RECOVERY_MIN_CENTER_SCORE
        and patch.center_score <= LOW_BORDER_SIDE_MINI_RECOVERY_MAX_CENTER_SCORE
        and patch.border_score <= LOW_BORDER_SIDE_MINI_RECOVERY_MAX_BORDER_SCORE
        and block.score <= LOW_BORDER_SIDE_MINI_RECOVERY_MAX_BLOCK_SCORE
        and best_score <= LOW_BORDER_SIDE_MINI_RECOVERY_MAX_BEST_TRIANGLE_SCORE
    )


def _is_low_border_side_mini_spike_candidate(score: float) -> bool:
    return score >= LOW_BORDER_SIDE_MINI_RECOVERY_MIN_SCORE


def _has_low_border_side_mini_spike_support(
    detections: list[Detection],
    x: int,
    y: int,
    type_id: int,
) -> bool:
    near_block_count = sum(
        1
        for det in detections
        if det.type_id == OBJ_BLOCK
        and distance((x, y), (det.x, det.y))
        <= LOW_BORDER_SIDE_MINI_RECOVERY_BLOCK_DISTANCE
    )
    if near_block_count != LOW_BORDER_SIDE_MINI_RECOVERY_NEAR_BLOCK_COUNT:
        return False

    same_full_type = (
        OBJ_SPIKE_RIGHT if type_id == OBJ_MINI_SPIKE_RIGHT else OBJ_SPIKE_LEFT
    )
    opposite_full_type = (
        OBJ_SPIKE_LEFT if type_id == OBJ_MINI_SPIKE_RIGHT else OBJ_SPIKE_RIGHT
    )
    return any(
        det.type_id in {same_full_type, opposite_full_type}
        and distance((x, y), (det.x, det.y))
        <= LOW_BORDER_SIDE_MINI_RECOVERY_SUPPORT_DISTANCE
        for det in detections
    )


def _is_ultra_faint_left_mini_spike_candidate(
    patch: _PatchFeatures,
    block: _GeometryClass,
    score: float,
    outline_delta: float,
    best_score: float,
) -> bool:
    return (
        patch.edge_density >= ULTRA_FAINT_LEFT_MINI_RECOVERY_MIN_EDGE_DENSITY
        and patch.edge_density <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_EDGE_DENSITY
        and patch.center_score >= ULTRA_FAINT_LEFT_MINI_RECOVERY_MIN_CENTER_SCORE
        and patch.center_score <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_CENTER_SCORE
        and patch.border_score >= ULTRA_FAINT_LEFT_MINI_RECOVERY_MIN_BORDER_SCORE
        and patch.border_score <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_BORDER_SCORE
        and block.score <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_BLOCK_SCORE
        and best_score <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_BEST_TRIANGLE_SCORE
        and score <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_SCORE
        and outline_delta <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_OUTLINE_DELTA
    )


def _has_ultra_faint_left_mini_spike_support(
    detections: list[Detection],
    x: int,
    y: int,
) -> bool:
    full_spikes = [det for det in detections if det.type_id in FULL_SPIKE_TYPES]
    blocks = [det for det in detections if det.type_id == OBJ_BLOCK]
    near_full_count = sum(
        1
        for det in full_spikes
        if distance((x, y), (det.x, det.y)) <= GRID_SIZE
    )
    near_block_count = sum(
        1
        for det in blocks
        if distance((x, y), (det.x, det.y))
        <= LOW_BORDER_SIDE_MINI_RECOVERY_BLOCK_DISTANCE
    )
    same_full_distance = min(
        (
            distance((x, y), (det.x, det.y))
            for det in full_spikes
            if det.type_id == OBJ_SPIKE_LEFT
        ),
        default=999.0,
    )
    opposite_full_distance = min(
        (
            distance((x, y), (det.x, det.y))
            for det in full_spikes
            if det.type_id == OBJ_SPIKE_RIGHT
        ),
        default=999.0,
    )
    block_distance = min(
        (distance((x, y), (det.x, det.y)) for det in blocks),
        default=999.0,
    )
    has_block_above = any(det.x == x and det.y == y - GRID_SIZE for det in blocks)
    has_right_block_support = any(
        det.x == x + GRID_SIZE // 2 and abs(det.y - y) <= GRID_SIZE
        for det in blocks
    )
    return (
        near_full_count == ULTRA_FAINT_LEFT_MINI_RECOVERY_NEAR_FULL_COUNT
        and near_block_count == ULTRA_FAINT_LEFT_MINI_RECOVERY_NEAR_BLOCK_COUNT
        and ULTRA_FAINT_LEFT_MINI_RECOVERY_MIN_SAME_FULL_DISTANCE
        <= same_full_distance
        <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_SAME_FULL_DISTANCE
        and ULTRA_FAINT_LEFT_MINI_RECOVERY_MIN_OPPOSITE_FULL_DISTANCE
        <= opposite_full_distance
        <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_OPPOSITE_FULL_DISTANCE
        and block_distance <= ULTRA_FAINT_LEFT_MINI_RECOVERY_MAX_BLOCK_DISTANCE
        and has_block_above
        and has_right_block_support
    )


def _recover_dense_adjacent_up_mini_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    recovered = list(detections)
    added: list[Detection] = []

    for y in range(0, ROOM_HEIGHT - 16 + 1, 16):
        for x in range(0, ROOM_WIDTH - 16 + 1, 16):
            patch = _patch_features(image, room, x, y, 16)
            block = _classify_block(patch)
            score, outline_delta = _triangle_direction_score(patch, "up")
            if not _is_dense_adjacent_up_mini_spike_candidate(
                patch,
                block,
                score,
                outline_delta,
            ):
                continue
            if _has_nearby_same_mini_spike(recovered, added, OBJ_MINI_SPIKE_UP, x, y):
                continue
            if not _has_dense_adjacent_up_mini_spike_support(recovered, x, y):
                continue
            added.append(
                _geometry_detection(
                    "mini_spike_up",
                    OBJ_MINI_SPIKE_UP,
                    x,
                    y,
                    score,
                    image,
                    room,
                    16,
                )
            )

    if added:
        recovered.extend(added)
    return recovered


def _is_dense_adjacent_up_mini_spike_candidate(
    patch: _PatchFeatures,
    block: _GeometryClass,
    score: float,
    outline_delta: float,
) -> bool:
    return (
        score >= DENSE_ADJACENT_UP_MINI_RECOVERY_MIN_SCORE
        and outline_delta >= DENSE_ADJACENT_UP_MINI_RECOVERY_MIN_OUTLINE_DELTA
        and patch.edge_density >= DENSE_ADJACENT_UP_MINI_RECOVERY_MIN_EDGE_DENSITY
        and patch.center_score >= DENSE_ADJACENT_UP_MINI_RECOVERY_MIN_CENTER_SCORE
        and block.score >= DENSE_ADJACENT_UP_MINI_RECOVERY_MIN_BLOCK_SCORE
    )


def _has_dense_adjacent_up_mini_spike_support(
    detections: list[Detection],
    x: int,
    y: int,
) -> bool:
    return any(
        det.type_id == OBJ_MINI_SPIKE_UP
        and det.score >= DENSE_ADJACENT_UP_MINI_RECOVERY_ANCHOR_SCORE
        and det.y == y
        and abs(det.x - x) == DENSE_ADJACENT_UP_MINI_RECOVERY_PAIR_DISTANCE
        for det in detections
    )


def _recover_final_structural_right_mini_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover right minis supported by an unambiguous local structure."""
    recovered = list(detections)
    mini_positions = {
        (detection.x, detection.y)
        for detection in recovered
        if detection.type_id in MINI_SPIKE_TYPES
    }
    for y in range(0, ROOM_HEIGHT - 16 + 1, 16):
        for x in range(0, ROOM_WIDTH - 16 + 1, 16):
            if (x, y) in mini_positions:
                continue
            patch = _patch_features(image, room, x, y, 16)
            mini = next(
                candidate
                for candidate in _classify_mini_spike_candidates(patch)
                if candidate.type_id == OBJ_MINI_SPIKE_RIGHT
            )
            block = _classify_block(patch)
            supported_stack = _is_final_right_mini_stack_candidate(
                patch,
                block,
                mini,
            ) and _has_final_right_mini_stack_support(recovered, x, y)
            supported_corridor = _is_final_right_mini_corridor_candidate(
                patch,
                block,
                mini,
            ) and _has_final_right_mini_corridor_support(recovered, x, y)
            if not (supported_stack or supported_corridor):
                continue
            recovered.append(
                _geometry_detection(
                    "mini_spike_right_structural_recovery",
                    OBJ_MINI_SPIKE_RIGHT,
                    x,
                    y,
                    mini.score,
                    image,
                    room,
                    16,
                )
            )
            mini_positions.add((x, y))
    return recovered


def _is_final_right_mini_stack_candidate(
    patch: _PatchFeatures,
    block: _GeometryClass,
    mini: _GeometryClass,
) -> bool:
    return (
        mini.score >= FINAL_RIGHT_MINI_STACK_MIN_SCORE
        and mini.direction_margin >= FINAL_RIGHT_MINI_STACK_MIN_DIRECTION_MARGIN
        and mini.outline_delta >= FINAL_RIGHT_MINI_STACK_MIN_OUTLINE_DELTA
        and patch.edge_density >= FINAL_RIGHT_MINI_STACK_MIN_EDGE_DENSITY
        and block.score <= FINAL_RIGHT_MINI_STACK_MAX_BLOCK_SCORE
    )


def _has_final_right_mini_stack_support(
    detections: list[Detection],
    x: int,
    y: int,
) -> bool:
    has_vertical_pair = any(
        detection.type_id == OBJ_MINI_SPIKE_RIGHT
        and detection.x == x
        and abs(detection.y - y) == FINAL_RIGHT_MINI_STACK_PAIR_DISTANCE
        for detection in detections
    )
    has_opposite = any(
        detection.type_id == OBJ_MINI_SPIKE_LEFT
        and detection.x == x + FINAL_RIGHT_MINI_STACK_OPPOSITE_X_OFFSET
        and detection.y == y
        for detection in detections
    )
    return has_vertical_pair and has_opposite


def _is_final_right_mini_corridor_candidate(
    patch: _PatchFeatures,
    block: _GeometryClass,
    mini: _GeometryClass,
) -> bool:
    return (
        mini.score >= FINAL_RIGHT_MINI_CORRIDOR_MIN_SCORE
        and FINAL_RIGHT_MINI_CORRIDOR_MIN_EDGE_DENSITY
        <= patch.edge_density
        <= FINAL_RIGHT_MINI_CORRIDOR_MAX_EDGE_DENSITY
        and patch.border_score <= FINAL_RIGHT_MINI_CORRIDOR_MAX_BORDER_SCORE
        and FINAL_RIGHT_MINI_CORRIDOR_MIN_CENTER_SCORE
        <= patch.center_score
        <= FINAL_RIGHT_MINI_CORRIDOR_MAX_CENTER_SCORE
        and block.score <= FINAL_RIGHT_MINI_CORRIDOR_MAX_BLOCK_SCORE
    )


def _has_final_right_mini_corridor_support(
    detections: list[Detection],
    x: int,
    y: int,
) -> bool:
    block_positions = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    has_full_continuation = any(
        detection.type_id == OBJ_SPIKE_RIGHT
        and abs(detection.x - x) <= FINAL_RIGHT_MINI_CORRIDOR_FULL_X_SLOP
        and detection.y == y + FINAL_RIGHT_MINI_CORRIDOR_FULL_Y_OFFSET
        for detection in detections
    )
    return has_full_continuation and {
        (x + FINAL_RIGHT_MINI_CORRIDOR_BLOCK_LEFT_OFFSET, y),
        (x + FINAL_RIGHT_MINI_CORRIDOR_BLOCK_RIGHT_OFFSET, y),
    }.issubset(block_positions)


def _recover_low_contrast_mini_up_pairs(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    if _is_directly_full_scale_dominant(detections):
        return detections
    if any(
        det.type_id in MINI_SPIKE_TYPES
        and det.score >= LOW_CONTRAST_MINI_UP_STRONG_ANCHOR_SCORE
        for det in detections
    ):
        return detections

    recovered = list(detections)
    candidates: dict[tuple[int, int], float] = {}
    for y in range(0, ROOM_HEIGHT - 16 + 1, 16):
        for x in range(0, ROOM_WIDTH - 16 + 1, 16):
            patch = _patch_features(image, room, x, y, 16)
            score, outline_delta = _triangle_direction_score(patch, "up")
            block = _classify_block(patch)
            if _is_low_contrast_mini_up_candidate(
                patch,
                block,
                score,
                outline_delta,
            ):
                candidates[(x, y)] = score

    added: list[Detection] = []
    for (x, y), score in sorted(
        candidates.items(),
        key=lambda item: (item[0][1], item[0][0]),
    ):
        if not _has_low_contrast_mini_up_pair(candidates, x, y):
            continue
        if _has_nearby_same_mini_spike(recovered, added, OBJ_MINI_SPIKE_UP, x, y):
            continue
        added.append(
            _geometry_detection(
                "mini_spike_up",
                OBJ_MINI_SPIKE_UP,
                x,
                y,
                score,
                image,
                room,
                16,
            )
        )

    if added:
        recovered.extend(added)
    return recovered


def _is_directly_full_scale_dominant(detections: list[Detection]) -> bool:
    """Distinguish weak mini evidence from fragments of clear full spikes.

    The low-contrast pair recovery is intentionally permissive, so the two
    base halves of a 32px triangle can resemble adjacent 16px up spikes.  A
    room with many directly classified full spikes and almost no independently
    classified minis already supplies a strong scale prior; manufacturing a
    second mini-scale interpretation there only poisons later room profiling.
    Mixed-scale and genuinely mini-dense rooms retain the recovery.
    """

    full_count = sum(
        detection.type_id in FULL_SPIKE_TYPES for detection in detections
    )
    mini_count = sum(
        detection.type_id in MINI_SPIKE_TYPES for detection in detections
    )
    return (
        full_count >= LOW_CONTRAST_MINI_UP_FULL_SCALE_MIN_COUNT
        and mini_count
        <= full_count * LOW_CONTRAST_MINI_UP_FULL_SCALE_MAX_MINI_RATIO
    )


def _is_low_contrast_mini_up_candidate(
    patch: _PatchFeatures,
    block: _GeometryClass,
    score: float,
    outline_delta: float,
) -> bool:
    return (
        score >= LOW_CONTRAST_MINI_UP_MIN_SCORE
        and outline_delta >= LOW_CONTRAST_MINI_UP_MIN_OUTLINE_DELTA
        and patch.edge_density >= LOW_CONTRAST_MINI_UP_MIN_EDGE_DENSITY
        and patch.center_score >= LOW_CONTRAST_MINI_UP_MIN_CENTER_SCORE
        and block.score <= LOW_CONTRAST_MINI_UP_MAX_BLOCK_SCORE
    )


def _has_low_contrast_mini_up_pair(
    candidates: dict[tuple[int, int], float],
    x: int,
    y: int,
) -> bool:
    return (
        (x - LOW_CONTRAST_MINI_UP_PAIR_DISTANCE, y) in candidates
        or (x + LOW_CONTRAST_MINI_UP_PAIR_DISTANCE, y) in candidates
    )


def _recover_edge_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    recovered = list(detections)
    block_positions = {(det.x, det.y) for det in recovered if det.type_id == OBJ_BLOCK}
    geometry_positions = {
        (det.x, det.y)
        for det in recovered
        if det.type_id in GEOMETRY_TYPES
    }
    added: list[Detection] = []

    for edge_x, offscreen_x, support_x in (
        (0, -GRID_SIZE, GRID_SIZE),
        (ROOM_WIDTH - GRID_SIZE, ROOM_WIDTH, ROOM_WIDTH - GRID_SIZE * 2),
    ):
        for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
            if (offscreen_x, y) in block_positions:
                continue
            if (edge_x, y) not in block_positions:
                continue
            has_vertical_support = (
                (edge_x, y - GRID_SIZE) in block_positions
                and (edge_x, y + GRID_SIZE) in block_positions
            )
            has_inward_geometry = (support_x, y) in geometry_positions
            has_inward_block = (support_x, y) in block_positions
            if not (
                has_vertical_support
                and has_inward_geometry
                and not has_inward_block
            ):
                continue
            added.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    offscreen_x,
                    y,
                    EDGE_BLOCK_EXTENSION_SCORE,
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            block_positions.add((offscreen_x, y))

    for x in (0, ROOM_WIDTH - GRID_SIZE):
        for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, BLOCK_ALIGNMENT_STEP):
            if (x, y) in block_positions:
                continue
            if (x, y) in geometry_positions:
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            if not _is_edge_outline_block_patch(patch):
                continue
            added.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    max(EDGE_BLOCK_EXTENSION_SCORE, _classify_block(patch).score),
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            block_positions.add((x, y))

    y = ROOM_HEIGHT - GRID_SIZE
    for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
        if (x, y) in block_positions:
            continue
        if (x, y) in geometry_positions:
            continue
        if not (
            (x - GRID_SIZE, y) in geometry_positions
            or (x + GRID_SIZE, y) in geometry_positions
        ):
            continue
        patch = _patch_features(image, room, x, y, GRID_SIZE)
        block = _classify_block(patch)
        if not _is_edge_weak_block_patch(patch, block):
            continue
        added.append(
            _geometry_detection(
                "block",
                OBJ_BLOCK,
                x,
                y,
                max(EDGE_BLOCK_EXTENSION_SCORE, block.score),
                image,
                room,
                GRID_SIZE,
            )
        )
        block_positions.add((x, y))

    if added:
        recovered.extend(added)
    return recovered


def _recover_supported_block_cells(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover strong grid cells revealed by a completed same-axis block run."""
    recovered = list(detections)
    block_positions = {(det.x, det.y) for det in recovered if det.type_id == OBJ_BLOCK}
    added: list[Detection] = []
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            if (x, y) in block_positions:
                continue
            axis_support = sum(
                position in block_positions
                for position in (
                    (x - GRID_SIZE, y),
                    (x + GRID_SIZE, y),
                    (x, y - GRID_SIZE),
                    (x, y + GRID_SIZE),
                )
            )
            if axis_support < 2:
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            block = _classify_block(patch)
            boundary = x in (0, ROOM_WIDTH - GRID_SIZE) or y in (0, ROOM_HEIGHT - GRID_SIZE)
            min_score = (
                SUPPORTED_BOUNDARY_BLOCK_CELL_MIN_SCORE
                if boundary
                else SUPPORTED_BLOCK_CELL_MIN_SCORE
            )
            if not (
                block.score >= min_score
                and patch.edge_density >= SUPPORTED_BLOCK_CELL_EDGE_SCORE
                and patch.border_score >= SUPPORTED_BLOCK_CELL_BORDER_SCORE
            ):
                continue
            added.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    block.score,
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            block_positions.add((x, y))
    recovered.extend(added)
    return recovered


def _is_dark_outline_room(image: RGBImage, room: Box) -> bool:
    dark = outline = total = 0
    step = 16
    for y in range(max(0, room.y), min(image.height, room.bottom), step):
        row = image.row(y)
        for x in range(max(0, room.x), min(image.width, room.right), step):
            offset = x * 3
            r = row[offset]
            g = row[offset + 1]
            b = row[offset + 2]
            total += 1
            brightness = r + g + b
            saturation = max(r, g, b) - min(r, g, b)
            if brightness < 80:
                dark += 1
            if brightness >= 80 and saturation >= 35:
                outline += 1
    if total == 0:
        return False
    return (
        dark / total >= DARK_OUTLINE_ROOM_MIN_DARK_RATIO
        and outline / total >= DARK_OUTLINE_ROOM_MIN_OUTLINE_RATIO
    )


def _is_dark_outline_block_run_fill_patch(patch: _PatchFeatures) -> bool:
    return (
        patch.edge_density <= DARK_OUTLINE_BLOCK_FILL_MAX_EDGE
        and patch.border_score <= DARK_OUTLINE_BLOCK_FILL_MAX_BORDER
        and patch.center_score <= DARK_OUTLINE_BLOCK_FILL_MAX_CENTER
    )


def _is_dark_outline_full_spike_candidate(spike: _GeometryClass) -> bool:
    return (
        spike.score >= DARK_OUTLINE_FULL_SPIKE_MIN_SCORE
        and spike.outline_delta >= DARK_OUTLINE_FULL_SPIKE_MIN_OUTLINE_DELTA
    )


def _is_dark_outline_half_step_full_spike_candidate(spike: _GeometryClass) -> bool:
    return (
        spike.score >= DARK_OUTLINE_HALF_STEP_FULL_SPIKE_MIN_SCORE
        and spike.outline_delta
        >= DARK_OUTLINE_HALF_STEP_FULL_SPIKE_MIN_OUTLINE_DELTA
    )


def _is_dark_outline_eight_step_full_spike_candidate(
    spike: _GeometryClass,
    patch: _PatchFeatures,
    block: _GeometryClass,
    side_coverage: float,
) -> bool:
    return (
        spike.score >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MIN_SCORE
        and spike.direction_margin
        >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MIN_DIRECTION_MARGIN
        and spike.outline_delta
        >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MIN_OUTLINE_DELTA
        and side_coverage
        >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MIN_SIDE_COVERAGE
        and patch.edge_density
        >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MIN_EDGE_DENSITY
        and block.score <= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_MAX_BLOCK_SCORE
        and (
            spike.direction_margin
            >= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_STRONG_DIRECTION_MARGIN
            or block.score <= DARK_OUTLINE_EIGHT_STEP_FULL_SPIKE_LOW_BLOCK_SCORE
        )
    )


def _is_supported_full_spike_candidate(
    spike: _GeometryClass,
    block: _GeometryClass,
    patch: _PatchFeatures,
) -> bool:
    return (
        spike.score >= SUPPORTED_FULL_SPIKE_MIN_SCORE
        and spike.outline_delta >= SUPPORTED_FULL_SPIKE_MIN_OUTLINE_DELTA
        and spike.direction_margin >= SUPPORTED_FULL_SPIKE_MIN_DIRECTION_MARGIN
        and block.score <= SUPPORTED_FULL_SPIKE_MAX_BLOCK_SCORE
        and SUPPORTED_FULL_SPIKE_MIN_CENTER_SCORE
        <= patch.center_score
        <= SUPPORTED_FULL_SPIKE_MAX_CENTER_SCORE
    )


def _is_low_signal_supported_full_spike_candidate(
    spike: _GeometryClass,
    block: _GeometryClass,
    patch: _PatchFeatures,
) -> bool:
    return (
        spike.score >= LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MIN_SCORE
        and spike.outline_delta >= LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MIN_OUTLINE_DELTA
        and spike.direction_margin >= LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MIN_DIRECTION_MARGIN
        and block.score <= LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MAX_BLOCK_SCORE
        and SUPPORTED_FULL_SPIKE_MIN_CENTER_SCORE
        <= patch.center_score
        <= SUPPORTED_FULL_SPIKE_MAX_CENTER_SCORE
    )


def _supported_full_spike_near_distance(
    spike: _GeometryClass,
    block: _GeometryClass,
    patch: _PatchFeatures,
    half_step: bool,
) -> float | None:
    if not half_step:
        if _is_supported_full_spike_candidate(spike, block, patch):
            return SUPPORTED_FULL_SPIKE_MAX_NEAR_DISTANCE
        if _is_low_signal_supported_full_spike_candidate(spike, block, patch):
            return LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MAX_NEAR_DISTANCE
        return None
    if _is_half_step_supported_full_spike_candidate(spike, block, patch):
        return HALF_STEP_SUPPORTED_FULL_SPIKE_MAX_NEAR_DISTANCE
    if _is_low_signal_supported_full_spike_candidate(spike, block, patch):
        return HALF_STEP_LOW_SIGNAL_SUPPORTED_FULL_SPIKE_MAX_NEAR_DISTANCE
    return None


def _is_half_step_supported_full_spike_candidate(
    spike: _GeometryClass,
    block: _GeometryClass,
    patch: _PatchFeatures,
) -> bool:
    return (
        spike.score >= HALF_STEP_SUPPORTED_FULL_SPIKE_MIN_SCORE
        and spike.outline_delta >= HALF_STEP_SUPPORTED_FULL_SPIKE_MIN_OUTLINE_DELTA
        and spike.direction_margin >= HALF_STEP_SUPPORTED_FULL_SPIKE_MIN_DIRECTION_MARGIN
        and block.score <= HALF_STEP_SUPPORTED_FULL_SPIKE_MAX_BLOCK_SCORE
        and SUPPORTED_FULL_SPIKE_MIN_CENTER_SCORE
        <= patch.center_score
        <= SUPPORTED_FULL_SPIKE_MAX_CENTER_SCORE
    )


def _is_edge_outline_block_patch(patch: _PatchFeatures) -> bool:
    return (
        patch.edge_density >= EDGE_OUTLINE_BLOCK_MIN_EDGE
        and patch.border_score >= EDGE_OUTLINE_BLOCK_MIN_BORDER
        and patch.center_score <= EDGE_OUTLINE_BLOCK_MAX_CENTER
    )


def _is_edge_weak_block_patch(
    patch: _PatchFeatures,
    block: _GeometryClass,
) -> bool:
    return (
        block.score >= EDGE_WEAK_BLOCK_MIN_BLOCK_SCORE
        and patch.edge_density >= EDGE_WEAK_BLOCK_MIN_EDGE
        and patch.border_score >= EDGE_WEAK_BLOCK_MIN_BORDER
    )


def _accept_block_run_gap_patch(
    patch: _PatchFeatures,
    block: _GeometryClass,
    support: str = "cluster",
) -> bool:
    if (
        block.score >= BLOCK_RUN_GAP_MIN_BLOCK_SCORE
        and patch.edge_density >= BLOCK_RUN_GAP_MIN_EDGE_DENSITY
    ):
        return True
    return (
        block.score >= BLOCK_RUN_GAP_HOLLOW_MIN_BLOCK_SCORE
        and patch.edge_density >= BLOCK_RUN_GAP_HOLLOW_MIN_EDGE_DENSITY
        and patch.border_score >= BLOCK_RUN_GAP_HOLLOW_MIN_BORDER_SCORE
        and patch.center_score <= BLOCK_RUN_GAP_HOLLOW_MAX_CENTER_SCORE
    )


def _is_block_run_gap(x: int, y: int, block_positions: set[tuple[int, int]]) -> bool:
    return _block_run_gap_support(x, y, block_positions) is not None


def _block_run_gap_support(
    x: int,
    y: int,
    block_positions: set[tuple[int, int]],
) -> str | None:
    neighboring_blocks = [
        (x - BLOCK_RUN_GAP_STEP, y),
        (x + BLOCK_RUN_GAP_STEP, y),
        (x, y - BLOCK_RUN_GAP_STEP),
        (x, y + BLOCK_RUN_GAP_STEP),
    ]
    if sum(position in block_positions for position in neighboring_blocks) >= 2:
        return "cluster"
    same_axis_run = (
        (
            (x - BLOCK_RUN_GAP_STEP, y) in block_positions
            and (x - BLOCK_RUN_GAP_STEP * 2, y) in block_positions
        )
        or (
            (x + BLOCK_RUN_GAP_STEP, y) in block_positions
            and (x + BLOCK_RUN_GAP_STEP * 2, y) in block_positions
        )
        or (
            (x, y - BLOCK_RUN_GAP_STEP) in block_positions
            and (x, y - BLOCK_RUN_GAP_STEP * 2) in block_positions
        )
        or (
            (x, y + BLOCK_RUN_GAP_STEP) in block_positions
            and (x, y + BLOCK_RUN_GAP_STEP * 2) in block_positions
        )
    )
    if same_axis_run:
        return "axis_extension"
    if any(position in block_positions for position in neighboring_blocks):
        return "neighbor_extension"
    return None


def _normalize_full_spike_detections(detections: list[Detection]) -> list[Detection]:
    normalized: list[Detection] = []
    for detection in detections:
        if detection.type_id not in FULL_SPIKE_TYPES:
            normalized.append(detection)
            continue
        if detection.kind == "full_spike_shape_recovery":
            x, y = detection.x, detection.y
        else:
            x, y = _normalize_full_spike_origin(
                detection.type_id,
                detection.x,
                detection.y,
            )
        normalized.append(
            Detection(
                detection.kind,
                detection.type_id,
                x,
                y,
                detection.score,
                detection.image_box,
            )
        )
    return normalized


def _dedupe_normalized_full_spikes(detections: list[Detection]) -> list[Detection]:
    kept_full_spikes: list[Detection] = []
    removed_full_spike_ids: set[int] = set()
    full_spikes = sorted(
        (det for det in detections if det.type_id in FULL_SPIKE_TYPES),
        key=lambda det: (-det.score, det.y, det.x),
    )
    for detection in full_spikes:
        if any(
            detection.type_id == kept.type_id
            and distance((detection.x, detection.y), (kept.x, kept.y))
            < FULL_SPIKE_POST_NORMALIZE_DEDUPE_DISTANCE
            for kept in kept_full_spikes
        ):
            removed_full_spike_ids.add(id(detection))
            continue
        kept_full_spikes.append(detection)
    return [det for det in detections if id(det) not in removed_full_spike_ids]


def _prune_final_geometry_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    original_detections = list(detections)
    detections = _prune_recovered_full_spike_noise(detections)
    detections = _prune_isolated_weak_full_spike_shape_noise(
        detections,
        image,
        room,
    )
    detections = _prune_blocklike_mini_spike_noise(detections, image, room)
    detections = _prune_isolated_weak_block_noise(detections)
    detections = _prune_adaptive_block_noise(detections)
    detections = _prune_adaptive_weak_block_noise(detections)
    detections = _prune_sparse_off_grid_block_noise(detections)
    detections = _prune_low_signal_block_patches(detections, image, room)
    detections = _recover_low_signal_boundary_blocks(detections, image, room)
    detections = _recover_low_signal_supported_blocks(detections, image, room)
    detections = _recover_low_signal_fuzzy_blocks(detections, image, room)
    detections = _recover_low_signal_bottom_boundary_blocks(detections, image, room)
    if _is_dark_outline_room(image, room):
        detections = _prune_dark_outline_low_signal_blocks(detections)
        detections = _recover_dark_outline_block_runs(detections, image, room)
        detections = _recover_block_run_gaps(detections, image, room)
        detections = _recover_dark_outline_supported_low_signal_blocks(
            original_detections,
            detections,
            image,
            room,
        )
        detections = _recover_dark_outline_center_heavy_blocks(
            detections,
            image,
            room,
        )
        detections = _recover_dark_outline_low_signal_run_gaps(
            detections,
            image,
            room,
        )
        detections = _recover_dark_outline_double_run_gaps(
            detections,
            image,
            room,
        )
        detections = _prune_dark_outline_off_grid_low_signal_blocks(
            detections,
            image,
            room,
        )
        detections = _recover_dark_outline_long_low_signal_runs(
            detections,
            image,
            room,
        )
    detections = _prune_primary_isolated_full_spikes(detections, image, room)
    detections = _prune_full_spike_shape_noise(detections, image, room)
    recovered = _recover_pruned_full_spikes(
        original_detections,
        detections,
        image,
        room,
    )
    return _prune_final_full_spike_recovery_noise(recovered, image, room)


def _recover_pruned_full_spikes(
    original_detections: list[Detection],
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover strong candidates removed only by final full-spike pruning."""
    recovered = list(detections)
    full_spikes = [
        detection
        for detection in recovered
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    original_full_spikes = [
        detection
        for detection in original_detections
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    candidates: list[Detection] = []
    for detection in original_detections:
        direction = direction_by_type.get(detection.type_id)
        if direction is None:
            continue
        if any(
            existing.type_id == detection.type_id
            and distance((detection.x, detection.y), (existing.x, existing.y))
            < FULL_SPIKE_FINAL_DEDUPE_DISTANCE
            for existing in full_spikes
        ):
            continue
        patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
        spike = _classify_full_spike(patch)
        if spike is None or spike.type_id != detection.type_id:
            continue
        block = _classify_block(patch)
        side_coverage = _triangle_side_coverage(patch, direction)
        run_supported = any(
            other.type_id == detection.type_id
            and (
                (
                    detection.type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN)
                    and abs(other.y - detection.y)
                    <= FULL_SPIKE_RECALL_RECOVERY_AXIS_TOLERANCE
                    and 8 < abs(other.x - detection.x)
                    <= FULL_SPIKE_RECALL_RECOVERY_NEIGHBOR_DISTANCE
                )
                or (
                    detection.type_id in (OBJ_SPIKE_LEFT, OBJ_SPIKE_RIGHT)
                    and abs(other.x - detection.x)
                    <= FULL_SPIKE_RECALL_RECOVERY_AXIS_TOLERANCE
                    and 8 < abs(other.y - detection.y)
                    <= FULL_SPIKE_RECALL_RECOVERY_NEIGHBOR_DISTANCE
                )
            )
            for other in original_full_spikes
        )
        standard_recovery = (
            detection.score >= FULL_SPIKE_RECALL_RECOVERY_MIN_SCORE
            and side_coverage >= FULL_SPIKE_RECALL_RECOVERY_MIN_SIDE_COVERAGE
            and patch.edge_density >= FULL_SPIKE_RECALL_RECOVERY_MIN_EDGE_DENSITY
            and block.score <= FULL_SPIKE_RECALL_RECOVERY_MAX_BLOCK_SCORE
            and spike.outline_delta >= FULL_SPIKE_RECALL_RECOVERY_MIN_OUTLINE_DELTA
            and spike.direction_margin
            >= FULL_SPIKE_RECALL_RECOVERY_MIN_DIRECTION_MARGIN
        )
        supported_recovery = _is_low_signal_supported_full_spike_recovery(
            detection,
            spike,
            block,
            patch,
            side_coverage,
            run_supported,
        )
        if not (standard_recovery or supported_recovery):
            continue
        isolated_shape = (
            detection.score >= 0.42
            and side_coverage >= 0.625
            and patch.edge_density >= 0.25
            and spike.direction_margin >= 0.08
        )
        if not run_supported and not isolated_shape:
            continue
        candidates.append(detection)

    for detection in sorted(candidates, key=lambda item: (-item.score, item.y, item.x)):
        if any(
            existing.type_id == detection.type_id
            and distance((detection.x, detection.y), (existing.x, existing.y))
            < FULL_SPIKE_FINAL_DEDUPE_DISTANCE
            for existing in recovered
        ):
            continue
        recovered.append(detection)
    return recovered


def _is_low_signal_supported_full_spike_recovery(
    detection: Detection,
    spike: _GeometryClass,
    block: _GeometryClass,
    patch: _PatchFeatures,
    side_coverage: float,
    run_supported: bool,
) -> bool:
    """Allow only provenance-supported candidates to use the weaker gate."""
    return bool(
        detection.kind == "full_spike_supported"
        and run_supported
        and detection.score >= FULL_SPIKE_SUPPORTED_RECOVERY_MIN_SCORE
        and spike.score >= FULL_SPIKE_SUPPORTED_RECOVERY_MIN_SHAPE_SCORE
        and side_coverage >= FULL_SPIKE_SUPPORTED_RECOVERY_MIN_SIDE_COVERAGE
        and patch.edge_density >= FULL_SPIKE_SUPPORTED_RECOVERY_MIN_EDGE_DENSITY
        and block.score <= FULL_SPIKE_RECALL_RECOVERY_MAX_BLOCK_SCORE
        and spike.outline_delta >= FULL_SPIKE_RECALL_RECOVERY_MIN_OUTLINE_DELTA
        and spike.direction_margin
        >= FULL_SPIKE_SUPPORTED_RECOVERY_MIN_DIRECTION_MARGIN
    )


def _prune_final_full_spike_recovery_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Remove re-added support markers that remain block-dominant."""
    return [
        detection
        for detection in detections
        if not _is_block_heavy_full_spike_support_noise(detection, image, room)
    ]


def _prune_low_value_full_spike_recoveries(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    blocks = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    full_spikes = [
        detection for detection in detections if detection.type_id in FULL_SPIKE_TYPES
    ]
    axis_support = _full_spike_axis_support(full_spikes)
    base_offsets = {
        OBJ_SPIKE_UP: (0, GRID_SIZE),
        OBJ_SPIKE_RIGHT: (-GRID_SIZE, 0),
        OBJ_SPIKE_LEFT: (GRID_SIZE, 0),
        OBJ_SPIKE_DOWN: (0, -GRID_SIZE),
    }
    directions = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    primary_kinds = {"spike_up", "spike_right", "spike_left", "spike_down"}
    support_recovery_kinds = {
        "full_spike_shape_recovery",
        "full_spike_support",
    }
    kept: list[Detection] = []
    for detection in detections:
        shape_recovery = detection.kind.startswith("full_spike_shape_recovery")
        if (
            not shape_recovery
            and detection.kind not in primary_kinds | support_recovery_kinds | {
                "full_spike_gap",
                "full_spike_raw_primary_recovery",
            }
        ):
            kept.append(detection)
            continue
        patch = _patch_features(
            image,
            room,
            detection.x,
            detection.y,
            GRID_SIZE,
        )
        spike = _classify_full_spike(patch)
        block = _classify_block(patch)
        classifier_failed = spike is None or spike.type_id != detection.type_id
        base_dx, base_dy = base_offsets[detection.type_id]
        base_supported = (
            detection.x + base_dx,
            detection.y + base_dy,
        ) in blocks
        if detection.kind in support_recovery_kinds or shape_recovery:
            direction = directions[detection.type_id]
            min_side_coverage = _triangle_min_side_coverage(patch, direction)
            base_edge_coverage = _triangle_base_edge_coverage(patch, direction)
            low_center_shape = patch.center_score <= 0.16
            stripe_texture_impostor = (
                _has_repeated_horizontal_edge_bands(
                    image,
                    room,
                    detection.x,
                    detection.y,
                )
                and (
                    base_edge_coverage >= 0.90
                    or classifier_failed
                )
            )
            coherent_weak_left = (
                detection.type_id == OBJ_SPIKE_LEFT
                and min_side_coverage >= 0.875
                and 0.53 <= detection.score <= 0.54
                and block.score <= 0.47
            )
            if stripe_texture_impostor:
                continue
            if (
                min_side_coverage >= 1.0
                or base_edge_coverage <= 0.375
                or base_supported
                or axis_support.get(id(detection), False)
                or low_center_shape
                or coherent_weak_left
            ):
                kept.append(detection)
            continue
        if detection.kind in primary_kinds:
            side_coverage = _triangle_side_coverage(
                patch,
                directions[detection.type_id],
            )
            min_side_coverage = _triangle_min_side_coverage(
                patch,
                directions[detection.type_id],
            )
            base_edge_coverage = _triangle_base_edge_coverage(
                patch,
                directions[detection.type_id],
            )
            direction_margin = (
                spike.direction_margin
                if spike is not None and spike.type_id == detection.type_id
                else -1.0
            )
            if _is_low_value_primary_full_spike_geometry(
                detection.type_id,
                detection.score,
                min_side_coverage,
                base_edge_coverage,
                direction_margin,
                patch.center_score,
                block.score,
                base_supported,
            ):
                continue
            high_score_low_block = (
                detection.score >= 0.70 and block.score <= 0.34
            )
            failed_up_profile = (
                detection.type_id == OBJ_SPIKE_UP
                and classifier_failed
                and 0.47 <= detection.score <= 0.55
                and patch.edge_density >= 0.30
                and block.score <= 0.41
            )
            weak_down_outline = (
                detection.type_id == OBJ_SPIKE_DOWN
                and 0.32 <= detection.score <= 0.35
                and side_coverage >= 0.50
                and spike is not None
                and spike.type_id == detection.type_id
                and spike.outline_delta >= 0.30
                and patch.edge_density <= 0.24
                and block.score <= 0.26
            )
            if (
                min_side_coverage >= 0.75
                or base_supported
                or axis_support.get(id(detection), False)
                or high_score_low_block
                or failed_up_profile
                or weak_down_outline
            ):
                kept.append(detection)
            continue
        if detection.kind == "full_spike_raw_primary_recovery":
            if (classifier_failed and block.score <= 0.46) or base_supported:
                kept.append(detection)
            continue
        if (
            detection.type_id == OBJ_SPIKE_UP
            and classifier_failed
            and block.score <= 0.40
            and axis_support.get(id(detection), False)
        ):
            kept.append(detection)
    return _prune_competing_full_spike_orientations(kept, image, room)


def _has_repeated_horizontal_edge_bands(
    image: RGBImage,
    room: Box,
    map_x: int,
    map_y: int,
) -> bool:
    """Detect repeated full-width bands around a candidate spike cell.

    Striped platform and wall textures can produce a convincing triangle
    score at a half-cell boundary.  A real spike has diagonal/isolated edges;
    repeated horizontal bands instead span most of a surrounding two-cell
    neighborhood.  Sampling luminance makes this independent of the
    platform's palette and screenshot brightness.
    """

    sample_size = 24
    colors = _sample_map_patch_colors(
        image,
        room,
        map_x - GRID_SIZE // 2,
        map_y - GRID_SIZE // 2,
        GRID_SIZE * 2,
        sample_size=sample_size,
    )
    gray = [
        (red * 30 + green * 59 + blue * 11) // 100
        for red, green, blue in colors
    ]
    horizontal_edge_rows = 0
    for row in range(sample_size - 1):
        edge_share = sum(
            abs(
                gray[(row + 1) * sample_size + column]
                - gray[row * sample_size + column]
            )
            >= 34
            for column in range(sample_size)
        ) / sample_size
        if edge_share >= 0.75:
            horizontal_edge_rows += 1
    return horizontal_edge_rows >= 2


def _is_low_value_primary_full_spike_geometry(
    type_id: int,
    score: float,
    min_side_coverage: float,
    base_edge_coverage: float,
    direction_margin: float,
    center_score: float,
    block_score: float,
    base_supported: bool,
) -> bool:
    """Reject primary candidates with multiple independent shape defects."""
    empty_center_directionless = (
        base_edge_coverage >= 0.25
        and direction_margin <= 0.04
        and center_score <= 0.20
    )
    block_like_closed_shape = (
        min_side_coverage <= 0.875
        and base_edge_coverage >= 0.75
        and block_score >= 0.50
    )
    low_score_closed_shape = (
        score <= 0.60
        and base_edge_coverage >= 1.0
        and center_score >= 0.30
    )
    unsupported_weak_left = (
        type_id == OBJ_SPIKE_LEFT
        and not base_supported
        and min_side_coverage <= 0.75
    )
    incomplete_low_block_shape = (
        min_side_coverage <= 0.75
        and base_edge_coverage >= 0.375
        and block_score <= 0.25
    )
    weak_block_like_horizontal = (
        type_id in (OBJ_SPIKE_RIGHT, OBJ_SPIKE_LEFT)
        and score <= 0.55
        and block_score >= 0.45
    )
    return (
        empty_center_directionless
        or block_like_closed_shape
        or low_score_closed_shape
        or unsupported_weak_left
        or incomplete_low_block_shape
        or weak_block_like_horizontal
    )


def _prune_competing_full_spike_orientations(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    primary_kinds = {"spike_up", "spike_right", "spike_left", "spike_down"}
    full_spikes = [
        detection for detection in detections if detection.type_id in FULL_SPIKE_TYPES
    ]
    if not full_spikes:
        return detections

    blocks = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    axis_support = _full_spike_axis_support(full_spikes)
    base_offsets = {
        OBJ_SPIKE_UP: (0, GRID_SIZE),
        OBJ_SPIKE_RIGHT: (-GRID_SIZE, 0),
        OBJ_SPIKE_LEFT: (GRID_SIZE, 0),
        OBJ_SPIKE_DOWN: (0, -GRID_SIZE),
    }
    directions = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }

    qualities: dict[int, float] = {}
    protected: set[int] = set()
    for detection in full_spikes:
        patch = _patch_features(
            image,
            room,
            detection.x,
            detection.y,
            GRID_SIZE,
        )
        spike = _classify_full_spike(patch)
        block = _classify_block(patch)
        classifier_matches = spike is not None and spike.type_id == detection.type_id
        direction_margin = spike.direction_margin if classifier_matches else -1.0
        outline_delta = spike.outline_delta if classifier_matches else -1.0
        side_coverage = _triangle_side_coverage(
            patch,
            directions[detection.type_id],
        )
        min_side_coverage = _triangle_min_side_coverage(
            patch,
            directions[detection.type_id],
        )
        base_edge_coverage = _triangle_base_edge_coverage(
            patch,
            directions[detection.type_id],
        )
        base_dx, base_dy = base_offsets[detection.type_id]
        base_supported = (
            detection.x + base_dx,
            detection.y + base_dy,
        ) in blocks
        classifier_failed_high_score = (
            not classifier_matches and detection.score >= 0.70
        )
        qualities[id(detection)] = (
            2.91 * side_coverage
            + 0.999 * outline_delta
            - 0.344 * direction_margin
            + 0.892 * detection.score
            + 2.815 * (1.0 - block.score)
            + 1.081 * float(base_supported)
            + 0.093 * float(axis_support.get(id(detection), False))
            - base_edge_coverage
            + 0.5 * float(classifier_failed_high_score)
        )
        if (
            detection.kind in primary_kinds
            and not classifier_matches
            and detection.score >= 0.75
            and min_side_coverage >= 1.0
            and patch.center_score >= 0.90
        ):
            protected.add(id(detection))

    accepted: list[Detection] = []
    for detection in sorted(
        full_spikes,
        key=lambda item: qualities[id(item)],
        reverse=True,
    ):
        if (
            detection.kind in primary_kinds
            and id(detection) not in protected
            and any(
                other.type_id != detection.type_id
                and math.dist(
                    (detection.x, detection.y),
                    (other.x, other.y),
                )
                <= 16.0
                and qualities[id(other)] - qualities[id(detection)] >= 0.75
                for other in accepted
            )
        ):
            continue
        accepted.append(detection)

    accepted_ids = {id(detection) for detection in accepted}
    return [
        detection
        for detection in detections
        if detection.type_id not in FULL_SPIKE_TYPES
        or id(detection) in accepted_ids
    ]


def _is_block_heavy_full_spike_support_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
) -> bool:
    if detection.kind != "full_spike_support":
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    block = _classify_block(patch)
    return bool(
        spike is not None
        and spike.type_id == detection.type_id
        and block.score >= FULL_SPIKE_FINAL_RECOVERY_MAX_BLOCK_SCORE
        and spike.direction_margin < FULL_SPIKE_FINAL_RECOVERY_MAX_DIRECTION_MARGIN
    )


def _prune_full_spike_shape_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Keep only off-grid support markers that belong to a spike run."""
    support_candidates = [
        detection
        for detection in detections
        if detection.kind == "full_spike_support"
    ]
    support_neighbor_counts = {
        id(detection): _count_full_spike_perpendicular_neighbors(
            detection,
            support_candidates,
        )
        for detection in support_candidates
    }
    kept = [
        detection
        for detection in detections
        if detection.kind != "full_spike_support"
        or (
            support_neighbor_counts[id(detection)]
            >= FULL_SPIKE_FINAL_SUPPORT_MIN_PERPENDICULAR_NEIGHBORS
            and not _is_weak_two_neighbor_support_noise(
                detection,
                image,
                room,
                support_neighbor_counts[id(detection)],
            )
        )
        or _is_strong_full_spike_support(
            detection,
            image,
            room,
            support_neighbor_counts[id(detection)],
        )
    ]
    kept = [
        detection
        for detection in kept
        if not _is_ambiguous_right_full_spike_noise(detection, image, room)
    ]
    kept = [
        detection
        for detection in kept
        if not _is_ambiguous_full_spike_noise(detection, image, room)
    ]
    return _prune_isolated_weak_full_spike_noise(kept, image, room)


def _prune_primary_isolated_full_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Reject weak primary spikes that lack a coherent run or side shape."""
    full_spikes = [
        detection for detection in detections if detection.type_id in FULL_SPIKE_TYPES
    ]
    axis_support = _full_spike_axis_support(full_spikes)
    return [
        detection
        for detection in detections
        if not _is_primary_isolated_full_spike_noise(
            detection,
            axis_support.get(id(detection), False),
            image,
            room,
        )
    ]


def _is_primary_isolated_full_spike_noise(
    detection: Detection,
    axis_support: bool,
    image: RGBImage,
    room: Box,
) -> bool:
    if (
        detection.type_id not in FULL_SPIKE_TYPES
        or detection.kind not in {
            "spike_up",
            "spike_right",
            "spike_left",
            "spike_down",
        }
        or detection.score >= FULL_SPIKE_PRIMARY_ISOLATED_PRUNE_MAX_SCORE
        or axis_support
    ):
        return False
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    direction = direction_by_type[detection.type_id]
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    if (
        spike is not None
        and spike.type_id == detection.type_id
        and spike.outline_delta >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_MIN_OUTLINE_DELTA
        and (
            spike.direction_margin
            >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_MIN_DIRECTION_MARGIN
            or (
                spike.direction_margin
                >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_FALLBACK_MIN_DIRECTION_MARGIN
                and patch.edge_density
                >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_MIN_EDGE_DENSITY
            )
        )
    ):
        return False
    block = _classify_block(patch)
    side_coverage = _triangle_side_coverage(patch, direction)
    if (
        detection.score >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_MIN_SCORE
        and patch.edge_density
        >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_PROFILE_MIN_EDGE_DENSITY
        and side_coverage
        >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_PROFILE_MIN_SIDE_COVERAGE
        and (
            block.score <= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_PROFILE_MAX_BLOCK_SCORE
            or side_coverage
            >= FULL_SPIKE_PRIMARY_ISOLATED_KEEP_PROFILE_STRONG_SIDE_COVERAGE
        )
    ):
        return False
    return (
        side_coverage < FULL_SPIKE_PRIMARY_ISOLATED_PRUNE_MIN_SIDE_COVERAGE
        or block.score > FULL_SPIKE_PRIMARY_ISOLATED_PRUNE_MAX_BLOCK_SCORE
    )


def _is_weak_two_neighbor_support_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
    perpendicular_neighbors: int,
) -> bool:
    """Reject block-heavy two-neighbor markers with weak direction evidence."""
    if (
        detection.kind != "full_spike_support"
        or perpendicular_neighbors != FULL_SPIKE_SUPPORT_MIN_PERPENDICULAR_NEIGHBORS
    ):
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    block = _classify_block(patch)
    return bool(
        spike is not None
        and spike.type_id == detection.type_id
        and block.score >= 0.55
        and spike.direction_margin < 0.10
    )


def _has_full_spike_perpendicular_neighbor(
    detection: Detection,
    full_spikes: list[Detection],
) -> bool:
    """Require a same-direction neighbor along the spike run axis."""
    return _count_full_spike_perpendicular_neighbors(detection, full_spikes) >= 1


def _count_full_spike_perpendicular_neighbors(
    detection: Detection,
    full_spikes: list[Detection],
) -> int:
    """Count same-direction candidates along the perpendicular run axis."""
    if detection.type_id not in FULL_SPIKE_TYPES:
        return 0
    count = 0
    for other in full_spikes:
        if other is detection or other.type_id != detection.type_id:
            continue
        if detection.type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN):
            aligned = other.y == detection.y
            run_distance = abs(other.x - detection.x)
        else:
            aligned = other.x == detection.x
            run_distance = abs(other.y - detection.y)
        if (
            aligned
            and 8 < run_distance <= FULL_SPIKE_RUN_NEIGHBOR_MAX_DISTANCE
        ):
            count += 1
    return count


def _is_strong_full_spike_support(
    detection: Detection,
    image: RGBImage,
    room: Box,
    perpendicular_neighbors: int,
) -> bool:
    """Recover an unanchored support marker only with a clear triangle shape."""
    if detection.type_id not in FULL_SPIKE_TYPES:
        return False
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    if spike is None or spike.type_id != detection.type_id:
        return False
    block = _classify_block(patch)
    side_coverage = _triangle_side_coverage(
        patch,
        direction_by_type[detection.type_id],
    )
    if (
        spike.direction_margin >= FULL_SPIKE_STRONG_SUPPORT_MIN_DIRECTION_MARGIN
        and side_coverage >= FULL_SPIKE_STRONG_SUPPORT_MIN_SIDE_COVERAGE
        and block.score <= FULL_SPIKE_STRONG_SUPPORT_MAX_BLOCK_SCORE
    ):
        return True
    if (
        perpendicular_neighbors == 0
        and spike.direction_margin >= FULL_SPIKE_STRONG_SUPPORT_MIN_DIRECTION_MARGIN
        and side_coverage >= FULL_SPIKE_UNANCHORED_SUPPORT_MIN_SIDE_COVERAGE
    ):
        return True
    if (
        perpendicular_neighbors == 0
        and side_coverage >= FULL_SPIKE_ISOLATED_SUPPORT_MIN_SIDE_COVERAGE
        and patch.center_score >= FULL_SPIKE_ISOLATED_SUPPORT_MIN_CENTER_SCORE
    ):
        return True
    return bool(
        perpendicular_neighbors == 1
        and spike.direction_margin
        >= FULL_SPIKE_SINGLE_NEIGHBOR_SUPPORT_MIN_DIRECTION_MARGIN
        and side_coverage >= FULL_SPIKE_SINGLE_NEIGHBOR_SUPPORT_MIN_SIDE_COVERAGE
    )


def _is_ambiguous_right_full_spike_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
) -> bool:
    """Reject right-facing texture with weak orientation evidence."""
    if detection.type_id != OBJ_SPIKE_RIGHT:
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    return bool(
        spike is not None
        and spike.type_id == OBJ_SPIKE_RIGHT
        and spike.direction_margin < FULL_SPIKE_AMBIGUOUS_RIGHT_MAX_DIRECTION_MARGIN
        and patch.edge_density >= FULL_SPIKE_AMBIGUOUS_RIGHT_MIN_EDGE_DENSITY
    )


def _is_ambiguous_full_spike_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
) -> bool:
    if (
        detection.type_id not in FULL_SPIKE_TYPES
        or detection.score >= FULL_SPIKE_AMBIGUOUS_MAX_SCORE
    ):
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    return bool(
        spike is not None
        and spike.type_id == detection.type_id
        and spike.direction_margin < FULL_SPIKE_AMBIGUOUS_RIGHT_MAX_DIRECTION_MARGIN
        and patch.edge_density >= FULL_SPIKE_AMBIGUOUS_RIGHT_MIN_EDGE_DENSITY
    )


def _prune_isolated_weak_full_spike_noise(
    detections: list[Detection],
    image: RGBImage | None = None,
    room: Box | None = None,
) -> list[Detection]:
    """Remove weak full spikes unless nearby geometry supports them."""
    full_spikes = [
        detection for detection in detections if detection.type_id in FULL_SPIKE_TYPES
    ]
    return [
        detection
        for detection in detections
        if detection.type_id not in FULL_SPIKE_TYPES
        or detection.score >= FULL_SPIKE_ISOLATED_WEAK_MAX_SCORE
        or _has_full_spike_nearby_neighbors(
            detection,
            full_spikes,
            FULL_SPIKE_ISOLATED_WEAK_MIN_NEIGHBORS,
        )
        or (
            detection.score >= FULL_SPIKE_ISOLATED_WEAK_ONE_NEIGHBOR_MIN_SCORE
            and _has_full_spike_nearby_neighbor(detection, full_spikes)
        )
        or (
            image is not None
            and room is not None
            and _is_weak_full_spike_shape_recovery(detection, image, room)
        )
    ]


def _prune_isolated_weak_full_spike_shape_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Reject weak isolated shapes unless their local triangle is coherent."""
    full_spikes = [
        detection for detection in detections if detection.type_id in FULL_SPIKE_TYPES
    ]
    axis_support = _full_spike_axis_support(full_spikes)
    return [
        detection
        for detection in detections
        if not _is_isolated_weak_full_spike_shape_noise(
            detection,
            axis_support.get(id(detection), False),
            image,
            room,
        )
    ]


def _full_spike_axis_support(
    full_spikes: list[Detection],
) -> dict[int, bool]:
    grouped: dict[tuple[int, int], list[Detection]] = defaultdict(list)
    for detection in full_spikes:
        axis = (
            detection.y
            if detection.type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN)
            else detection.x
        )
        grouped[(detection.type_id, axis)].append(detection)
    support: dict[int, bool] = {}
    for detection in full_spikes:
        axis = (
            detection.y
            if detection.type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN)
            else detection.x
        )
        has_neighbor = False
        for other in grouped[(detection.type_id, axis)]:
            if other is detection:
                continue
            run_distance = (
                abs(other.x - detection.x)
                if detection.type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN)
                else abs(other.y - detection.y)
            )
            if 0 < run_distance <= FULL_SPIKE_RUN_NEIGHBOR_MAX_DISTANCE:
                has_neighbor = True
        support[id(detection)] = has_neighbor
    return support


def _is_isolated_weak_full_spike_shape_noise(
    detection: Detection,
    axis_support: bool,
    image: RGBImage,
    room: Box,
) -> bool:
    if (
        detection.type_id not in FULL_SPIKE_TYPES
        or detection.kind == "full_spike_support"
        or detection.score >= FULL_SPIKE_ISOLATED_SHAPE_PRUNE_MAX_SCORE
    ):
        return False
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    direction = direction_by_type[detection.type_id]
    if axis_support:
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    block = _classify_block(patch)
    side_coverage = _triangle_side_coverage(patch, direction)
    if spike is None or spike.type_id != detection.type_id:
        return True
    if block.score > FULL_SPIKE_ISOLATED_SHAPE_MAX_BLOCK_SCORE:
        return True
    return (
        spike.direction_margin < FULL_SPIKE_ISOLATED_SHAPE_MAX_DIRECTION_MARGIN
        and side_coverage < FULL_SPIKE_ISOLATED_SHAPE_MIN_SIDE_COVERAGE
    )


def _is_weak_full_spike_shape_recovery(
    detection: Detection,
    image: RGBImage,
    room: Box,
) -> bool:
    """Keep a weak isolated spike only when its local triangle is coherent."""
    if (
        detection.kind == "full_spike_support"
        or detection.score < FULL_SPIKE_WEAK_SHAPE_MIN_SCORE
        or detection.score >= FULL_SPIKE_ISOLATED_WEAK_MAX_SCORE
    ):
        return False
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    direction = direction_by_type.get(detection.type_id)
    if direction is None:
        return False
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    block = _classify_block(patch)
    return bool(
        spike is not None
        and spike.type_id == detection.type_id
        and spike.direction_margin >= FULL_SPIKE_WEAK_SHAPE_MIN_DIRECTION_MARGIN
        and _triangle_side_coverage(patch, direction)
        >= FULL_SPIKE_WEAK_SHAPE_MIN_SIDE_COVERAGE
        and patch.edge_density >= FULL_SPIKE_WEAK_SHAPE_MIN_EDGE_DENSITY
        and block.score <= FULL_SPIKE_WEAK_SHAPE_MAX_BLOCK_SCORE
    )


def _has_full_spike_nearby_neighbor(
    detection: Detection,
    full_spikes: list[Detection],
) -> bool:
    """Treat a nearby same-direction candidate as support for a weak spike."""
    return any(
        other is not detection
        and other.type_id == detection.type_id
        and distance((detection.x, detection.y), (other.x, other.y))
        <= FULL_SPIKE_ISOLATED_NEIGHBOR_DISTANCE
        for other in full_spikes
    )


def _has_full_spike_nearby_neighbors(
    detection: Detection,
    full_spikes: list[Detection],
    minimum: int,
) -> bool:
    return sum(
        1
        for other in full_spikes
        if other is not detection
        and other.type_id == detection.type_id
        and distance((detection.x, detection.y), (other.x, other.y))
        <= FULL_SPIKE_ISOLATED_NEIGHBOR_DISTANCE
    ) >= minimum


def _is_strong_full_spike_shape(
    detection: Detection,
    image: RGBImage,
    room: Box,
    directions: dict[int, str],
) -> bool:
    patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
    spike = _classify_full_spike(patch)
    return bool(
        spike is not None
        and spike.direction_margin >= FULL_SPIKE_MIN_OUTPUT_DIRECTION_MARGIN
        and _triangle_side_coverage(patch, directions[detection.type_id])
        >= FULL_SPIKE_MIN_SIDE_COVERAGE
    )


def _has_full_spike_axis_continuation_anchor(
    detection: Detection,
    strong_candidates: list[Detection],
) -> bool:
    return any(
        other.type_id == detection.type_id
        and (
            (
                other.x == detection.x
                and 0 < abs(other.y - detection.y)
                <= FULL_SPIKE_CONTINUATION_MAX_AXIS_DISTANCE
            )
            or (
                other.y == detection.y
                and 0 < abs(other.x - detection.x)
                <= FULL_SPIKE_CONTINUATION_MAX_AXIS_DISTANCE
            )
        )
        for other in strong_candidates
    )


def _prune_isolated_weak_block_noise(detections: list[Detection]) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < ISOLATED_WEAK_BLOCK_PRUNE_MIN_BLOCK_COUNT:
        return detections
    remove_ids: set[int] = set()
    for detection in blocks:
        if detection.score >= ISOLATED_WEAK_BLOCK_PRUNE_MAX_SCORE:
            continue
        axis_support = sum(
            1
            for other in blocks
            if other is not detection
            and (
                (other.x == detection.x and abs(other.y - detection.y) == 32)
                or (other.y == detection.y and abs(other.x - detection.x) == 32)
            )
        )
        nearby_blocks = sum(
            1
            for other in blocks
            if other is not detection
            and distance((other.x, other.y), (detection.x, detection.y)) <= 40
        )
        if (
            axis_support <= ISOLATED_WEAK_BLOCK_PRUNE_MAX_AXIS_SUPPORT
            and nearby_blocks <= ISOLATED_WEAK_BLOCK_PRUNE_MAX_NEARBY_BLOCKS
        ):
            remove_ids.add(id(detection))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _prune_sparse_off_grid_block_noise(detections: list[Detection]) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < OFF_GRID_BLOCK_PRUNE_MIN_BLOCK_COUNT:
        return detections
    off_grid = [
        detection
        for detection in blocks
        if not _is_block_aligned_to(detection.x, detection.y, BLOCK_ALIGNMENT_STEP)
    ]
    if len(off_grid) / len(blocks) > OFF_GRID_BLOCK_PRUNE_MAX_RATIO:
        return detections
    remove_ids = {id(detection) for detection in off_grid}
    return [detection for detection in detections if id(detection) not in remove_ids]


def _prune_dark_outline_low_signal_blocks(detections: list[Detection]) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < DARK_OUTLINE_BLOCK_PRUNE_MIN_BLOCK_COUNT:
        return detections
    return [
        detection
        for detection in detections
        if detection.type_id != OBJ_BLOCK
        or detection.score >= DARK_OUTLINE_BLOCK_PRUNE_SCORE_THRESHOLD
    ]


def _prune_low_signal_block_patches(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Drop texture-free block patches in dense, non-dark-outline rooms."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if (
        len(blocks) < LOW_SIGNAL_BLOCK_PATCH_PRUNE_MIN_BLOCK_COUNT
        or _is_dark_outline_room(image, room)
    ):
        return detections
    remove_ids = set()
    for detection in blocks:
        patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
        if (
            patch.edge_density < LOW_SIGNAL_BLOCK_PATCH_PRUNE_MAX_EDGE
            and patch.center_score < LOW_SIGNAL_BLOCK_PATCH_PRUNE_MAX_CENTER
        ):
            remove_ids.add(id(detection))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _recover_low_signal_boundary_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover faint boundary cells supported by an adjacent block run."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BLOCK_COUNT:
        return detections
    if _is_dark_outline_room(image, room):
        return detections
    if not _has_mixed_grid_block_population(blocks):
        return detections
    positions = {(detection.x, detection.y) for detection in blocks}
    recovered = list(detections)
    boundary_positions = set()
    for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
        boundary_positions.add((x, 0))
        boundary_positions.add((x, ROOM_HEIGHT - GRID_SIZE))
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        boundary_positions.add((0, y))
        boundary_positions.add((ROOM_WIDTH - GRID_SIZE, y))
    for x, y in sorted(boundary_positions):
        if (x, y) in positions:
            continue
        has_neighbor = any(
            position in positions
            for position in ((x - GRID_SIZE, y), (x + GRID_SIZE, y), (x, y - GRID_SIZE), (x, y + GRID_SIZE))
        )
        is_boundary = x in (0, ROOM_WIDTH - GRID_SIZE) or y in (0, ROOM_HEIGHT - GRID_SIZE)
        if not has_neighbor and not is_boundary:
            continue
        patch = _patch_features(image, room, x, y, GRID_SIZE)
        if not (
            patch.edge_density >= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_EDGE
            and patch.border_score >= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BORDER
            and patch.center_score <= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MAX_CENTER
        ):
            continue
        block = _classify_block(patch)
        recovered.append(
            _geometry_detection(
                "block",
                OBJ_BLOCK,
                x,
                y,
                max(BLOCK_RUN_GAP_SCORE, block.score),
                image,
                room,
                GRID_SIZE,
            )
        )
        positions.add((x, y))
    continuation_positions = set()
    for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
        continuation_positions.add((x, GRID_SIZE))
        continuation_positions.add((x, ROOM_HEIGHT - GRID_SIZE * 2))
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        continuation_positions.add((GRID_SIZE, y))
        continuation_positions.add((ROOM_WIDTH - GRID_SIZE * 2, y))
    for x, y in sorted(continuation_positions):
        if (x, y) in positions:
            continue
        if not any(
            position in positions
            for position in ((x - GRID_SIZE, y), (x + GRID_SIZE, y), (x, y - GRID_SIZE), (x, y + GRID_SIZE))
        ):
            continue
        patch = _patch_features(image, room, x, y, GRID_SIZE)
        if not (
            patch.edge_density >= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_EDGE
            and patch.border_score >= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BORDER
            and patch.center_score <= LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MAX_CENTER
        ):
            continue
        block = _classify_block(patch)
        recovered.append(
            _geometry_detection(
                "block",
                OBJ_BLOCK,
                x,
                y,
                max(BLOCK_RUN_GAP_SCORE, block.score),
                image,
                room,
                GRID_SIZE,
            )
        )
        positions.add((x, y))
    return recovered


def _recover_low_signal_supported_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover faint block patches with one aligned structural neighbor."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BLOCK_COUNT:
        return detections
    if _is_dark_outline_room(image, room):
        return detections
    if not _has_mixed_grid_block_population(blocks):
        return detections
    positions = {(detection.x, detection.y) for detection in blocks}
    recovered = list(detections)
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            if (x, y) in positions:
                continue
            if not any(
                position in positions
                for position in ((x - GRID_SIZE, y), (x + GRID_SIZE, y), (x, y - GRID_SIZE), (x, y + GRID_SIZE))
            ):
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            block = _classify_block(patch)
            if not (
                block.score >= LOW_SIGNAL_SUPPORTED_BLOCK_RECOVERY_MIN_SCORE
                and patch.edge_density >= LOW_SIGNAL_SUPPORTED_BLOCK_RECOVERY_MIN_EDGE
                and patch.border_score >= LOW_SIGNAL_SUPPORTED_BLOCK_RECOVERY_MIN_BORDER
                and patch.center_score <= LOW_SIGNAL_SUPPORTED_BLOCK_RECOVERY_MAX_CENTER
            ):
                continue
            recovered.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    max(BLOCK_RUN_GAP_SCORE, block.score),
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            positions.add((x, y))
    return recovered


def _recover_low_signal_fuzzy_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover strong-border cells near an offset block candidate."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BLOCK_COUNT:
        return detections
    if _is_dark_outline_room(image, room) or not _has_mixed_grid_block_population(blocks):
        return detections
    positions = {(detection.x, detection.y) for detection in blocks}
    recovered = list(detections)
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            if (x, y) in positions:
                continue
            if not any(
                distance((x, y), (detection.x, detection.y))
                <= LOW_SIGNAL_FUZZY_BLOCK_RECOVERY_MAX_DISTANCE
                for detection in blocks
            ):
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            if not (
                patch.edge_density >= LOW_SIGNAL_FUZZY_BLOCK_RECOVERY_MIN_EDGE
                and patch.border_score >= LOW_SIGNAL_FUZZY_BLOCK_RECOVERY_MIN_BORDER
                and patch.center_score <= LOW_SIGNAL_FUZZY_BLOCK_RECOVERY_MAX_CENTER
            ):
                continue
            block = _classify_block(patch)
            recovered.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    max(BLOCK_RUN_GAP_SCORE, block.score),
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            positions.add((x, y))
    return recovered


def _recover_low_signal_bottom_boundary_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover strong-border cells on the bottom boundary of mixed-grid rooms."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < LOW_SIGNAL_BOUNDARY_BLOCK_RECOVERY_MIN_BLOCK_COUNT:
        return detections
    if _is_dark_outline_room(image, room) or not _has_mixed_grid_block_population(blocks):
        return detections
    positions = {(detection.x, detection.y) for detection in blocks}
    recovered = list(detections)
    y = ROOM_HEIGHT - GRID_SIZE
    for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
        if (x, y) in positions:
            continue
        patch = _patch_features(image, room, x, y, GRID_SIZE)
        if not (
            patch.edge_density >= LOW_SIGNAL_BOTTOM_BOUNDARY_RECOVERY_MIN_EDGE
            and patch.border_score >= LOW_SIGNAL_BOTTOM_BOUNDARY_RECOVERY_MIN_BORDER
            and patch.center_score <= LOW_SIGNAL_BOTTOM_BOUNDARY_RECOVERY_MAX_CENTER
        ):
            continue
        block = _classify_block(patch)
        recovered.append(
            _geometry_detection(
                "block",
                OBJ_BLOCK,
                x,
                y,
                max(BLOCK_RUN_GAP_SCORE, block.score),
                image,
                room,
                GRID_SIZE,
            )
        )
        positions.add((x, y))
    return recovered


def _has_mixed_grid_block_population(blocks: list[Detection]) -> bool:
    if not blocks:
        return False
    offset_count = sum(
        not _is_block_aligned_to(
            detection.x,
            detection.y,
            PREFERRED_BLOCK_ALIGNMENT_STEP,
        )
        for detection in blocks
    )
    return offset_count / len(blocks) >= LOW_SIGNAL_MIXED_GRID_MIN_OFFSET_RATIO


def _recover_dark_outline_supported_low_signal_blocks(
    candidates: list[Detection],
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    block_positions = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    recovered = list(detections)
    for candidate in candidates:
        if candidate.type_id != OBJ_BLOCK:
            continue
        if candidate.score >= DARK_OUTLINE_BLOCK_PRUNE_SCORE_THRESHOLD:
            continue
        position = (candidate.x, candidate.y)
        if position in block_positions:
            continue
        if candidate.x < 0:
            recovered.append(candidate)
            block_positions.add(position)
            continue
        patch = _patch_features(image, room, candidate.x, candidate.y, GRID_SIZE)
        if not (
            patch.edge_density >= DARK_OUTLINE_SUPPORTED_LOW_BLOCK_MIN_EDGE
            and patch.border_score >= DARK_OUTLINE_SUPPORTED_LOW_BLOCK_MIN_BORDER
            and patch.center_score <= DARK_OUTLINE_SUPPORTED_LOW_BLOCK_MAX_CENTER
        ):
            continue
        recovered.append(candidate)
        block_positions.add(position)
    return recovered


def _recover_dark_outline_center_heavy_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover 32px cells whose strong center texture was masked by a spike."""
    recovered = list(detections)
    block_positions = {
        (detection.x, detection.y)
        for detection in recovered
        if detection.type_id == OBJ_BLOCK
    }
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            if (x, y) in block_positions:
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            block = _classify_block(patch)
            if not (
                block.score >= DARK_OUTLINE_CENTER_HEAVY_BLOCK_MIN_SCORE
                and patch.edge_density >= DARK_OUTLINE_CENTER_HEAVY_BLOCK_MIN_EDGE
                and patch.center_score >= DARK_OUTLINE_CENTER_HEAVY_BLOCK_MIN_CENTER
            ):
                continue
            recovered.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    block.score,
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            block_positions.add((x, y))
    return recovered


def _recover_dark_outline_low_signal_run_gaps(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Fill faint cells enclosed by a same-axis two-cell block run."""
    recovered = list(detections)
    block_positions = {
        (detection.x, detection.y)
        for detection in recovered
        if detection.type_id == OBJ_BLOCK
    }
    for y in range(0, ROOM_HEIGHT - GRID_SIZE + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            if (x, y) in block_positions:
                continue
            has_run = (
                ((x - GRID_SIZE, y) in block_positions and (x - GRID_SIZE * 2, y) in block_positions)
                or ((x + GRID_SIZE, y) in block_positions and (x + GRID_SIZE * 2, y) in block_positions)
                or ((x, y - GRID_SIZE) in block_positions and (x, y - GRID_SIZE * 2) in block_positions)
                or ((x, y + GRID_SIZE) in block_positions and (x, y + GRID_SIZE * 2) in block_positions)
            )
            if not has_run:
                continue
            patch = _patch_features(image, room, x, y, GRID_SIZE)
            if patch.edge_density < DARK_OUTLINE_LOW_SIGNAL_RUN_GAP_MIN_EDGE:
                if not _has_dark_outline_faint_gap_anchor_support(
                    block_positions,
                    image,
                    room,
                    x,
                    y,
                ):
                    continue
            recovered.append(
                _geometry_detection(
                    "block",
                    OBJ_BLOCK,
                    x,
                    y,
                    BLOCK_RUN_GAP_SCORE,
                    image,
                    room,
                    GRID_SIZE,
                )
            )
            block_positions.add((x, y))
    return recovered


def _has_dark_outline_faint_gap_anchor_support(
    block_positions: set[tuple[int, int]],
    image: RGBImage,
    room: Box,
    x: int,
    y: int,
) -> bool:
    """Keep a faint gap only when it is centered in a strong axis run."""
    for dx, dy in ((GRID_SIZE, 0), (0, GRID_SIZE)):
        near_a = (x - dx, y - dy)
        near_b = (x + dx, y + dy)
        far_a = (x - dx * 2, y - dy * 2)
        far_b = (x + dx * 2, y + dy * 2)
        if not all(position in block_positions for position in (near_a, near_b, far_a, far_b)):
            continue
        anchor_scores = []
        for anchor_x, anchor_y in (far_a, far_b):
            if not (0 <= anchor_x <= ROOM_WIDTH - GRID_SIZE and 0 <= anchor_y <= ROOM_HEIGHT - GRID_SIZE):
                continue
            anchor_scores.append(
                _classify_block(
                    _patch_features(image, room, anchor_x, anchor_y, GRID_SIZE)
                ).score
            )
        if anchor_scores and max(anchor_scores) >= DARK_OUTLINE_LOW_SIGNAL_RUN_GAP_MIN_FAINT_ANCHOR_SCORE:
            return True
    return False


def _recover_dark_outline_long_low_signal_runs(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Restore faint candidate cells between strong anchors on long runs."""
    if not _is_dark_outline_room(image, room):
        return detections
    block_positions = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    strong_by_x: defaultdict[int, set[int]] = defaultdict(set)
    strong_by_y: defaultdict[int, set[int]] = defaultdict(set)
    for detection in detections:
        if (
            detection.type_id == OBJ_BLOCK
            and detection.score >= DARK_OUTLINE_LONG_RUN_MIN_ANCHOR_SCORE
        ):
            strong_by_x[detection.x].add(detection.y)
            strong_by_y[detection.y].add(detection.x)

    recovered = list(detections)
    added: list[Detection] = []
    for axis_values, vertical in ((strong_by_x, True), (strong_by_y, False)):
        for fixed, anchors in axis_values.items():
            ordered = sorted(anchors)
            for start, end in zip(ordered, ordered[1:]):
                if end - start < DARK_OUTLINE_LONG_RUN_MIN_ANCHOR_SPAN:
                    continue
                for position in range(start + GRID_SIZE, end, GRID_SIZE):
                    x, y = (fixed, position) if vertical else (position, fixed)
                    if (x, y) in block_positions:
                        continue
                    patch = _patch_features(image, room, x, y, GRID_SIZE)
                    if not (
                        DARK_OUTLINE_LONG_RUN_MIN_CANDIDATE_EDGE
                        <= patch.edge_density
                        < DARK_OUTLINE_LONG_RUN_MAX_CANDIDATE_EDGE
                        and patch.border_score
                        <= DARK_OUTLINE_LONG_RUN_MAX_CANDIDATE_BORDER
                        and patch.center_score
                        <= DARK_OUTLINE_LONG_RUN_MAX_CANDIDATE_CENTER
                    ):
                        continue
                    added.append(
                        _geometry_detection(
                            "block",
                            OBJ_BLOCK,
                            x,
                            y,
                            BLOCK_RUN_GAP_SCORE,
                            image,
                            room,
                            GRID_SIZE,
                        )
                    )
                    block_positions.add((x, y))
    recovered.extend(added)
    return recovered


def _recover_dark_outline_double_run_gaps(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Fill two consecutive faint cells bracketed by a same-axis block run."""
    recovered = list(detections)
    block_positions = {
        (detection.x, detection.y)
        for detection in recovered
        if detection.type_id == OBJ_BLOCK
    }
    for y in range(0, ROOM_HEIGHT - GRID_SIZE * 3 + 1, GRID_SIZE):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, GRID_SIZE):
            vertical = (x, y) in block_positions and (x, y + GRID_SIZE * 3) in block_positions
            horizontal = (x, y) in block_positions and (x + GRID_SIZE * 3, y) in block_positions
            if not (vertical or horizontal):
                continue
            gaps = (
                ((x, y + GRID_SIZE), (x, y + GRID_SIZE * 2))
                if vertical
                else ((x + GRID_SIZE, y), (x + GRID_SIZE * 2, y))
            )
            if any(position in block_positions for position in gaps):
                continue
            patches = [
                _patch_features(image, room, position[0], position[1], GRID_SIZE)
                for position in gaps
            ]
            if any(
                patch.edge_density < DARK_OUTLINE_DOUBLE_RUN_GAP_MIN_EDGE
                for patch in patches
            ):
                continue
            for position in gaps:
                recovered.append(
                    _geometry_detection(
                        "block",
                        OBJ_BLOCK,
                        position[0],
                        position[1],
                        BLOCK_RUN_GAP_SCORE,
                        image,
                        room,
                        GRID_SIZE,
                    )
                )
                block_positions.add(position)
    return recovered


def _prune_dark_outline_off_grid_low_signal_blocks(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Remove weak half-step blocks in a room whose block grid is 32px-dominant."""
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if not blocks or not _is_dark_outline_room(image, room):
        return detections
    remove_ids = set()
    for detection in blocks:
        if _is_block_aligned_to(
            detection.x,
            detection.y,
            PREFERRED_BLOCK_ALIGNMENT_STEP,
        ):
            continue
        patch = _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
        if (
            patch.edge_density < DARK_OUTLINE_OFF_GRID_LOW_SIGNAL_MAX_EDGE
            and patch.center_score < DARK_OUTLINE_OFF_GRID_LOW_SIGNAL_MAX_CENTER
        ):
            remove_ids.add(id(detection))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _prune_adaptive_block_noise(detections: list[Detection]) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < ADAPTIVE_BLOCK_PRUNE_MIN_BLOCK_COUNT:
        return detections
    scores = sorted(detection.score for detection in blocks)
    upper_quartile = scores[len(scores) * 3 // 4]
    if upper_quartile < ADAPTIVE_BLOCK_PRUNE_MIN_UPPER_QUARTILE_SCORE:
        return detections
    return [
        detection
        for detection in detections
        if detection.type_id != OBJ_BLOCK
        or detection.score >= ADAPTIVE_BLOCK_PRUNE_SCORE_THRESHOLD
    ]


def _prune_adaptive_weak_block_noise(detections: list[Detection]) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if len(blocks) < ADAPTIVE_BLOCK_PRUNE_MIN_BLOCK_COUNT:
        return detections
    scores = sorted(detection.score for detection in blocks)
    upper_quartile = scores[len(scores) * 3 // 4]
    if upper_quartile >= ADAPTIVE_WEAK_BLOCK_PRUNE_MIN_UPPER_QUARTILE_SCORE:
        threshold = ADAPTIVE_WEAK_BLOCK_PRUNE_SCORE_THRESHOLD
    elif (
        ADAPTIVE_MID_SIGNAL_BLOCK_PRUNE_MIN_UPPER_QUARTILE_SCORE
        <= upper_quartile
        < ADAPTIVE_MID_SIGNAL_BLOCK_PRUNE_MAX_UPPER_QUARTILE_SCORE
    ):
        threshold = ADAPTIVE_MID_SIGNAL_BLOCK_PRUNE_SCORE_THRESHOLD
    else:
        return detections
    return [
        detection
        for detection in detections
        if detection.type_id != OBJ_BLOCK
        or detection.score >= threshold
        or _is_supported_room_boundary_block(detection, blocks)
    ]


def _is_supported_room_boundary_block(
    detection: Detection,
    blocks: list[Detection],
) -> bool:
    """Keep a clipped edge tile when its adjacent run supports the reading."""
    if detection.score < ADAPTIVE_WEAK_BLOCK_PRUNE_BOUNDARY_SCORE_THRESHOLD:
        return False
    if not (
        detection.x in (0, ROOM_WIDTH - GRID_SIZE)
        or detection.y in (0, ROOM_HEIGHT - GRID_SIZE)
    ):
        return False
    step = ADAPTIVE_WEAK_BLOCK_PRUNE_BOUNDARY_SUPPORT_DISTANCE
    return any(
        other is not detection
        and other.score >= ADAPTIVE_WEAK_BLOCK_PRUNE_BOUNDARY_SCORE_THRESHOLD
        and (
            (other.x == detection.x and abs(other.y - detection.y) == step)
            or (other.y == detection.y and abs(other.x - detection.x) == step)
        )
        for other in blocks
    )


def _prune_recovered_full_spike_noise(detections: list[Detection]) -> list[Detection]:
    normalized = _normalize_full_spike_detections(detections)
    kept_full_spikes: list[Detection] = []
    removed_full_spike_ids: set[int] = set()
    full_spikes = sorted(
        (det for det in normalized if det.type_id in FULL_SPIKE_TYPES),
        key=lambda det: (-det.score, det.y, det.x),
    )
    for detection in full_spikes:
        if detection.score < FULL_SPIKE_FINAL_MIN_SCORE:
            removed_full_spike_ids.add(id(detection))
            continue
        if any(
            detection.type_id == kept.type_id
            and distance((detection.x, detection.y), (kept.x, kept.y))
            < FULL_SPIKE_FINAL_DEDUPE_DISTANCE
            for kept in kept_full_spikes
        ):
            removed_full_spike_ids.add(id(detection))
            continue
        kept_full_spikes.append(detection)
    return [det for det in normalized if id(det) not in removed_full_spike_ids]


def _prune_blocklike_mini_spike_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    detections = _prune_duplicate_mini_spike_cells(detections)
    mini_spikes = [det for det in detections if det.type_id in MINI_SPIKE_TYPES]
    full_spikes = [det for det in detections if det.type_id in FULL_SPIKE_TYPES]
    blocks = [det for det in detections if det.type_id == OBJ_BLOCK]
    return [
        det
        for det in detections
        if not _is_blocklike_mini_spike_noise(
            det,
            image,
            room,
            mini_spikes,
            full_spikes,
            blocks,
        )
        and not _is_residual_mini_spike_noise(
            det,
            image,
            room,
            mini_spikes,
            full_spikes,
            blocks,
        )
    ]


@dataclass(frozen=True, slots=True)
class _TriangleFillFeatures:
    cluster_gap: float
    inside_density: float
    outside_density: float
    density_contrast: float
    luma_contrast: float


def _triangle_fill_features(
    image: RGBImage,
    room: Box,
    map_x: int,
    map_y: int,
    map_size: int,
    direction: str,
) -> _TriangleFillFeatures:
    pixels: list[list[tuple[int, int, int]]] = []
    scale_x = room.width / ROOM_WIDTH
    scale_y = room.height / ROOM_HEIGHT
    for sample_y in range(16):
        image_y = int(
            min(
                image.height - 1,
                max(
                    0,
                    room.y
                    + (map_y + (sample_y + 0.5) * map_size / 16) * scale_y,
                ),
            )
        )
        row: list[tuple[int, int, int]] = []
        for sample_x in range(16):
            image_x = int(
                min(
                    image.width - 1,
                    max(
                        0,
                        room.x
                        + (map_x + (sample_x + 0.5) * map_size / 16)
                        * scale_x,
                    ),
                )
            )
            row.append(image.pixel(image_x, image_y))
        pixels.append(row)

    luma_values = [sum(pixel) / 3 for row in pixels for pixel in row]
    low = min(luma_values)
    high = max(luma_values)
    for _ in range(12):
        midpoint = (low + high) / 2
        lower = [value for value in luma_values if value < midpoint]
        upper = [value for value in luma_values if value >= midpoint]
        if not lower or not upper:
            break
        low = sum(lower) / len(lower)
        high = sum(upper) / len(upper)
    threshold = (low + high) / 2

    inside_values: list[float] = []
    outside_values: list[float] = []
    inside_bright = 0
    outside_bright = 0
    for sample_y, row in enumerate(pixels):
        for sample_x, pixel in enumerate(row):
            if direction == "up":
                inside = sample_y >= 2 * abs(sample_x - 7.5)
            elif direction == "down":
                inside = sample_y <= 15 - 2 * abs(sample_x - 7.5)
            elif direction == "right":
                inside = sample_x <= 15 - 2 * abs(sample_y - 7.5)
            else:
                inside = sample_x >= 2 * abs(sample_y - 7.5)
            value = sum(pixel) / 3
            if inside:
                inside_values.append(value)
                inside_bright += value >= threshold
            else:
                outside_values.append(value)
                outside_bright += value >= threshold

    inside_density = inside_bright / len(inside_values)
    outside_density = outside_bright / len(outside_values)
    return _TriangleFillFeatures(
        cluster_gap=high - low,
        inside_density=inside_density,
        outside_density=outside_density,
        density_contrast=inside_density - outside_density,
        luma_contrast=(
            sum(inside_values) / len(inside_values)
            - sum(outside_values) / len(outside_values)
        ),
    )


def _prune_final_mini_spike_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
    *,
    miniblock_room: bool,
) -> list[Detection]:
    mini_spikes = [
        detection for detection in detections if detection.type_id in MINI_SPIKE_TYPES
    ]
    if not mini_spikes:
        return detections
    if miniblock_room:
        kept_mini_spikes = _select_miniblock_room_mini_spikes(
            detections,
            mini_spikes,
            image,
            room,
        )
    else:
        kept_mini_spikes = []
        for detection in mini_spikes:
            direction = {
                OBJ_MINI_SPIKE_UP: "up",
                OBJ_MINI_SPIKE_RIGHT: "right",
                OBJ_MINI_SPIKE_LEFT: "left",
                OBJ_MINI_SPIKE_DOWN: "down",
            }[detection.type_id]
            fill = _triangle_fill_features(
                image,
                room,
                detection.x,
                detection.y,
                MINI_BLOCK_SIZE,
                direction,
            )
            neighbors = _nearby_mini_spike_support_count(
                detection,
                mini_spikes,
                MINI_BLOCK_SIZE,
            )
            if not _is_final_legacy_mini_spike_noise(
                detection.score,
                fill.inside_density,
                neighbors,
            ):
                kept_mini_spikes.append(detection)

    kept_ids = {id(detection) for detection in kept_mini_spikes}
    return [
        detection
        for detection in detections
        if detection.type_id not in MINI_SPIKE_TYPES or id(detection) in kept_ids
    ]


def _is_final_legacy_mini_spike_noise(
    score: float,
    fill_inside: float,
    neighbors: int,
) -> bool:
    return score >= 0.40 and fill_inside >= 0.40 and neighbors == 0


def _select_miniblock_room_mini_spikes(
    detections: list[Detection],
    mini_spikes: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    directions = {
        OBJ_MINI_SPIKE_UP: "up",
        OBJ_MINI_SPIKE_RIGHT: "right",
        OBJ_MINI_SPIKE_LEFT: "left",
        OBJ_MINI_SPIKE_DOWN: "down",
    }
    base_offsets = {
        OBJ_MINI_SPIKE_UP: (0, MINI_BLOCK_SIZE),
        OBJ_MINI_SPIKE_RIGHT: (-MINI_BLOCK_SIZE, 0),
        OBJ_MINI_SPIKE_LEFT: (MINI_BLOCK_SIZE, 0),
        OBJ_MINI_SPIKE_DOWN: (0, -MINI_BLOCK_SIZE),
    }
    opposite_types = {
        OBJ_MINI_SPIKE_UP: OBJ_MINI_SPIKE_DOWN,
        OBJ_MINI_SPIKE_DOWN: OBJ_MINI_SPIKE_UP,
        OBJ_MINI_SPIKE_LEFT: OBJ_MINI_SPIKE_RIGHT,
        OBJ_MINI_SPIKE_RIGHT: OBJ_MINI_SPIKE_LEFT,
    }
    mini_keys = {
        (detection.type_id, detection.x, detection.y) for detection in mini_spikes
    }
    mini_blocks = [
        detection for detection in detections if detection.type_id == OBJ_MINI_BLOCK
    ]
    raw_mini_block_positions = {
        (detection.x, detection.y)
        for detection in mini_blocks
        if detection.kind == "mini_block"
    }
    dense_miniblock_room = _looks_miniblock_dominant(
        raw_mini_block_positions
    )
    block_profiles = [
        _patch_color_profile(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
        )
        for detection in mini_blocks
    ]
    learned_block_profile = _median_color_profile(block_profiles)

    kept: list[Detection] = []
    for detection in mini_spikes:
        direction = directions[detection.type_id]
        patch = _patch_features(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
        )
        block = _classify_block(patch)
        shape = _mini_spike_class_for_detection(detection, patch)
        if shape is None:
            continue
        side_min = _triangle_min_side_coverage(patch, direction)
        base_edge = _triangle_base_edge_coverage(patch, direction)
        fill = _triangle_fill_features(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
            direction,
        )
        normalized_patch = _normalized_miniblock_luma_patch(
            image,
            room,
            detection.x,
            detection.y,
        )
        profile = _patch_color_profile(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
        )
        block_profile_distance = _color_profile_distance(
            profile,
            learned_block_profile,
        )
        neighbors = _nearby_mini_spike_support_count(
            detection,
            mini_spikes,
            MINI_BLOCK_SIZE,
        )
        if detection.type_id in (OBJ_MINI_SPIKE_UP, OBJ_MINI_SPIKE_DOWN):
            axis_offsets = tuple(
                (0, offset) for offset in (-48, -32, -16, 16, 32, 48)
            )
            immediate_offsets = ((0, -16), (0, 16))
        else:
            axis_offsets = tuple(
                (offset, 0) for offset in (-48, -32, -16, 16, 32, 48)
            )
            immediate_offsets = ((-16, 0), (16, 0))
        same_type_axis_run = sum(
            (detection.type_id, detection.x + dx, detection.y + dy) in mini_keys
            for dx, dy in axis_offsets
        )
        same_type_immediate_axis = sum(
            (detection.type_id, detection.x + dx, detection.y + dy) in mini_keys
            for dx, dy in immediate_offsets
        )
        opposite_type_axis_run = sum(
            (
                opposite_types[detection.type_id],
                detection.x + dx,
                detection.y + dy,
            )
            in mini_keys
            for dx, dy in axis_offsets
        )
        base_dx, base_dy = base_offsets[detection.type_id]
        run_supported = _is_dense_miniblock_run_supported(
            shape,
            patch,
            fill,
            normalized_patch,
            same_type_immediate_axis,
            (
                detection.x + base_dx,
                detection.y + base_dy,
            )
            in raw_mini_block_positions,
            dense_miniblock_room=dense_miniblock_room,
        )
        if run_supported or _is_miniblock_room_mini_spike_candidate(
            detection.type_id,
            detection.score,
            shape.direction_margin,
            side_min,
            base_edge,
            patch.edge_density,
            patch.border_score,
            patch.center_score,
            block.score,
            profile.saturation,
            block_profile_distance,
            fill.inside_density,
            fill.density_contrast,
            fill.luma_contrast,
            neighbors,
            same_type_axis_run,
            same_type_immediate_axis,
            opposite_type_axis_run,
        ):
            kept.append(detection)
    return kept


def _is_dense_miniblock_run_supported(
    shape: _GeometryClass,
    patch: _PatchFeatures,
    fill: _TriangleFillFeatures,
    normalized_patch: _NormalizedLumaPatch,
    same_type_immediate_axis: int,
    raw_base_support: bool,
    *,
    dense_miniblock_room: bool,
) -> bool:
    """Recognize a triangle from palette-relative shape and local run topology.

    Two immediate same-direction neighbors provide independent support on both
    sides.  With only one neighbor, require stronger triangle evidence and a
    direction-relative base emitted by the immutable raw miniblock detector.
    Later recovered geometry therefore cannot manufacture its own support.
    """

    if not dense_miniblock_room:
        return False

    normalized_edge = normalized_patch.edge_density
    two_sided_run = (
        same_type_immediate_axis >= 2
        and shape.score >= DENSE_MINIBLOCK_TWO_SIDED_RUN_MIN_SCORE
        and shape.direction_margin
        >= DENSE_MINIBLOCK_TWO_SIDED_RUN_MIN_DIRECTION_MARGIN
        and shape.outline_delta >= DENSE_MINIBLOCK_TWO_SIDED_RUN_MIN_OUTLINE_DELTA
        and patch.edge_density >= DENSE_MINIBLOCK_TWO_SIDED_RUN_MIN_EDGE_DENSITY
        and fill.density_contrast
        >= DENSE_MINIBLOCK_TWO_SIDED_RUN_MIN_FILL_DENSITY_CONTRAST
        and normalized_edge >= DENSE_MINIBLOCK_RUN_MIN_NORMALIZED_EDGE_DENSITY
    )
    based_run = (
        same_type_immediate_axis >= 1
        and raw_base_support
        and shape.score >= DENSE_MINIBLOCK_BASED_RUN_MIN_SCORE
        and shape.direction_margin >= DENSE_MINIBLOCK_BASED_RUN_MIN_DIRECTION_MARGIN
        and shape.outline_delta >= DENSE_MINIBLOCK_BASED_RUN_MIN_OUTLINE_DELTA
        and patch.edge_density >= DENSE_MINIBLOCK_BASED_RUN_MIN_EDGE_DENSITY
        and fill.density_contrast
        >= DENSE_MINIBLOCK_BASED_RUN_MIN_FILL_DENSITY_CONTRAST
        and abs(fill.luma_contrast)
        >= DENSE_MINIBLOCK_BASED_RUN_MIN_ABS_LUMA_CONTRAST
        and normalized_edge >= DENSE_MINIBLOCK_RUN_MIN_NORMALIZED_EDGE_DENSITY
    )
    return two_sided_run or based_run


def _is_miniblock_room_mini_spike_candidate(
    type_id: int,
    score: float,
    direction_margin: float,
    side_min: float,
    base_edge: float,
    edge_density: float,
    border_score: float,
    center_score: float,
    block_score: float,
    saturation: float,
    block_profile_distance: float,
    fill_inside: float,
    fill_density_contrast: float,
    fill_luma_contrast: float,
    neighbors: int,
    same_type_axis_run: int,
    same_type_immediate_axis: int,
    opposite_type_axis_run: int,
) -> bool:
    core_triangle = side_min >= 0.75 and fill_density_contrast >= 0.40
    stretched_up_run = (
        type_id == OBJ_MINI_SPIKE_UP
        and same_type_axis_run >= 2
        and opposite_type_axis_run == 0
    )
    block_supported_triangle = (
        base_edge <= 0.50
        and block_score >= 0.35
        and fill_density_contrast >= 0.40
    )
    low_score_complete_outline = (
        score <= 0.35 and side_min >= 0.875 and border_score >= 0.30
    )
    low_texture_block_relative = (
        border_score <= 0.20
        and saturation <= 0.25
        and block_profile_distance <= 40
    )
    low_score_directional = (
        score <= 0.25 and direction_margin >= -0.05 and block_score >= 0.30
    )
    faint_immediate_run = (
        0.20 <= edge_density <= 0.225 and same_type_immediate_axis >= 2
    )
    open_center_shape = (
        base_edge >= 0.375 and center_score >= 0.40 and block_score <= 0.30
    )
    isolated_tip_shape = (
        base_edge <= 0.25 and neighbors <= 1 and fill_inside >= 0.70
    )
    high_border_weak_shape = (
        score <= 0.30 and edge_density >= 0.30 and border_score >= 0.40
    )
    faint_high_border_up = (
        type_id == OBJ_MINI_SPIKE_UP
        and edge_density <= 0.25
        and border_score >= 0.40
    )
    center_heavy_directional = (
        direction_margin >= 0.15
        and border_score >= 0.30
        and center_score >= 0.50
    )
    saturated_axis_run = (
        saturation >= 0.40
        and fill_luma_contrast >= 30
        and same_type_axis_run >= 2
    )
    return core_triangle or any(
        (
            stretched_up_run,
            block_supported_triangle,
            low_score_complete_outline,
            low_texture_block_relative,
            low_score_directional,
            faint_immediate_run,
            open_center_shape,
            isolated_tip_shape,
            high_border_weak_shape,
            faint_high_border_up,
            center_heavy_directional,
            saturated_axis_run,
        )
    )


def _prune_particle_field_geometry_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Reject soft particles and banner text above a broad water surface."""

    water_top = _particle_water_top(detections, image, room)
    if water_top is None:
        return detections

    geometry = [
        detection
        for detection in detections
        if detection.type_id == OBJ_BLOCK
        or detection.type_id in FULL_SPIKE_TYPES
        or detection.type_id in MINI_SPIKE_TYPES
    ]
    upper_geometry = [
        detection for detection in geometry if detection.y < water_top - 32
    ]
    components: list[list[Detection]] = []
    unseen = set(range(len(upper_geometry)))
    while unseen:
        seed = unseen.pop()
        component = [upper_geometry[seed]]
        queue = deque([seed])
        while queue:
            current = upper_geometry[queue.popleft()]
            neighbors = [
                index
                for index in tuple(unseen)
                if abs(upper_geometry[index].x - current.x) <= 40
                and abs(upper_geometry[index].y - current.y) <= 40
            ]
            for index in neighbors:
                unseen.remove(index)
                queue.append(index)
                component.append(upper_geometry[index])
        components.append(component)

    rejected: set[int] = set()
    for component in components:
        blocks = [
            detection
            for detection in component
            if detection.type_id == OBJ_BLOCK
        ]
        component_width = (
            max(detection.x for detection in component)
            - min(detection.x for detection in component)
            + GRID_SIZE
        )
        component_height = (
            max(detection.y for detection in component)
            - min(detection.y for detection in component)
            + GRID_SIZE
        )
        mean_block_border = (
            sum(
                _patch_features(
                    image,
                    room,
                    detection.x,
                    detection.y,
                    GRID_SIZE,
                ).border_score
                for detection in blocks
            )
            / len(blocks)
            if blocks
            else 1.0
        )
        text_like_cluster = (
            len(component) >= 8
            and len(blocks) >= 5
            and component_width >= 192
            and component_height <= 112
            and mean_block_border < 0.42
        )
        if text_like_cluster:
            rejected.update(id(detection) for detection in component)
            continue
        if len(component) <= 2:
            rejected.update(
                id(detection)
                for detection in component
                if detection.y < water_top - 64 and detection.score < 0.38
            )

    return [
        detection for detection in detections if id(detection) not in rejected
    ]


def _particle_water_top(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> int | None:
    """Return the first broad water row in a room with an upper particle field."""

    water_rows: dict[int, int] = defaultdict(int)
    for detection in detections:
        if detection.type_id in (OBJ_WATER, OBJ_WATER_2, OBJ_WATER_3):
            water_rows[detection.y] += 1
    dense_rows = sorted(y for y, count in water_rows.items() if count >= 12)
    if len(dense_rows) < 3:
        return None

    water_top = dense_rows[0]
    if water_top < 192 or not _has_upper_particle_field(image, room, water_top):
        return None
    return water_top


def _recover_particle_water_room_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover low-contrast cyan spikes using local contrast and terrain faces."""

    water_top = _particle_water_top(detections, image, room)
    if water_top is None:
        return detections

    blocks = [
        detection for detection in detections if detection.type_id == OBJ_BLOCK
    ]
    block_positions = {(detection.x, detection.y) for detection in blocks}
    if len(block_positions) < 20:
        return detections

    classes = (
        ("up", OBJ_SPIKE_UP),
        ("right", OBJ_SPIKE_RIGHT),
        ("left", OBJ_SPIKE_LEFT),
        ("down", OBJ_SPIKE_DOWN),
    )
    candidates: list[Detection] = []
    floating_candidates: list[Detection] = []
    for y in range(max(0, water_top - GRID_SIZE), ROOM_HEIGHT - GRID_SIZE + 1, 8):
        for x in range(0, ROOM_WIDTH - GRID_SIZE + 1, 8):
            colors = _sample_map_patch_colors(image, room, x, y, GRID_SIZE)
            luminance = sorted(sum(color) / 3 for color in colors)
            median_luminance = luminance[len(luminance) // 2]

            def is_local_outline(color: tuple[int, int, int]) -> bool:
                red, green, blue = color
                return (
                    sum(color) / 3 >= median_luminance + 20
                    and (
                        max(color) - min(color) < 90
                        or green > red + 18
                        and blue > red + 25
                    )
                )

            patch_scores: list[tuple[float, int, str, int]] = []
            for direction, type_id in classes:
                score, colored = _masked_triangle_score(
                    colors,
                    direction,
                    is_local_outline,
                )
                patch_scores.append((score, colored, direction, type_id))
                support = _warm_spike_support_overlap(
                    x,
                    y,
                    direction,
                    block_positions,
                )
                if not (
                    30 <= colored <= 220
                    and (
                        score >= 0.59
                        and support >= 24
                        or score >= 0.65
                        and support >= 16
                    )
                ):
                    continue
                candidates.append(
                    _geometry_detection(
                        f"particle_water_spike_{direction}",
                        type_id,
                        x,
                        y,
                        min(0.90, score + support / 160),
                        image,
                        room,
                        GRID_SIZE,
                    )
                )

            if y < water_top + GRID_SIZE:
                continue
            patch_scores.sort(reverse=True)
            best_score, best_colored, best_direction, best_type_id = patch_scores[0]
            second_score = patch_scores[1][0]
            if (
                best_score >= 0.70
                and best_score - second_score >= 0.075
                and 30 <= best_colored <= 220
            ):
                floating_candidates.append(
                    _geometry_detection(
                        f"particle_water_floating_spike_{best_direction}",
                        best_type_id,
                        x,
                        y,
                        min(0.88, best_score + (best_score - second_score)),
                        image,
                        room,
                        GRID_SIZE,
                    )
                )

    existing_spikes = [
        detection
        for detection in detections
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    recovered: list[Detection] = []
    for candidate in sorted(
        [*candidates, *floating_candidates],
        key=lambda detection: detection.score,
        reverse=True,
    ):
        if any(
            distance(
                (detection.x, detection.y),
                (candidate.x, candidate.y),
            )
            < 16
            for detection in existing_spikes
        ):
            continue
        if any(
            distance(
                (detection.x, detection.y),
                (candidate.x, candidate.y),
            )
            < 24
            for detection in recovered
        ):
            continue
        recovered.append(candidate)
    combined = [*detections, *recovered]
    full_spikes = [
        detection
        for detection in combined
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    reconciled_spikes = _reorient_unsupported_spikes(full_spikes, blocks)
    spike_replacements = {
        id(original): replacement
        for original, replacement in zip(full_spikes, reconciled_spikes)
    }
    return [
        spike_replacements.get(id(detection), detection)
        for detection in combined
    ]


def _reconcile_common_room_geometry(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
    *,
    profile_reconciled: bool = False,
) -> list[Detection]:
    """Apply conservative terrain rules shared by every visual profile."""

    particle_water_top = _particle_water_top(detections, image, room)
    filtered = [
        detection
        for detection in detections
        if not (
            particle_water_top is not None
            and detection.type_id == OBJ_WARP
            and detection.kind == "warp"
            and not _has_dark_portal_core(image, detection.image_box)
        )
    ]
    blocks = [
        detection for detection in filtered if detection.type_id == OBJ_BLOCK
    ]
    block_positions = {(detection.x, detection.y) for detection in blocks}
    if not block_positions:
        return _dedupe_overlapping_geometry(filtered)

    reconciled: list[Detection] = []
    for detection in filtered:
        if detection.type_id not in FULL_SPIKE_TYPES:
            reconciled.append(detection)
            continue
        direction = {
            OBJ_SPIKE_UP: "up",
            OBJ_SPIKE_RIGHT: "right",
            OBJ_SPIKE_LEFT: "left",
            OBJ_SPIKE_DOWN: "down",
        }[detection.type_id]
        old_support = _warm_spike_support_overlap(
            detection.x,
            detection.y,
            direction,
            block_positions,
        )
        aligned_x, aligned_y = _align_warm_spike_to_terrain(
            detection.x,
            detection.y,
            direction,
            block_positions,
        )
        movement = abs(aligned_x - detection.x) + abs(aligned_y - detection.y)
        new_support = _warm_spike_support_overlap(
            aligned_x,
            aligned_y,
            direction,
            block_positions,
        )
        if movement <= 8 and new_support > old_support:
            detection = _geometry_detection(
                f"{detection.kind}_common_aligned",
                detection.type_id,
                aligned_x,
                aligned_y,
                detection.score,
                image,
                room,
                GRID_SIZE,
            )

        if profile_reconciled:
            # Profiled rooms already resolved solid overlap and marker
            # conflicts. They still benefit from the shared 8px face snap.
            reconciled.append(detection)
            continue

        overlap = _total_block_overlap(
            detection.x,
            detection.y,
            block_positions,
        )
        if overlap <= GRID_SIZE * MINI_BLOCK_SIZE:
            reconciled.append(detection)
            continue

        clear_face = _nearest_clear_spike_face(detection, block_positions)
        if clear_face is None:
            continue
        x, y = clear_face
        reconciled.append(
            _geometry_detection(
                f"{detection.kind}_common_resolved",
                detection.type_id,
                x,
                y,
                detection.score,
                image,
                room,
                GRID_SIZE,
            )
        )

    reconciled = _separate_overlapping_opposite_spikes(reconciled)
    if profile_reconciled:
        marker_types = (OBJ_SAVE, OBJ_WARP, OBJ_APPLE)
        markers = [
            detection
            for detection in reconciled
            if detection.type_id in marker_types
        ]
        terrain_blocks = [
            detection
            for detection in reconciled
            if detection.type_id == OBJ_BLOCK
        ]
        block_positions = {
            (detection.x, detection.y)
            for detection in terrain_blocks
        }
        if any(
            marker.type_id == OBJ_SAVE
            and _total_block_overlap(marker.x, marker.y, block_positions) > 0
            for marker in markers
        ):
            markers, terrain_blocks = _reconcile_terrain_markers(
                markers,
                terrain_blocks,
                image,
                room,
            )
            reconciled = [
                detection
                for detection in reconciled
                if detection.type_id not in marker_types
                and detection.type_id != OBJ_BLOCK
            ]
            reconciled.extend(terrain_blocks)
            reconciled.extend(markers)
        return _dedupe_exact_detections(reconciled)

    marker_types = (OBJ_SAVE, OBJ_WARP, OBJ_APPLE)
    markers = [
        detection for detection in reconciled if detection.type_id in marker_types
    ]
    terrain_blocks = [
        detection for detection in reconciled if detection.type_id == OBJ_BLOCK
    ]
    other = [
        detection
        for detection in reconciled
        if detection.type_id not in marker_types and detection.type_id != OBJ_BLOCK
    ]
    overlapping_save = any(
        marker.type_id == OBJ_SAVE
        and _total_block_overlap(marker.x, marker.y, block_positions) > 0
        for marker in markers
    )
    if overlapping_save:
        markers, terrain_blocks = _reconcile_terrain_markers(
            markers,
            terrain_blocks,
            image,
            room,
        )
    return _dedupe_exact_detections(
        _dedupe_overlapping_geometry([*other, *terrain_blocks, *markers])
    )


def _reconcile_profiled_marker_anchors(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Apply support-cell marker anchoring after a profile adds terrain.

    The bright outlined-room route appends its final block lattice late in the
    scan pipeline.  Marker detection therefore cannot always see the support
    cells during the earlier profile replacement.  Reusing the same
    palette-independent support arbitration here keeps point-object origins
    canonical without altering the global image-to-map conversion.
    """

    blocks = [
        detection for detection in detections if detection.type_id == OBJ_BLOCK
    ]
    if not blocks:
        return detections
    markers = [
        detection
        for detection in detections
        if detection.type_id in (OBJ_SAVE, OBJ_WARP, OBJ_APPLE)
    ]
    block_positions = {(detection.x, detection.y) for detection in blocks}
    if not any(
        marker.type_id == OBJ_SAVE
        and _total_block_overlap(marker.x, marker.y, block_positions) > 0
        for marker in markers
    ):
        return detections
    markers, blocks = _reconcile_terrain_markers(
        markers,
        blocks,
        image,
        room,
    )
    return [
        detection
        for detection in detections
        if detection.type_id not in (OBJ_SAVE, OBJ_WARP, OBJ_APPLE, OBJ_BLOCK)
    ] + blocks + markers


def _mini_terrain_overlap(
    x: int,
    y: int,
    cell_x: int,
    cell_y: int,
) -> int:
    width = max(
        0,
        min(x + GRID_SIZE, cell_x + MINI_BLOCK_SIZE)
        - max(x, cell_x),
    )
    height = max(
        0,
        min(y + GRID_SIZE, cell_y + MINI_BLOCK_SIZE)
        - max(y, cell_y),
    )
    return width * height


def _reconcile_mini_terrain_marker_anchors(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Snap high-confidence saves to an unoccupied full mini-cell support row.

    A 16px terrain learner can leave a save body on the neighboring 8px
    phase even when the next row contains two complete mini cells.  This
    arbitration uses occupancy and support geometry only; it does not infer a
    tileset color or shift a marker farther than one 8px phase.
    """

    mini_cells = [
        detection
        for detection in detections
        if (
            detection.type_id == OBJ_MINI_BLOCK
            and detection.score >= MINI_TERRAIN_MARKER_MIN_CELL_SCORE
        )
    ]
    if not mini_cells:
        return detections
    saves = [
        detection
        for detection in detections
        if (
            detection.type_id == OBJ_SAVE
            and detection.score >= SUPPORTED_TERRAIN_MARKER_MIN_SAVE_SCORE
        )
    ]
    if not saves:
        return detections
    replacements: dict[int, Detection] = {}
    for save in saves:
        candidates = []
        for y in range(
            max(0, save.y - MINI_BLOCK_SIZE),
            min(ROOM_HEIGHT - GRID_SIZE, save.y + MINI_BLOCK_SIZE) + 1,
            8,
        ):
            for x in range(
                max(0, save.x - MINI_BLOCK_SIZE),
                min(ROOM_WIDTH - GRID_SIZE, save.x + MINI_BLOCK_SIZE) + 1,
                8,
            ):
                overlap = sum(
                    _mini_terrain_overlap(x, y, cell.x, cell.y)
                    for cell in mini_cells
                )
                support = sum(
                    max(
                        0,
                        min(x + GRID_SIZE, cell.x + MINI_BLOCK_SIZE)
                        - max(x, cell.x),
                    )
                    for cell in mini_cells
                    if cell.y == y + GRID_SIZE
                )
                exact_support = sum(
                    min(GRID_SIZE, MINI_BLOCK_SIZE)
                    for cell in mini_cells
                    if cell.x == x and cell.y == y + GRID_SIZE
                )
                side_support = sum(
                    max(
                        0,
                        min(y + GRID_SIZE, cell.y + MINI_BLOCK_SIZE)
                        - max(y, cell.y),
                    )
                    for cell in mini_cells
                    if cell.x in (x - GRID_SIZE, x + GRID_SIZE)
                )
                movement = abs(x - save.x) + abs(y - save.y)
                candidates.append(
                    (
                        overlap > 0,
                        -min(GRID_SIZE, exact_support),
                        -min(GRID_SIZE, support),
                        movement,
                        -min(GRID_SIZE, side_support),
                        y,
                        x,
                        support,
                    )
                )
        if not candidates:
            continue
        best = min(candidates)
        _overlap, _exact, _support, movement, _side, y, x, support = best
        if (
            support < MINI_TERRAIN_MARKER_MIN_SUPPORT
            or movement > MINI_TERRAIN_MARKER_MAX_SHIFT
            or (x, y) == (save.x, save.y)
        ):
            continue
        replacements[id(save)] = _geometry_detection(
            f"{save.kind}_mini_terrain_aligned",
            save.type_id,
            x,
            y,
            save.score,
            image,
            room,
            GRID_SIZE,
        )
    if not replacements:
        return detections
    return [replacements.get(id(detection), detection) for detection in detections]


def _recover_late_mini_spike_silhouettes(
    detections: list[Detection],
    raw_primary_mini_spikes: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover strong mini silhouettes after room-scale geometry arbitration.

    Some unfamiliar tilesets expose a real 16px spike clearly enough for the
    primary classifier, but later cleanup removes it because the neighboring
    32px terrain profile has no matching anchor.  Reconsider only the raw
    mini candidate's local shape here, after all full-spike reconciliation is
    complete.  The independent 32px footprint veto keeps a full spike that
    was split into two 16px halves from being emitted as minis.  All decisions
    are shape- and topology-based; no palette or fixture coordinate is used.
    """
    if not raw_primary_mini_spikes:
        return detections

    def full_shape(detection: Detection) -> _GeometryClass | None:
        return _classify_full_spike(
            _patch_features(image, room, detection.x, detection.y, GRID_SIZE)
        )

    mini_detections = [
        detection
        for detection in detections
        if detection.type_id in MINI_SPIKE_TYPES
    ]
    remove_ids: set[int] = set()
    for detection in mini_detections:
        if (
            detection.type_id != OBJ_MINI_SPIKE_DOWN
            or detection.score >= FULL_SHAPED_DOWN_MINI_PAIR_MAX_SCORE
        ):
            continue
        shape = full_shape(detection)
        if not (
            shape is not None
            and shape.type_id == OBJ_SPIKE_DOWN
            and shape.score >= FULL_SHAPED_DOWN_MINI_PAIR_MIN_FULL_SCORE
            and shape.direction_margin
            >= FULL_SHAPED_DOWN_MINI_PAIR_MIN_DIRECTION_MARGIN
        ):
            continue
        neighbors = [
            other
            for other in mini_detections
            if (
                other is not detection
                and other.type_id == OBJ_MINI_SPIKE_DOWN
                and abs(other.x - detection.x) <= MINI_BLOCK_SIZE
                and abs(other.y - detection.y) <= MINI_BLOCK_SIZE
            )
        ]
        if neighbors:
            remove_ids.add(id(detection))
            remove_ids.update(id(other) for other in neighbors)

    recovered = [
        detection
        for detection in detections
        if id(detection) not in remove_ids
    ]
    existing_minis = [
        detection
        for detection in recovered
        if detection.type_id in MINI_SPIKE_TYPES
    ]
    for candidate in raw_primary_mini_spikes:
        if candidate.type_id not in MINI_SPIKE_TYPES:
            continue
        if any(
            existing.type_id == candidate.type_id
            and abs(existing.x - candidate.x) <= 8
            and abs(existing.y - candidate.y) <= 8
            for existing in existing_minis
        ):
            continue
        patch = _patch_features(image, room, candidate.x, candidate.y, MINI_BLOCK_SIZE)
        mini = _mini_spike_class_for_detection(candidate, patch)
        if mini is None:
            continue
        shape = full_shape(candidate)
        if (
            shape is not None
            and shape.score >= LATE_MINI_SPIKE_RECOVERY_MAX_FULL_SHAPE_SCORE
        ):
            continue
        keep = (
            candidate.type_id == OBJ_MINI_SPIKE_DOWN
            and candidate.score >= LATE_MINI_SPIKE_RECOVERY_DOWN_MIN_SCORE
            and mini.direction_margin
            >= LATE_MINI_SPIKE_RECOVERY_DOWN_MIN_DIRECTION_MARGIN
            and mini.outline_delta >= LATE_MINI_SPIKE_RECOVERY_DOWN_MIN_OUTLINE_DELTA
        ) or (
            candidate.type_id == OBJ_MINI_SPIKE_RIGHT
            and candidate.score >= LATE_MINI_SPIKE_RECOVERY_RIGHT_MIN_SCORE
            and mini.direction_margin
            >= LATE_MINI_SPIKE_RECOVERY_RIGHT_MIN_DIRECTION_MARGIN
            and mini.outline_delta >= LATE_MINI_SPIKE_RECOVERY_RIGHT_MIN_OUTLINE_DELTA
        ) or (
            candidate.type_id == OBJ_MINI_SPIKE_UP
            and candidate.score >= LATE_MINI_SPIKE_RECOVERY_UP_MIN_SCORE
            and mini.direction_margin
            >= LATE_MINI_SPIKE_RECOVERY_UP_MIN_DIRECTION_MARGIN
            and mini.outline_delta >= LATE_MINI_SPIKE_RECOVERY_UP_MIN_OUTLINE_DELTA
        )
        if keep:
            recovered.append(candidate)
            existing_minis.append(candidate)
    return recovered


def _recover_block_edge_mini_spikes(
    detections: list[Detection],
    candidate_mini_spikes: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover half-cell spikes split across a recognized terrain edge.

    A mini-spike can be visually complete in its 16px cell while the ordinary
    16px pass rejects it because the neighboring 32px terrain cell wins the
    local overlap arbitration.  Revisit every normalized half-cell only after
    room-scale terrain reconciliation has produced accepted blocks.  The
    candidate must have a strong direction/outline/side profile, share an
    actual edge with a block on the appropriate side, and fail to look like an
    independent 32px spike.  Miniblock rooms are deliberately left to their
    dedicated topology-aware route.

    The candidate list is the union of primary mini candidates and candidates
    rejected by the first overlap pass, so late room arbitration can be
    reconsidered without rescanning every half-cell.  These are palette- and
    tileset-relative geometry tests; no fixture or coordinate identity is used.
    """
    if any(detection.type_id == OBJ_MINI_BLOCK for detection in detections):
        return detections

    blocks = [
        detection for detection in detections if detection.type_id == OBJ_BLOCK
    ]
    if not blocks:
        return detections

    directions = {
        OBJ_MINI_SPIKE_UP: "up",
        OBJ_MINI_SPIKE_RIGHT: "right",
        OBJ_MINI_SPIKE_LEFT: "left",
        OBJ_MINI_SPIKE_DOWN: "down",
    }
    existing = [
        detection
        for detection in detections
        if detection.type_id in MINI_SPIKE_TYPES
    ]
    full_spikes = [
        detection
        for detection in detections
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    terrain_count = len(blocks) + len(full_spikes)
    if existing and len(existing) / max(1, terrain_count) > (
        BLOCK_EDGE_MINI_SPIKE_RECOVERY_MAX_MINI_TERRAIN_RATIO
    ):
        # Dense mini-spike rooms have their own lattice/profile arbitration;
        # isolated block-edge recovery would only promote texture seams there.
        return detections
    added: list[Detection] = []

    def has_adjacent_block_edge(type_id: int, x: int, y: int) -> bool:
        direction = directions[type_id]
        for block in blocks:
            horizontal_overlap = min(x + MINI_BLOCK_SIZE, block.x + GRID_SIZE) > max(
                x,
                block.x,
            )
            vertical_overlap = min(y + MINI_BLOCK_SIZE, block.y + GRID_SIZE) > max(
                y,
                block.y,
            )
            if direction == "up" and block.y == y + MINI_BLOCK_SIZE:
                if horizontal_overlap:
                    return True
            elif direction == "down" and block.y + GRID_SIZE == y:
                if horizontal_overlap:
                    return True
            elif direction == "right" and block.x + GRID_SIZE == x:
                if vertical_overlap:
                    return True
            elif direction == "left" and block.x == x + MINI_BLOCK_SIZE:
                if vertical_overlap:
                    return True
        return False

    for candidate in candidate_mini_spikes:
        if candidate.type_id not in MINI_SPIKE_TYPES:
            continue
        x, y = candidate.x, candidate.y
        if any(
            abs(detection.x - x) <= 8
            and abs(detection.y - y) <= 8
            for detection in [*existing, *added]
        ):
            continue
        patch = _patch_features(image, room, x, y, MINI_BLOCK_SIZE)
        mini = _mini_spike_class_for_detection(candidate, patch)
        if mini is None:
            continue
        direction = directions[mini.type_id]
        if not (
            mini.score >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_SCORE
            and mini.direction_margin
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_DIRECTION_MARGIN
            and mini.outline_delta
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_OUTLINE_DELTA
            and patch.edge_density
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_EDGE_DENSITY
            and _triangle_side_coverage(patch, direction)
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_SIDE_COVERAGE
            and _triangle_min_side_coverage(patch, direction)
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MIN_SIDE_MIN_COVERAGE
            and has_adjacent_block_edge(mini.type_id, x, y)
        ):
            continue
        full_shape = _classify_full_spike(
            _patch_features(image, room, x, y, GRID_SIZE)
        )
        if (
            full_shape is not None
            and full_shape.score
            >= BLOCK_EDGE_MINI_SPIKE_RECOVERY_MAX_FULL_SHAPE_SCORE
        ):
            continue
        added.append(
            _geometry_detection(
                "mini_spike_block_edge_recovery",
                mini.type_id,
                x,
                y,
                mini.score,
                image,
                room,
                MINI_BLOCK_SIZE,
            )
        )

    return [*detections, *added] if added else detections


def _recover_dark_textured_adjacent_up_mini_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover paired upward minis in dark, neutral textured rooms.

    In this room family the spike material can have almost the same luminance
    as the surrounding texture, so the ordinary edge classifier sees only
    noise.  The patch border still provides a palette-relative background
    estimate: a real upward triangle grows from a centered narrow top toward a
    filled lower edge.  Requiring that profile in two adjacent cells prevents
    isolated texture seams from becoming gameplay objects.
    """

    if sum(
        detection.type_id in FULL_SPIKE_TYPES
        for detection in detections
    ) < DARK_TEXTURED_MINI_MIN_FULL_SPIKE_COUNT:
        return detections

    profile = _room_color_profile(image, room)
    brightness = _profile_brightness(profile)
    if not (
        DARK_TEXTURED_MINI_ROOM_MIN_BRIGHTNESS
        <= brightness
        <= DARK_TEXTURED_MINI_ROOM_MAX_BRIGHTNESS
        and profile.saturation <= DARK_TEXTURED_MINI_ROOM_MAX_SATURATION
        and abs(profile.avg_b - profile.avg_r)
        <= DARK_TEXTURED_MINI_ROOM_MAX_CHROMA_DELTA
    ):
        return detections

    candidates: dict[tuple[int, int], float] = {}
    for y in range(0, ROOM_HEIGHT - MINI_BLOCK_SIZE + 1, MINI_BLOCK_SIZE):
        for x in range(0, ROOM_WIDTH - MINI_BLOCK_SIZE + 1, MINI_BLOCK_SIZE):
            score = _dark_textured_up_mini_shape_score(image, room, x, y)
            if score is not None:
                candidates[(x, y)] = score
    if not candidates:
        return detections

    existing = [
        detection
        for detection in detections
        if detection.type_id == OBJ_MINI_SPIKE_UP
    ]
    added: list[Detection] = []
    for (x, y), score in sorted(
        candidates.items(),
        key=lambda item: (item[0][1], item[0][0]),
    ):
        if not (
            (x - DARK_TEXTURED_MINI_PAIR_DISTANCE, y) in candidates
            or (x + DARK_TEXTURED_MINI_PAIR_DISTANCE, y) in candidates
        ):
            continue
        if any(
            abs(detection.x - x) <= 8 and abs(detection.y - y) <= 8
            for detection in (*existing, *added)
        ):
            continue
        added.append(
            _geometry_detection(
                "mini_spike_up_dark_textured_pair",
                OBJ_MINI_SPIKE_UP,
                x,
                y,
                score,
                image,
                room,
                MINI_BLOCK_SIZE,
            )
        )
    return [*detections, *added] if added else detections


def _prune_overlapping_terrain_full_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Reject weak neutral-terrain triangles drawn inside solid cells.

    The neutral-terrain fallback intentionally permits a high masked-colour
    score to retain a full spike even when only a small part of its triangle
    is visible.  In practice a low-coverage, wrong-orientation patch inside a
    reconciled block is a terrain edge alias, not a lethal object.  Run this
    veto after every geometry consumer so the block remains available as
    support while true occluded horizontal recoveries keep their dedicated
    provenance and are never filtered by this rule.

    The gate uses only local triangle shape, directional confidence, and
    overlap with the independently retained block field.  It is therefore
    independent of absolute colour, tileset, room name, and coordinates.
    """

    block_positions = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_BLOCK
    }
    if not block_positions:
        return detections
    direction_by_type = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    removed = False
    kept: list[Detection] = []
    for detection in detections:
        if (
            detection.type_id not in FULL_SPIKE_TYPES
            or not detection.kind.startswith("terrain_full_spike_")
            or detection.kind == "terrain_occluded_horizontal_spike"
            or _total_block_overlap(
                detection.x,
                detection.y,
                block_positions,
            )
            <= 0
        ):
            kept.append(detection)
            continue
        direction = direction_by_type[detection.type_id]
        overlap_area = _total_block_overlap(
            detection.x,
            detection.y,
            block_positions,
        )
        patch = _patch_features(
            image,
            room,
            detection.x,
            detection.y,
            GRID_SIZE,
        )
        classified = _classify_full_spike(patch)
        weak_shape = _triangle_side_coverage(patch, direction) < (
            TERRAIN_FULL_SPIKE_OVERLAP_MIN_SIDE_COVERAGE
        )
        weak_orientation = (
            classified is None
            or classified.type_id != detection.type_id
            or classified.direction_margin
            < TERRAIN_FULL_SPIKE_OVERLAP_MIN_DIRECTION_MARGIN
        )
        # A six-pixel-or-less face overlap can be the native 8px phase of a
        # real triangle.  Preserve that narrow, same-direction candidate when
        # its masked score and directional margin are still meaningful; deep
        # overlaps and orientation disagreements remain vetoed.
        shallow_phase_recovery = (
            overlap_area <= TERRAIN_FULL_SPIKE_OVERLAP_MAX_SHALLOW_AREA
            and classified is not None
            and classified.type_id == detection.type_id
            and detection.score >= TERRAIN_FULL_SPIKE_OVERLAP_MIN_PHASE_SCORE
            and classified.direction_margin
            >= TERRAIN_FULL_SPIKE_OVERLAP_MIN_PHASE_MARGIN
        )
        directional_support = _warm_spike_support_overlap(
            detection.x,
            detection.y,
            direction,
            block_positions,
        )
        deep_unsupported_alias = (
            overlap_area > TERRAIN_FULL_SPIKE_OVERLAP_MAX_UNSUPPORTED_AREA
            and directional_support == 0
            and detection.score < TERRAIN_FULL_SPIKE_OVERLAP_MAX_DEEP_UNSUPPORTED_SCORE
        )
        if (
            (weak_shape or weak_orientation or deep_unsupported_alias)
            and not shallow_phase_recovery
        ):
            removed = True
            continue
        kept.append(detection)
    return kept if removed else detections


def _prune_terrain_mini_spike_overlaps(
    detections: list[Detection],
) -> list[Detection]:
    """Drop neutral-terrain mini aliases that duplicate a full-spike cell.

    The neutral fallback runs on both 32px and 16px windows.  On an 8px
    capture phase, the same triangle can therefore survive once as a full
    spike and once as a ``terrain_mini_spike_*`` candidate.  The full-spike
    result is the more specific hypothesis when their actual footprints
    overlap materially.  Only the fallback mini provenance is considered;
    ordinary mini spikes and ``terrain_occluded_horizontal_spike`` recoveries
    are left untouched because they can represent independent objects.
    """

    full_spikes = [
        detection
        for detection in detections
        if detection.type_id in FULL_SPIKE_TYPES
    ]
    if not full_spikes:
        return detections
    removed = False
    kept: list[Detection] = []
    for detection in detections:
        if (
            detection.type_id in MINI_SPIKE_TYPES
            and detection.kind.startswith("terrain_mini_spike_")
            and any(
                _sized_box_overlap_area(
                    detection.x,
                    detection.y,
                    MINI_BLOCK_SIZE,
                    full_spike.x,
                    full_spike.y,
                    GRID_SIZE,
                )
                >= TERRAIN_MINI_SPIKE_OVERLAP_MIN_AREA
                for full_spike in full_spikes
            )
        ):
            removed = True
            continue
        kept.append(detection)
    return kept if removed else detections


def _terrain_mini_overlaps_strong_raw_full(
    mini_spike: Detection,
    raw_full_candidates: list[Detection],
) -> bool:
    """Identify a neutral mini candidate duplicated by raw full shape evidence."""

    if (
        mini_spike.type_id not in MINI_SPIKE_TYPES
        or not mini_spike.kind.startswith("terrain_mini_spike_")
    ):
        return False
    full_type_by_mini = {
        OBJ_MINI_SPIKE_UP: OBJ_SPIKE_UP,
        OBJ_MINI_SPIKE_RIGHT: OBJ_SPIKE_RIGHT,
        OBJ_MINI_SPIKE_LEFT: OBJ_SPIKE_LEFT,
        OBJ_MINI_SPIKE_DOWN: OBJ_SPIKE_DOWN,
    }
    full_type = full_type_by_mini[mini_spike.type_id]
    return any(
        candidate.type_id == full_type
        and candidate.score >= TERRAIN_MINI_RAW_FULL_ALIAS_MIN_SCORE
        and _sized_box_overlap_area(
            mini_spike.x,
            mini_spike.y,
            MINI_BLOCK_SIZE,
            candidate.x,
            candidate.y,
            GRID_SIZE,
        )
        >= TERRAIN_MINI_SPIKE_OVERLAP_MIN_AREA
        for candidate in raw_full_candidates
    )


def _prune_late_dense_miniblock_aliases(
    detections: list[Detection],
    detected_mini_blocks: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Remove flat material aliases after geometry has consumed support.

    Dense-room arbitration intentionally runs before the final full-spike and
    marker passes because it resolves overlapping hypotheses.  A material
    alias that is not at a same-origin conflict is still useful support for
    those passes, however.  This late, independent veto handles only raw
    ``mini_block`` candidates after all such consumers have finished.  The
    descriptor, center-gradient, and cardinal-neighbor features are
    normalized relative to the room palette/lattice, so the rule does not
    depend on a fixed RGB tileset.
    """

    seed_positions = {
        (detection.x, detection.y)
        for detection in detected_mini_blocks
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
    }
    if not _looks_miniblock_dominant(seed_positions):
        return detections
    candidates = [
        detection
        for detection in detections
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
        and (detection.x, detection.y) in seed_positions
    ]
    if len(candidates) < 4:
        return detections
    candidate_positions = {(detection.x, detection.y) for detection in candidates}
    material_features = [
        (
            detection,
            _normalized_miniblock_luma_patch(
                image,
                room,
                detection.x,
                detection.y,
            ),
        )
        for detection in candidates
    ]
    learned_descriptor = tuple(
        median(values)
        for values in zip(
            *(features.descriptor for _detection, features in material_features)
        )
    )
    remove_ids: set[int] = set()
    for detection, features in material_features:
        descriptor_distance = _normalized_luma_descriptor_distance(
            features.descriptor,
            learned_descriptor,
        )
        saturation = _patch_color_profile(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
        ).saturation
        neighbors4 = sum(
            (detection.x + dx, detection.y + dy) in candidate_positions
            for dx, dy in (
                (-MINI_BLOCK_SIZE, 0),
                (MINI_BLOCK_SIZE, 0),
                (0, -MINI_BLOCK_SIZE),
                (0, MINI_BLOCK_SIZE),
            )
        )
        if (
            features.center_gradient
            < DENSE_MINIBLOCK_LATE_FLAT_ALIAS_MAX_CENTER_GRADIENT
        ) or (
            descriptor_distance
            > DENSE_MINIBLOCK_LATE_MATERIAL_ALIAS_MIN_DESCRIPTOR_DISTANCE
            and features.center_gradient
            < DENSE_MINIBLOCK_LATE_MATERIAL_ALIAS_MAX_CENTER_GRADIENT
        ) or (
            descriptor_distance
            > DENSE_MINIBLOCK_LATE_LOW_SATURATION_ALIAS_MIN_DESCRIPTOR_DISTANCE
            and saturation
            < DENSE_MINIBLOCK_LATE_LOW_SATURATION_ALIAS_MAX_SATURATION
        ) or (
            descriptor_distance
            > DENSE_MINIBLOCK_LATE_SPARSE_ALIAS_MIN_DESCRIPTOR_DISTANCE
            and neighbors4 <= DENSE_MINIBLOCK_LATE_SPARSE_ALIAS_MAX_CARDINAL_NEIGHBORS
            and features.edge_density
            >= DENSE_MINIBLOCK_LATE_SPARSE_ALIAS_MIN_EDGE_DENSITY
        ):
            remove_ids.add(id(detection))
    pruned = [
        detection
        for detection in detections
        if id(detection) not in remove_ids
    ]
    return _recover_dense_minispike_backing_cells(pruned, image, room)


def _recover_dense_minispike_backing_cells(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Restore room-like 16px cells directly backed by a detected mini cap."""

    material = [
        detection
        for detection in detections
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
    ]
    material_positions = {(detection.x, detection.y) for detection in material}
    if len(material) < 4 or not _looks_miniblock_dominant(material_positions):
        return detections
    material_patches = [
        _normalized_miniblock_luma_patch(
            image,
            room,
            detection.x,
            detection.y,
        )
        for detection in material
    ]
    learned_descriptor = tuple(
        median(values)
        for values in zip(*(patch.descriptor for patch in material_patches))
    )
    backing_offset = {
        OBJ_MINI_SPIKE_UP: (0, MINI_BLOCK_SIZE),
        OBJ_MINI_SPIKE_DOWN: (0, -MINI_BLOCK_SIZE),
        OBJ_MINI_SPIKE_LEFT: (MINI_BLOCK_SIZE, 0),
        OBJ_MINI_SPIKE_RIGHT: (-MINI_BLOCK_SIZE, 0),
    }
    existing = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_MINI_BLOCK
    }
    candidates: set[tuple[int, int]] = set()
    for detection in detections:
        offset = backing_offset.get(detection.type_id)
        if offset is None:
            continue
        candidates.add((detection.x + offset[0], detection.y + offset[1]))
    added: list[Detection] = []
    for x, y in sorted(candidates, key=lambda position: (position[1], position[0])):
        if (
            (x, y) in existing
            or not (0 <= x < ROOM_WIDTH)
            or not (0 <= y < ROOM_HEIGHT)
        ):
            continue
        normalized = _normalized_miniblock_luma_patch(image, room, x, y)
        patch = _patch_features(image, room, x, y, MINI_BLOCK_SIZE)
        saturation = _patch_color_profile(
            image,
            room,
            x,
            y,
            MINI_BLOCK_SIZE,
        ).saturation
        if not (
            _normalized_luma_descriptor_distance(
                normalized.descriptor,
                learned_descriptor,
            )
            <= DENSE_MINIBLOCK_CAP_BACKING_MAX_DESCRIPTOR_DISTANCE
            and saturation >= DENSE_MINIBLOCK_CAP_BACKING_MIN_SATURATION
            and normalized.center_gradient
            >= DENSE_MINIBLOCK_CAP_BACKING_MIN_CENTER_GRADIENT
            and patch.edge_density >= DENSE_MINIBLOCK_CAP_BACKING_MIN_EDGE_DENSITY
            and patch.center_score <= DENSE_MINIBLOCK_CAP_BACKING_MAX_CENTER_SCORE
        ):
            continue
        added.append(
            _geometry_detection(
                "mini_block_minispike_backing",
                OBJ_MINI_BLOCK,
                x,
                y,
                0.55 + min(0.35, patch.edge_density),
                image,
                room,
                MINI_BLOCK_SIZE,
            )
        )
        existing.add((x, y))
    return [*detections, *added] if added else detections


def _is_dense_walljump_edge_mini_spike_candidate(
    shape: _GeometryClass,
    fill: _TriangleFillFeatures,
    normalized: _NormalizedLumaPatch,
    side_coverage: float,
) -> bool:
    """Return whether a walljump-backed cell is decisively a mini spike."""

    normalized_luma = abs(fill.luma_contrast) / max(1.0, fill.cluster_gap)
    fill_polarity = abs(fill.inside_density - 0.50)
    return (
        shape.score >= DENSE_WALLJUMP_EDGE_MINI_MIN_SCORE
        and shape.direction_margin
        >= DENSE_WALLJUMP_EDGE_MINI_MIN_DIRECTION_MARGIN
        and shape.outline_delta >= DENSE_WALLJUMP_EDGE_MINI_MIN_OUTLINE_DELTA
        and side_coverage >= DENSE_WALLJUMP_EDGE_MINI_MIN_SIDE_COVERAGE
        and fill.cluster_gap >= DENSE_MINIBLOCK_MINI_MIN_CLUSTER_GAP
        and normalized_luma
        >= DENSE_MINIBLOCK_MINI_MIN_NORMALIZED_LUMA_CONTRAST
        and (
            fill_polarity >= DENSE_MINIBLOCK_MINI_MIN_FILL_POLARITY
            or normalized.edge_density
            >= DENSE_MINIBLOCK_MINI_MIN_NORMALIZED_EDGE_DENSITY
        )
    )


def _recover_dense_walljump_edge_mini_spikes(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Recover decisive mini triangles hidden by structural walljump backing."""

    backing = [
        detection
        for detection in detections
        if detection.kind == "mini_block_walljump_backing"
        and detection.type_id == OBJ_MINI_BLOCK
    ]
    if not backing:
        return detections
    existing_mini_origins = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id in MINI_SPIKE_TYPES
    }
    directions = {
        OBJ_MINI_SPIKE_UP: "up",
        OBJ_MINI_SPIKE_RIGHT: "right",
        OBJ_MINI_SPIKE_LEFT: "left",
        OBJ_MINI_SPIKE_DOWN: "down",
    }
    added: list[Detection] = []
    for block in backing:
        if (block.x, block.y) in existing_mini_origins:
            continue
        patch = _patch_features(
            image,
            room,
            block.x,
            block.y,
            MINI_BLOCK_SIZE,
        )
        shape = max(
            _classify_mini_spike_candidates(patch),
            key=lambda item: item.score,
        )
        direction = directions[shape.type_id]
        fill = _triangle_fill_features(
            image,
            room,
            block.x,
            block.y,
            MINI_BLOCK_SIZE,
            direction,
        )
        normalized = _normalized_miniblock_luma_patch(
            image,
            room,
            block.x,
            block.y,
        )
        side_coverage = _triangle_side_coverage(patch, direction)
        if not _is_dense_walljump_edge_mini_spike_candidate(
            shape,
            fill,
            normalized,
            side_coverage,
        ):
            continue
        added.append(
            _geometry_detection(
                "mini_spike_walljump_edge_recovery",
                shape.type_id,
                block.x,
                block.y,
                shape.score,
                image,
                room,
                MINI_BLOCK_SIZE,
            )
        )
        existing_mini_origins.add((block.x, block.y))
    return [*detections, *added] if added else detections


def _dominant_dense_minispike_type(
    evidence: list[tuple[int, float, float, float, float]],
) -> int | None:
    """Return one direction only when it strictly dominates every rival."""

    if len(evidence) < 2:
        return None
    dominant: list[int] = []
    for type_id, score, margin, side, normalized_luma in evidence:
        rivals = [row for row in evidence if row[0] != type_id]
        if not rivals:
            continue
        if all(
            score >= other_score
            and margin >= other_margin
            and side >= other_side
            and normalized_luma >= other_luma
            and (
                normalized_luma - other_luma
                >= DENSE_MINIBLOCK_MULTI_MINI_MIN_LUMA_ADVANTAGE
                or side - other_side
                >= DENSE_MINIBLOCK_MULTI_MINI_MIN_SIDE_ADVANTAGE
                or margin - other_margin
                >= DENSE_MINIBLOCK_MULTI_MINI_MIN_MARGIN_ADVANTAGE
            )
            for (
                _other_type,
                other_score,
                other_margin,
                other_side,
                other_luma,
            ) in rivals
        ):
            dominant.append(type_id)
    return dominant[0] if len(dominant) == 1 else None


def _is_decisive_dense_mini_over_fragmented_full(
    shape: _GeometryClass,
    fill: _TriangleFillFeatures,
    side_coverage: float,
    full_native_extent: float,
) -> bool:
    """Return whether a strong 16px triangle disproves a weak 32px alias."""

    normalized_luma = abs(fill.luma_contrast) / max(1.0, fill.cluster_gap)
    return (
        full_native_extent < DENSE_MINIBLOCK_FULL_MIN_NATIVE_EDGE_EXTENT
        and shape.score >= DENSE_MINIBLOCK_FULL_MINI_CONFLICT_MIN_MINI_SCORE
        and shape.direction_margin
        >= DENSE_MINIBLOCK_FULL_MINI_CONFLICT_MIN_MINI_MARGIN
        and side_coverage >= DENSE_MINIBLOCK_FULL_MINI_CONFLICT_MIN_MINI_SIDE
        and fill.cluster_gap >= DENSE_MINIBLOCK_MINI_MIN_CLUSTER_GAP
        and normalized_luma
        >= DENSE_MINIBLOCK_FULL_MINI_CONFLICT_MIN_NORMALIZED_LUMA
    )


def _prune_dense_minispike_direction_conflicts(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
    *,
    dense_miniblock_room: bool = False,
) -> list[Detection]:
    """Resolve only strictly dominated directions in a dense 16px lattice."""

    seed_positions = {
        (detection.x, detection.y)
        for detection in detections
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
    }
    if not dense_miniblock_room and not _looks_miniblock_dominant(seed_positions):
        return detections
    mini_directions = {
        OBJ_MINI_SPIKE_UP: "up",
        OBJ_MINI_SPIKE_RIGHT: "right",
        OBJ_MINI_SPIKE_LEFT: "left",
        OBJ_MINI_SPIKE_DOWN: "down",
    }
    minis_by_origin: dict[tuple[int, int], list[Detection]] = defaultdict(list)
    for detection in detections:
        if detection.type_id in MINI_SPIKE_TYPES:
            minis_by_origin[(detection.x, detection.y)].append(detection)
    remove_ids: set[int] = set()
    for origin, hypotheses in minis_by_origin.items():
        if len({detection.type_id for detection in hypotheses}) < 2:
            continue
        patch = _patch_features(
            image,
            room,
            origin[0],
            origin[1],
            MINI_BLOCK_SIZE,
        )
        directional_evidence: list[tuple[int, float, float, float, float]] = []
        for detection in hypotheses:
            shape = _mini_spike_class_for_detection(detection, patch)
            if shape is None:
                continue
            direction = mini_directions[detection.type_id]
            fill = _triangle_fill_features(
                image,
                room,
                detection.x,
                detection.y,
                MINI_BLOCK_SIZE,
                direction,
            )
            directional_evidence.append(
                (
                    detection.type_id,
                    shape.score,
                    shape.direction_margin,
                    _triangle_side_coverage(patch, direction),
                    abs(fill.luma_contrast) / max(1.0, fill.cluster_gap),
                )
            )
        dominant_type = _dominant_dense_minispike_type(directional_evidence)
        if dominant_type is not None:
            remove_ids.update(
                id(detection)
                for detection in hypotheses
                if detection.type_id != dominant_type
            )
    if not remove_ids:
        return detections
    return [detection for detection in detections if id(detection) not in remove_ids]


def _arbitrate_dense_miniblock_geometry(
    detections: list[Detection],
    detected_mini_blocks: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    """Resolve material and scale aliases in a proven dense 16px lattice.

    The activation evidence is the immutable output of the raw miniblock
    detector, rather than later structural recoveries.  This keeps the rule
    palette- and room-independent while preventing recovered cells from
    manufacturing the topology that enables their own pruning.

    Once active, the learned material profile can reject only raw miniblock
    candidates.  Structural miniblocks retain their provenance unless a
    decisive same-origin triangle owns that cell.  A separately decisive
    primary 32px spike can then absorb contained 16px spike fragments without
    deleting or reorienting the full spike itself.  When a triangle remains
    plausible but does not prove ownership, retain both hypotheses instead of
    converting uncertainty into a false negative.
    """

    seed_blocks = [
        detection
        for detection in detected_mini_blocks
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
    ]
    seed_positions = {
        (detection.x, detection.y) for detection in seed_blocks
    }
    if not _looks_miniblock_dominant(seed_positions):
        return detections

    mini_directions = {
        OBJ_MINI_SPIKE_UP: "up",
        OBJ_MINI_SPIKE_RIGHT: "right",
        OBJ_MINI_SPIKE_LEFT: "left",
        OBJ_MINI_SPIKE_DOWN: "down",
    }
    mini_base_offsets = {
        OBJ_MINI_SPIKE_UP: (0, MINI_BLOCK_SIZE),
        OBJ_MINI_SPIKE_RIGHT: (-MINI_BLOCK_SIZE, 0),
        OBJ_MINI_SPIKE_LEFT: (MINI_BLOCK_SIZE, 0),
        OBJ_MINI_SPIKE_DOWN: (0, -MINI_BLOCK_SIZE),
    }
    full_directions = {
        OBJ_SPIKE_UP: "up",
        OBJ_SPIKE_RIGHT: "right",
        OBJ_SPIKE_LEFT: "left",
        OBJ_SPIKE_DOWN: "down",
    }
    primary_mini_kinds = {
        OBJ_MINI_SPIKE_UP: "mini_spike_up",
        OBJ_MINI_SPIKE_RIGHT: "mini_spike_right",
        OBJ_MINI_SPIKE_LEFT: "mini_spike_left",
        OBJ_MINI_SPIKE_DOWN: "mini_spike_down",
    }
    primary_full_kinds = {
        OBJ_SPIKE_UP: "spike_up",
        OBJ_SPIKE_RIGHT: "spike_right",
        OBJ_SPIKE_LEFT: "spike_left",
        OBJ_SPIKE_DOWN: "spike_down",
    }
    mini_type_order = {
        OBJ_MINI_SPIKE_UP: 0,
        OBJ_MINI_SPIKE_RIGHT: 1,
        OBJ_MINI_SPIKE_LEFT: 2,
        OBJ_MINI_SPIKE_DOWN: 3,
    }
    input_index = {
        id(detection): index for index, detection in enumerate(detections)
    }
    remove_ids: set[int] = set()

    material_blocks = [
        detection
        for detection in detections
        if detection.type_id == OBJ_MINI_BLOCK
        and detection.kind == "mini_block"
    ]
    if material_blocks:
        material_features = [
            (
                detection,
                _normalized_miniblock_luma_patch(
                    image,
                    room,
                    detection.x,
                    detection.y,
                ),
            )
            for detection in material_blocks
        ]
        learned_descriptor = tuple(
            median(values)
            for values in zip(
                *(features.descriptor for _detection, features in material_features)
            )
        )
        for detection, features in material_features:
            descriptor_distance = _normalized_luma_descriptor_distance(
                features.descriptor,
                learned_descriptor,
            )
            if (
                descriptor_distance
                > DENSE_MINIBLOCK_MATERIAL_MIN_DESCRIPTOR_DISTANCE
                and features.edge_density
                >= DENSE_MINIBLOCK_MATERIAL_MIN_NORMALIZED_EDGE_DENSITY
                and features.center_gradient
                <= DENSE_MINIBLOCK_MATERIAL_MAX_NORMALIZED_CENTER_GRADIENT
            ):
                remove_ids.add(id(detection))

    blocks_by_origin: dict[tuple[int, int], list[Detection]] = defaultdict(list)
    minis_by_origin: dict[tuple[int, int], list[Detection]] = defaultdict(list)
    for detection in detections:
        if id(detection) in remove_ids:
            continue
        origin = (detection.x, detection.y)
        if detection.type_id == OBJ_MINI_BLOCK:
            blocks_by_origin[origin].append(detection)
        elif detection.type_id in MINI_SPIKE_TYPES:
            minis_by_origin[origin].append(detection)

    mini_keys = {
        (detection.type_id, detection.x, detection.y)
        for hypotheses in minis_by_origin.values()
        for detection in hypotheses
    }

    conflict_origins = sorted(blocks_by_origin.keys() & minis_by_origin.keys())
    for origin in conflict_origins:
        admissible: list[tuple[tuple[float, ...], Detection]] = []
        plausible_ids: set[int] = set()
        for detection in minis_by_origin[origin]:
            direction = mini_directions[detection.type_id]
            patch = _patch_features(
                image,
                room,
                detection.x,
                detection.y,
                MINI_BLOCK_SIZE,
            )
            shape = _mini_spike_class_for_detection(detection, patch)
            if shape is None:
                continue
            fill = _triangle_fill_features(
                image,
                room,
                detection.x,
                detection.y,
                MINI_BLOCK_SIZE,
                direction,
            )
            normalized_luma = abs(fill.luma_contrast) / max(
                1.0,
                fill.cluster_gap,
            )
            fill_polarity = abs(fill.inside_density - 0.50)
            normalized_patch = _normalized_miniblock_luma_patch(
                image,
                room,
                detection.x,
                detection.y,
            )
            if detection.type_id in (OBJ_MINI_SPIKE_UP, OBJ_MINI_SPIKE_DOWN):
                immediate_offsets = ((0, -MINI_BLOCK_SIZE), (0, MINI_BLOCK_SIZE))
            else:
                immediate_offsets = ((-MINI_BLOCK_SIZE, 0), (MINI_BLOCK_SIZE, 0))
            same_type_immediate_axis = sum(
                (
                    detection.type_id,
                    detection.x + dx,
                    detection.y + dy,
                )
                in mini_keys
                for dx, dy in immediate_offsets
            )
            base_dx, base_dy = mini_base_offsets[detection.type_id]
            run_supported = _is_dense_miniblock_run_supported(
                shape,
                patch,
                fill,
                normalized_patch,
                same_type_immediate_axis,
                (
                    detection.x + base_dx,
                    detection.y + base_dy,
                )
                in seed_positions,
                dense_miniblock_room=True,
            )
            evidence = (
                fill_polarity,
                normalized_patch.edge_density,
                normalized_luma,
                fill.cluster_gap,
                shape.score,
                shape.direction_margin,
                shape.outline_delta,
                detection.score,
                float(detection.kind == primary_mini_kinds[detection.type_id]),
                float(-mini_type_order[detection.type_id]),
                float(-input_index[id(detection)]),
            )
            if run_supported or (
                fill.cluster_gap
                >= DENSE_MINIBLOCK_MINI_PLAUSIBLE_MIN_CLUSTER_GAP
                and normalized_luma
                >= DENSE_MINIBLOCK_MINI_PLAUSIBLE_MIN_NORMALIZED_LUMA_CONTRAST
                and normalized_patch.edge_density
                >= DENSE_MINIBLOCK_MINI_PLAUSIBLE_MIN_NORMALIZED_EDGE_DENSITY
            ):
                plausible_ids.add(id(detection))
            if not (
                fill.cluster_gap >= DENSE_MINIBLOCK_MINI_MIN_CLUSTER_GAP
                and normalized_luma
                >= DENSE_MINIBLOCK_MINI_MIN_NORMALIZED_LUMA_CONTRAST
                and (
                    fill_polarity >= DENSE_MINIBLOCK_MINI_MIN_FILL_POLARITY
                    or normalized_patch.edge_density
                    >= DENSE_MINIBLOCK_MINI_MIN_NORMALIZED_EDGE_DENSITY
                )
            ):
                continue
            admissible.append((evidence, detection))

        if admissible:
            winners_by_type: dict[int, tuple[tuple[float, ...], Detection]] = {}
            for evidence, detection in admissible:
                previous = winners_by_type.get(detection.type_id)
                if previous is None or evidence > previous[0]:
                    winners_by_type[detection.type_id] = (evidence, detection)
            winner_ids = {
                id(detection)
                for _evidence, detection in winners_by_type.values()
            }
            remove_ids.update(
                id(detection) for detection in blocks_by_origin[origin]
            )
            remove_ids.update(
                id(detection)
                for detection in minis_by_origin[origin]
                if id(detection) not in winner_ids
            )
        elif plausible_ids:
            remove_ids.update(
                id(detection)
                for detection in minis_by_origin[origin]
                if id(detection) not in plausible_ids
            )
        else:
            remove_ids.update(
                id(detection) for detection in minis_by_origin[origin]
            )

    # A block conflict is not required for resampling to leave two mini-spike
    # directions at one origin.  Reuse the final-coordinate-space reconciler
    # here so both ordinary and capture-consensus scans make the same choice.
    surviving = [
        detection for detection in detections if id(detection) not in remove_ids
    ]
    direction_reconciled = _prune_dense_minispike_direction_conflicts(
        surviving,
        image,
        room,
        dense_miniblock_room=True,
    )
    retained_direction_ids = {id(detection) for detection in direction_reconciled}
    remove_ids.update(
        id(detection)
        for detection in surviving
        if id(detection) not in retained_direction_ids
    )

    # Resolve only the measured asymmetric scale aliases: an extreme interior
    # primary fragment has insufficient native contour to be a 32px object,
    # while a sub-26px full hypothesis can lose at the same origin only to an
    # independently decisive 16px triangle.  Strong and boundary full spikes
    # remain eligible, including the established occluded recoveries.
    surviving_minis_by_origin: dict[tuple[int, int], list[Detection]] = defaultdict(list)
    for detection in detections:
        if id(detection) in remove_ids or detection.type_id not in MINI_SPIKE_TYPES:
            continue
        surviving_minis_by_origin[(detection.x, detection.y)].append(detection)
    for full in detections:
        if id(full) in remove_ids or full.type_id not in FULL_SPIKE_TYPES:
            continue
        native_extent = _native_edge_component_extent(
            image,
            room,
            full.x,
            full.y,
        )
        if (
            full.kind == primary_full_kinds[full.type_id]
            and 0 < full.x < ROOM_WIDTH - GRID_SIZE
            and 0 < full.y < ROOM_HEIGHT - GRID_SIZE
            and native_extent
            < DENSE_MINIBLOCK_PRIMARY_FULL_FRAGMENT_MAX_NATIVE_EXTENT
        ):
            remove_ids.add(id(full))
            continue
        for mini in surviving_minis_by_origin.get((full.x, full.y), ()):
            patch = _patch_features(
                image,
                room,
                mini.x,
                mini.y,
                MINI_BLOCK_SIZE,
            )
            shape = _mini_spike_class_for_detection(mini, patch)
            if shape is None:
                continue
            direction = mini_directions[mini.type_id]
            fill = _triangle_fill_features(
                image,
                room,
                mini.x,
                mini.y,
                MINI_BLOCK_SIZE,
                direction,
            )
            if _is_decisive_dense_mini_over_fragmented_full(
                shape,
                fill,
                _triangle_side_coverage(patch, direction),
                native_extent,
            ):
                remove_ids.add(id(full))
                break

    strong_fulls: list[Detection] = []
    for full in detections:
        if (
            id(full) in remove_ids
            or full.type_id not in FULL_SPIKE_TYPES
            or full.kind != primary_full_kinds[full.type_id]
        ):
            continue
        patch = _patch_features(image, room, full.x, full.y, GRID_SIZE)
        shape = _classify_full_spike(patch)
        direction = full_directions[full.type_id]
        if (
            shape is not None
            and shape.type_id == full.type_id
            and _native_edge_component_extent(
                image,
                room,
                full.x,
                full.y,
            )
            >= DENSE_MINIBLOCK_FULL_MIN_NATIVE_EDGE_EXTENT
            and shape.score >= DENSE_MINIBLOCK_FULL_MIN_SCORE
            and shape.outline_delta >= DENSE_MINIBLOCK_FULL_MIN_OUTLINE_DELTA
            and _triangle_side_coverage(patch, direction)
            >= DENSE_MINIBLOCK_FULL_MIN_SIDE_COVERAGE
            and _triangle_min_side_coverage(patch, direction)
            >= DENSE_MINIBLOCK_FULL_MIN_SIDE_COVERAGE
        ):
            strong_fulls.append(full)

    for mini in detections:
        if id(mini) in remove_ids or mini.type_id not in MINI_SPIKE_TYPES:
            continue
        normalized_patch = _normalized_miniblock_luma_patch(
            image,
            room,
            mini.x,
            mini.y,
        )
        if (
            normalized_patch.edge_density
            >= DENSE_MINIBLOCK_CONTAINED_MINI_PRESERVE_MIN_NORMALIZED_EDGE_DENSITY
        ):
            continue
        if any(
            full.x <= mini.x
            and mini.x + MINI_BLOCK_SIZE <= full.x + GRID_SIZE
            and full.y <= mini.y
            and mini.y + MINI_BLOCK_SIZE <= full.y + GRID_SIZE
            for full in strong_fulls
        ):
            remove_ids.add(id(mini))

    return [
        detection
        for detection in detections
        if id(detection) not in remove_ids
    ]


def _normalized_miniblock_luma_patch(
    image: RGBImage,
    room: Box,
    map_x: int,
    map_y: int,
) -> _NormalizedLumaPatch:
    """Describe 16px material structure independent of palette and offset."""

    colors = _sample_map_patch_colors(
        image,
        room,
        map_x,
        map_y,
        MINI_BLOCK_SIZE,
    )
    luma = [
        (red * 30 + green * 59 + blue * 11) / 100
        for red, green, blue in colors
    ]
    ordered = sorted(luma)

    def percentile(fraction: float) -> float:
        index = fraction * (len(ordered) - 1)
        lower = math.floor(index)
        upper = math.ceil(index)
        if lower == upper:
            return ordered[lower]
        return (
            ordered[lower] * (upper - index)
            + ordered[upper] * (index - lower)
        )

    scale = max(8.0, percentile(0.90) - percentile(0.10))
    mean_luma = sum(luma) / len(luma)
    descriptor = tuple(
        (
            sum(
                luma[y * 16 + x]
                for y in range(block_y, block_y + 4)
                for x in range(block_x, block_x + 4)
            )
            / 16
            - mean_luma
        )
        / scale
        for block_y in range(0, 16, 4)
        for block_x in range(0, 16, 4)
    )
    edge_strengths = [
        abs(luma[y * 16 + min(15, x + 1)] - luma[y * 16 + x])
        + abs(luma[min(15, y + 1) * 16 + x] - luma[y * 16 + x])
        for y in range(16)
        for x in range(16)
    ]
    center_strengths = [
        abs(luma[y * 16 + x + 1] - luma[y * 16 + x])
        + abs(luma[(y + 1) * 16 + x] - luma[y * 16 + x])
        for y in range(4, 11)
        for x in range(4, 11)
    ]
    return _NormalizedLumaPatch(
        descriptor=descriptor,
        edge_density=(
            sum(strength / scale >= 0.50 for strength in edge_strengths)
            / len(edge_strengths)
        ),
        center_gradient=(
            sum(center_strengths) / len(center_strengths) / scale
        ),
    )


def _normalized_luma_descriptor_distance(
    first: tuple[float, ...],
    second: tuple[float, ...],
) -> float:
    return math.sqrt(
        sum((left - right) ** 2 for left, right in zip(first, second))
        / len(first)
    )


def _dark_textured_up_mini_shape_score(
    image: RGBImage,
    room: Box,
    x: int,
    y: int,
) -> float | None:
    colors = _sample_map_patch_colors(
        image,
        room,
        x,
        y,
        MINI_BLOCK_SIZE,
    )
    border_positions = [
        index
        for index in range(16 * 16)
        if index // 16 < 2
        or index // 16 >= 14
        or index % 16 < 2
        or index % 16 >= 14
    ]
    background = tuple(
        median(colors[index][channel] for index in border_positions)
        for channel in range(3)
    )
    border_distances = sorted(
        math.sqrt(
            sum((colors[index][channel] - background[channel]) ** 2 for channel in range(3))
        )
        for index in border_positions
    )
    threshold = max(
        DARK_TEXTURED_MINI_BORDER_THRESHOLD,
        median(border_distances) * DARK_TEXTURED_MINI_BORDER_SCALE,
    )
    row_counts: list[float] = []
    row_centers: list[float | None] = []
    for row in range(16):
        positions = [
            column
            for column in range(16)
            if math.sqrt(
                sum(
                    (
                        colors[row * 16 + column][channel]
                        - background[channel]
                    )
                    ** 2
                    for channel in range(3)
                )
            )
            > threshold
        ]
        row_counts.append(len(positions) / 16)
        row_centers.append(
            sum(positions) / len(positions) if len(positions) >= 2 else None
        )

    quartiles = tuple(
        sum(row_counts[start : start + 4]) / 4
        for start in (0, 4, 8, 12)
    )
    top, second, third, bottom = quartiles
    if not (
        top <= DARK_TEXTURED_MINI_MAX_TOP_SHARE
        and bottom >= DARK_TEXTURED_MINI_MIN_BOTTOM_SHARE
        and bottom - top >= DARK_TEXTURED_MINI_MIN_RISE
        and min(
            second - top,
            third - second,
            bottom - third,
        )
        >= -DARK_TEXTURED_MINI_MAX_QUARTILE_DROP
    ):
        return None

    early_centers = [
        center
        for center, count in zip(row_centers[:10], row_counts[:10])
        if center is not None and count >= 2 / 16
    ]
    if not early_centers:
        return None
    center = median(early_centers[:4])
    if not (
        DARK_TEXTURED_MINI_MIN_CENTER
        <= center
        <= DARK_TEXTURED_MINI_MAX_CENTER
    ):
        return None
    return min(
        0.96,
        0.56
        + (bottom - top) * 0.30
        + (bottom - second) * 0.10
        + (1.0 - top) * 0.04,
    )


def _has_upper_particle_field(
    image: RGBImage,
    room: Box,
    water_top: int,
) -> bool:
    source_bottom = room.y + int(round(water_top * room.height / ROOM_HEIGHT))
    upper_room = Box(room.x, room.y, room.width, max(1, source_bottom - room.y))
    particles = 0
    for box, pixels in _connected_components(
        image,
        upper_room,
        lambda r, g, b: min(r, g, b) >= 125
        and max(r, g, b) - min(r, g, b) <= 115,
    ):
        if (
            3 <= len(pixels) <= 350
            and 2 <= box.width <= 32
            and 2 <= box.height <= 32
        ):
            particles += 1
            if particles >= 12:
                return True
    return False


def _prune_final_block_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    blocks = [detection for detection in detections if detection.type_id == OBJ_BLOCK]
    if not blocks:
        return detections
    positions = {(detection.x, detection.y) for detection in blocks}
    profiles = {
        position: _patch_color_profile(image, room, *position, GRID_SIZE)
        for position in positions
    }
    learned_profile = _median_color_profile(list(profiles.values()))
    remove_ids: set[int] = set()
    for detection in blocks:
        if detection.x < 0 or detection.y < 0:
            continue
        position = (detection.x, detection.y)
        patch = _patch_features(
            image,
            room,
            detection.x,
            detection.y,
            GRID_SIZE,
        )
        block = _classify_block(patch)
        profile = profiles[position]
        axis_profile_distances = [
            _color_profile_distance(profile, profiles[neighbor])
            for neighbor in _axis_neighbors(position, GRID_SIZE)
            if neighbor in profiles
        ]
        diagonal_neighbors = sum(
            neighbor in positions
            for neighbor in (
                (detection.x - GRID_SIZE, detection.y - GRID_SIZE),
                (detection.x + GRID_SIZE, detection.y - GRID_SIZE),
                (detection.x - GRID_SIZE, detection.y + GRID_SIZE),
                (detection.x + GRID_SIZE, detection.y + GRID_SIZE),
            )
        )
        if _is_final_block_noise_candidate(
            detection.score,
            patch.edge_density,
            patch.border_score,
            patch.center_score,
            block.score,
            _color_profile_distance(profile, learned_profile),
            min(axis_profile_distances, default=999.0),
            diagonal_neighbors,
        ):
            remove_ids.add(id(detection))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _is_final_block_noise_candidate(
    scanner_score: float,
    edge_density: float,
    border_score: float,
    center_score: float,
    block_score: float,
    learned_profile_distance: float,
    min_axis_profile_distance: float,
    diagonal_neighbors: int,
) -> bool:
    low_texture_background = (
        edge_density <= 0.15
        and border_score <= 0.20
        and learned_profile_distance >= 20
    )
    weak_diagonal_fill = (
        scanner_score <= 0.30
        and center_score >= 0.10
        and diagonal_neighbors >= 2
    )
    isolated_axis_color = (
        block_score >= 0.40
        and min_axis_profile_distance >= 15
        and diagonal_neighbors >= 3
    )
    return low_texture_background or weak_diagonal_fill or isolated_axis_color


def _prune_final_miniblock_noise(
    detections: list[Detection],
    image: RGBImage,
    room: Box,
) -> list[Detection]:
    mini_blocks = [
        detection for detection in detections if detection.type_id == OBJ_MINI_BLOCK
    ]
    if not mini_blocks:
        return detections
    profiles = [
        _patch_color_profile(
            image,
            room,
            detection.x,
            detection.y,
            MINI_BLOCK_SIZE,
        )
        for detection in mini_blocks
    ]
    learned_profile = _median_color_profile(profiles)
    remove_ids = {
        id(detection)
        for detection, profile in zip(mini_blocks, profiles)
        if _is_final_miniblock_noise_candidate(
            detection.kind,
            _color_profile_distance(profile, learned_profile),
        )
    }
    return [detection for detection in detections if id(detection) not in remove_ids]


def _is_final_miniblock_noise_candidate(
    kind: str,
    learned_profile_distance: float,
) -> bool:
    return kind == "mini_block" and learned_profile_distance > 100


def _prune_final_water_noise(detections: list[Detection]) -> list[Detection]:
    water = [
        detection
        for detection in detections
        if detection.type_id in (OBJ_WATER_2, OBJ_WATER_3)
    ]
    remove_ids: set[int] = set()
    for detection in water:
        if any(
            other is not detection
            and other.type_id == detection.type_id
            and distance((detection.x, detection.y), (other.x, other.y)) <= 24
            and other.score - detection.score >= 0.40
            and other.x not in (0, ROOM_WIDTH - GRID_SIZE)
            and other.y not in (0, ROOM_HEIGHT - GRID_SIZE)
            for other in water
        ):
            remove_ids.add(id(detection))
    kept = [detection for detection in water if id(detection) not in remove_ids]
    remove_ids.update(_dense_axis_overlap_ids(kept, MINI_BLOCK_SIZE))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _prune_final_walljump_noise(detections: list[Detection]) -> list[Detection]:
    walljumps = [
        detection
        for detection in detections
        if detection.type_id in (OBJ_WALLJUMP_LEFT, OBJ_WALLJUMP_RIGHT)
    ]
    remove_ids = _dense_axis_overlap_ids(walljumps, MINI_BLOCK_SIZE)
    kept = [detection for detection in walljumps if id(detection) not in remove_ids]
    for detection in kept:
        if any(
            other is not detection
            and other.type_id != detection.type_id
            and distance((detection.x, detection.y), (other.x, other.y)) <= 40
            and min(
                abs(other.x - detection.x),
                abs(other.y - detection.y),
            ) <= MINI_BLOCK_SIZE
            and other.score > detection.score
            for other in kept
        ):
            remove_ids.add(id(detection))
    return [detection for detection in detections if id(detection) not in remove_ids]


def _dense_axis_overlap_ids(
    detections: list[Detection],
    step: int,
) -> set[int]:
    remove_ids: set[int] = set()
    for vertical in (True, False):
        groups: defaultdict[tuple[int, int], list[Detection]] = defaultdict(list)
        for detection in detections:
            if id(detection) in remove_ids:
                continue
            fixed = detection.x if vertical else detection.y
            groups[(detection.type_id, fixed)].append(detection)
        for group in groups.values():
            ordered = sorted(group, key=lambda item: item.y if vertical else item.x)
            component: list[Detection] = []
            for detection in ordered:
                value = detection.y if vertical else detection.x
                previous = (
                    component[-1].y if vertical else component[-1].x
                ) if component else None
                if previous is None or value - previous == step:
                    component.append(detection)
                    continue
                remove_ids.update(_dense_axis_component_overlap_ids(component, vertical))
                component = [detection]
            remove_ids.update(_dense_axis_component_overlap_ids(component, vertical))
    return remove_ids


def _dense_axis_component_overlap_ids(
    component: list[Detection],
    vertical: bool,
) -> set[int]:
    if len(component) < 3:
        return set()
    ordered = sorted(component, key=lambda item: item.y if vertical else item.x)
    selected_ids = {id(ordered[0])}
    last_value = ordered[0].y if vertical else ordered[0].x
    for detection in ordered[1:]:
        value = detection.y if vertical else detection.x
        if value - last_value >= GRID_SIZE:
            selected_ids.add(id(detection))
            last_value = value
    selected_ids.add(id(ordered[-1]))
    return {id(detection) for detection in ordered if id(detection) not in selected_ids}


def _prune_duplicate_mini_spike_cells(detections: list[Detection]) -> list[Detection]:
    best_by_cell: dict[tuple[int, int], Detection] = {}
    for detection in detections:
        if detection.type_id not in MINI_SPIKE_TYPES:
            continue
        key = (detection.x, detection.y)
        current = best_by_cell.get(key)
        if current is None or _mini_spike_cell_rank(detection) > _mini_spike_cell_rank(
            current
        ):
            best_by_cell[key] = detection
    return [
        detection
        for detection in detections
        if detection.type_id not in MINI_SPIKE_TYPES
        or best_by_cell[(detection.x, detection.y)] is detection
    ]


def _mini_spike_cell_rank(detection: Detection) -> tuple[float, int]:
    return detection.score, -detection.type_id


def _is_blocklike_mini_spike_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
    mini_spikes: list[Detection],
    full_spikes: list[Detection],
    blocks: list[Detection],
) -> bool:
    if detection.type_id not in MINI_SPIKE_TYPES:
        return False
    patch = _patch_features(image, room, detection.x, detection.y, 16)
    block = _classify_block(patch)
    mini = _mini_spike_class_for_detection(detection, patch)
    mini_neighbors = _nearby_mini_spike_support_count(
        detection,
        mini_spikes,
        CROWDED_BLOCKLIKE_MINI_SPIKE_NOISE_DISTANCE,
    )
    full_supports = _nearby_full_spike_support_count(
        detection,
        full_spikes,
        BLOCKLIKE_MINI_SPIKE_NOISE_SUPPORT_DISTANCE,
    )
    full_overlap_supports = _nearby_full_spike_support_count(
        detection,
        full_spikes,
        FULL_OVERLAP_MINI_SPIKE_NOISE_DISTANCE,
    )
    block_supports = _nearby_block_support_count(
        detection,
        blocks,
        BLOCKLIKE_MINI_SPIKE_NOISE_SUPPORT_DISTANCE,
    )
    return _is_blocklike_mini_spike_noise_candidate(
        detection.type_id,
        block.score,
        detection.score,
        mini.direction_margin if mini else 0.0,
        mini.outline_delta if mini else 0.0,
        full_supports,
        full_overlap_supports,
        block_supports,
        mini_neighbors,
    )


def _nearby_full_spike_support_count(
    detection: Detection,
    full_spikes: list[Detection],
    max_distance: float,
) -> int:
    return sum(
        1
        for full_spike in full_spikes
        if distance((detection.x, detection.y), (full_spike.x, full_spike.y))
        <= max_distance
    )


def _nearby_mini_spike_support_count(
    detection: Detection,
    mini_spikes: list[Detection],
    max_distance: float,
) -> int:
    return sum(
        1
        for mini_spike in mini_spikes
        if mini_spike is not detection
        and distance((detection.x, detection.y), (mini_spike.x, mini_spike.y))
        <= max_distance
    )


def _nearby_same_type_mini_spike_support_count(
    detection: Detection,
    mini_spikes: list[Detection],
    max_dx: int,
    max_dy: int,
) -> int:
    return sum(
        1
        for mini_spike in mini_spikes
        if mini_spike is not detection
        and mini_spike.type_id == detection.type_id
        and abs(mini_spike.x - detection.x) <= max_dx
        and abs(mini_spike.y - detection.y) <= max_dy
    )


def _has_diagonal_right_mini_step_support(
    detection: Detection,
    mini_spikes: list[Detection],
) -> bool:
    if detection.type_id != OBJ_MINI_SPIKE_RIGHT:
        return False
    return any(
        mini_spike is not detection
        and mini_spike.type_id == OBJ_MINI_SPIKE_RIGHT
        and abs(mini_spike.x - detection.x) == 16
        and abs(mini_spike.y - detection.y) == 32
        for mini_spike in mini_spikes
    )


def _has_axis_left_mini_step_support(
    detection: Detection,
    mini_spikes: list[Detection],
) -> bool:
    if detection.type_id != OBJ_MINI_SPIKE_LEFT:
        return False
    return any(
        mini_spike is not detection
        and mini_spike.type_id == OBJ_MINI_SPIKE_LEFT
        and mini_spike.x == detection.x
        and abs(mini_spike.y - detection.y) == 32
        for mini_spike in mini_spikes
    )


def _nearby_block_support_count(
    detection: Detection,
    blocks: list[Detection],
    max_distance: float,
) -> int:
    return sum(
        1
        for block in blocks
        if distance((detection.x, detection.y), (block.x, block.y)) <= max_distance
    )


def _mini_spike_class_for_detection(
    detection: Detection,
    patch: _PatchFeatures,
) -> _GeometryClass | None:
    return next(
        (
            mini
            for mini in _classify_mini_spike_candidates(patch)
            if mini.type_id == detection.type_id
        ),
        None,
    )


def _is_residual_mini_spike_noise(
    detection: Detection,
    image: RGBImage,
    room: Box,
    mini_spikes: list[Detection],
    full_spikes: list[Detection],
    blocks: list[Detection],
) -> bool:
    if detection.type_id not in MINI_SPIKE_TYPES:
        return False
    patch = _patch_features(image, room, detection.x, detection.y, 16)
    block = _classify_block(patch)
    mini = _mini_spike_class_for_detection(detection, patch)
    same_type_close = _nearby_same_type_mini_spike_support_count(
        detection,
        mini_spikes,
        16,
        16,
    )
    same_type_axis = _nearby_same_type_mini_spike_support_count(
        detection,
        mini_spikes,
        32,
        16,
    )
    mini_neighbors = _nearby_mini_spike_support_count(
        detection,
        mini_spikes,
        CROWDED_BLOCKLIKE_MINI_SPIKE_NOISE_DISTANCE,
    )
    full_overlap_supports = _nearby_full_spike_support_count(
        detection,
        full_spikes,
        FULL_OVERLAP_MINI_SPIKE_NOISE_DISTANCE,
    )
    block_supports = _nearby_block_support_count(
        detection,
        blocks,
        BLOCKLIKE_MINI_SPIKE_NOISE_SUPPORT_DISTANCE,
    )
    if (
        _has_diagonal_right_mini_step_support(detection, mini_spikes)
        and full_overlap_supports
        >= RESIDUAL_DIAGONAL_RIGHT_STEP_KEEP_MIN_FULL_SUPPORTS
        and block_supports >= RESIDUAL_DIAGONAL_RIGHT_STEP_KEEP_MIN_BLOCK_SUPPORTS
    ):
        return False
    if (
        _has_axis_left_mini_step_support(detection, mini_spikes)
        and full_overlap_supports <= RESIDUAL_AXIS_LEFT_STEP_KEEP_MAX_FULL_SUPPORTS
        and block_supports >= RESIDUAL_AXIS_LEFT_STEP_KEEP_MIN_BLOCK_SUPPORTS
    ):
        return False
    return _is_residual_mini_spike_noise_candidate(
        detection.type_id,
        block.score,
        detection.score,
        mini.direction_margin if mini else 0.0,
        mini.outline_delta if mini else 0.0,
        same_type_close,
        same_type_axis,
        mini_neighbors,
        full_overlap_supports,
        block_supports,
    )


def _is_residual_mini_spike_noise_candidate(
    type_id: int,
    block_score: float,
    mini_score: float,
    direction_margin: float,
    outline_delta: float,
    same_type_close: int,
    same_type_axis: int,
    mini_neighbors: int,
    full_overlap_supports: int,
    block_supports: int,
) -> bool:
    if _is_supported_residual_up_mini_spike(
        type_id,
        block_score,
        mini_score,
        direction_margin,
        outline_delta,
        same_type_axis,
    ):
        return False
    if (
        type_id == OBJ_MINI_SPIKE_UP
        and same_type_close >= RESIDUAL_PAIRED_UP_KEEP_MIN_SAME_TYPE_NEIGHBORS
        and same_type_axis >= RESIDUAL_PAIRED_UP_KEEP_MIN_SAME_TYPE_NEIGHBORS
        and mini_score >= RESIDUAL_PAIRED_UP_KEEP_MIN_SCORE
        and direction_margin >= RESIDUAL_PAIRED_UP_KEEP_MIN_DIRECTION_MARGIN
        and outline_delta >= RESIDUAL_PAIRED_UP_KEEP_MIN_OUTLINE_DELTA
        and block_score < RESIDUAL_PAIRED_UP_KEEP_MAX_BLOCK_SCORE
    ):
        return False
    return (
        type_id == OBJ_MINI_SPIKE_DOWN
        and block_score >= RESIDUAL_DOWN_MINI_NOISE_MIN_BLOCK_SCORE
        and outline_delta < RESIDUAL_DOWN_MINI_NOISE_MAX_OUTLINE_DELTA
    ) or (
        type_id == OBJ_MINI_SPIKE_UP
        and same_type_close >= RESIDUAL_UP_CLUSTER_NOISE_MIN_SAME_TYPE_NEIGHBORS
        and direction_margin < RESIDUAL_UP_CLUSTER_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        type_id == OBJ_MINI_SPIKE_UP
        and block_score >= RESIDUAL_UP_BLOCKLIKE_NOISE_MIN_BLOCK_SCORE
        and direction_margin < RESIDUAL_UP_BLOCKLIKE_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        block_score >= RESIDUAL_BLOCKLIKE_MINI_NOISE_MIN_BLOCK_SCORE
        and direction_margin < RESIDUAL_BLOCKLIKE_MINI_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        type_id == OBJ_MINI_SPIKE_RIGHT
        and mini_score >= RESIDUAL_RIGHT_SPARSE_MINI_NOISE_MIN_SCORE
        and mini_neighbors <= RESIDUAL_RIGHT_SPARSE_MINI_NOISE_MAX_NEIGHBORS
        and outline_delta < RESIDUAL_RIGHT_SPARSE_MINI_NOISE_MAX_OUTLINE_DELTA
    ) or (
        type_id == OBJ_MINI_SPIKE_UP
        and mini_score >= RESIDUAL_SPARSE_UP_MINI_NOISE_MIN_SCORE
        and mini_neighbors <= RESIDUAL_SPARSE_UP_MINI_NOISE_MAX_NEIGHBORS
    ) or (
        type_id == OBJ_MINI_SPIKE_LEFT
        and full_overlap_supports
        >= RESIDUAL_LEFT_OVERLAP_MINI_NOISE_MIN_FULL_SUPPORTS
        and block_supports <= RESIDUAL_LEFT_OVERLAP_MINI_NOISE_MAX_BLOCK_SUPPORTS
        and outline_delta < RESIDUAL_LEFT_OVERLAP_MINI_NOISE_MAX_OUTLINE_DELTA
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and mini_score >= RESIDUAL_SPARSE_DOWN_MINI_NOISE_MIN_SCORE
        and mini_neighbors <= RESIDUAL_SPARSE_DOWN_MINI_NOISE_MAX_NEIGHBORS
    ) or (
        type_id == OBJ_MINI_SPIKE_UP
        and block_score >= RESIDUAL_EXTENDED_UP_MINI_NOISE_MIN_BLOCK_SCORE
        and outline_delta < RESIDUAL_EXTENDED_UP_MINI_NOISE_MAX_OUTLINE_DELTA
    ) or (
        type_id == OBJ_MINI_SPIKE_LEFT
        and block_score >= RESIDUAL_EXTENDED_LEFT_MINI_NOISE_MIN_BLOCK_SCORE
        and outline_delta < RESIDUAL_EXTENDED_LEFT_MINI_NOISE_MAX_OUTLINE_DELTA
        and not _is_supported_residual_left_stack_mini_spike(
            type_id,
            outline_delta,
            same_type_close,
            full_overlap_supports,
            block_supports,
        )
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and mini_score >= RESIDUAL_STRONG_SPARSE_DOWN_MINI_NOISE_MIN_SCORE
        and mini_neighbors <= RESIDUAL_STRONG_SPARSE_DOWN_MINI_NOISE_MAX_NEIGHBORS
        and not _is_supported_residual_down_stack_mini_spike(
            type_id,
            outline_delta,
            same_type_close,
            full_overlap_supports,
            block_supports,
        )
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and mini_score >= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MIN_SCORE
        and same_type_close <= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MAX_SAME_TYPE_NEIGHBORS
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and mini_score >= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MIN_CONTEXTUAL_SCORE
        and same_type_close <= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MAX_SAME_TYPE_NEIGHBORS
        and full_overlap_supports >= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MIN_FULL_SUPPORTS
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and same_type_close <= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MAX_SAME_TYPE_NEIGHBORS
        and direction_margin <= RESIDUAL_ISOLATED_DOWN_MINI_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        type_id == OBJ_MINI_SPIKE_RIGHT
        and same_type_close == 0
        and full_overlap_supports >= RESIDUAL_ISOLATED_RIGHT_MINI_NOISE_MIN_FULL_SUPPORTS
        and block_supports >= RESIDUAL_ISOLATED_RIGHT_MINI_NOISE_MIN_BLOCK_SUPPORTS
        and direction_margin <= RESIDUAL_ISOLATED_RIGHT_MINI_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        type_id == OBJ_MINI_SPIKE_LEFT
        and same_type_close == 0
        and full_overlap_supports >= RESIDUAL_ISOLATED_LEFT_MINI_NOISE_MIN_FULL_SUPPORTS
        and block_supports >= RESIDUAL_ISOLATED_LEFT_MINI_NOISE_MIN_BLOCK_SUPPORTS
        and direction_margin <= RESIDUAL_ISOLATED_LEFT_MINI_NOISE_MAX_DIRECTION_MARGIN
    ) or (
        type_id == OBJ_MINI_SPIKE_DOWN
        and full_overlap_supports >= RESIDUAL_DENSE_DOWN_MINI_NOISE_MIN_FULL_SUPPORTS
        and block_supports >= RESIDUAL_DENSE_DOWN_MINI_NOISE_MIN_BLOCK_SUPPORTS
        and same_type_close <= RESIDUAL_DENSE_DOWN_MINI_NOISE_MAX_SAME_TYPE_NEIGHBORS
        and direction_margin <= RESIDUAL_DENSE_DOWN_MINI_NOISE_MAX_DIRECTION_MARGIN
    )


def _is_supported_residual_up_mini_spike(
    type_id: int,
    block_score: float,
    mini_score: float,
    direction_margin: float,
    outline_delta: float,
    same_type_axis: int,
) -> bool:
    return (
        type_id == OBJ_MINI_SPIKE_UP
        and mini_score >= RESIDUAL_SUPPORTED_UP_MINI_KEEP_MIN_SCORE
        and block_score >= RESIDUAL_SUPPORTED_UP_MINI_KEEP_MIN_BLOCK_SCORE
        and outline_delta < RESIDUAL_SUPPORTED_UP_MINI_KEEP_MAX_OUTLINE_DELTA
        and direction_margin < RESIDUAL_SUPPORTED_UP_MINI_KEEP_MAX_DIRECTION_MARGIN
        and same_type_axis >= RESIDUAL_SUPPORTED_UP_MINI_KEEP_MIN_SAME_TYPE_NEIGHBORS
    )


def _is_supported_residual_left_stack_mini_spike(
    type_id: int,
    outline_delta: float,
    same_type_close: int,
    full_overlap_supports: int,
    block_supports: int,
) -> bool:
    return (
        type_id == OBJ_MINI_SPIKE_LEFT
        and same_type_close >= RESIDUAL_LEFT_STACK_KEEP_MIN_SAME_TYPE_NEIGHBORS
        and full_overlap_supports <= RESIDUAL_LEFT_STACK_KEEP_MAX_FULL_SUPPORTS
        and block_supports >= RESIDUAL_LEFT_STACK_KEEP_MIN_BLOCK_SUPPORTS
        and outline_delta < RESIDUAL_LEFT_STACK_KEEP_MAX_OUTLINE_DELTA
    )


def _is_supported_residual_down_stack_mini_spike(
    type_id: int,
    outline_delta: float,
    same_type_close: int,
    full_overlap_supports: int,
    block_supports: int,
) -> bool:
    return (
        type_id == OBJ_MINI_SPIKE_DOWN
        and same_type_close >= RESIDUAL_DOWN_STACK_KEEP_MIN_SAME_TYPE_NEIGHBORS
        and full_overlap_supports <= RESIDUAL_DOWN_STACK_KEEP_MAX_FULL_SUPPORTS
        and block_supports >= RESIDUAL_DOWN_STACK_KEEP_MIN_BLOCK_SUPPORTS
        and outline_delta >= RESIDUAL_DOWN_STACK_KEEP_MIN_OUTLINE_DELTA
        and outline_delta <= RESIDUAL_DOWN_STACK_KEEP_MAX_OUTLINE_DELTA
    )


def _is_blocklike_mini_spike_noise_candidate(
    type_id: int,
    block_score: float,
    mini_score: float,
    direction_margin: float,
    outline_delta: float,
    full_supports: int,
    full_overlap_supports: int,
    block_supports: int,
    mini_neighbors: int,
) -> bool:
    if _is_aggressive_mini_spike_recovery_candidate(
        type_id,
        block_score,
        mini_score,
        outline_delta,
        full_overlap_supports,
        block_supports,
        mini_neighbors,
    ):
        return False
    if _is_crowded_blocklike_mini_spike_noise(
        type_id,
        block_score,
        mini_score,
        outline_delta,
        full_overlap_supports,
        mini_neighbors,
    ):
        return True
    if _is_strong_mini_spike_geometry(
        mini_score,
        direction_margin,
        outline_delta,
    ):
        return False
    if _is_full_overlap_mini_spike_noise(full_overlap_supports):
        return True
    if _is_supported_blocklike_down_right_mini_spike(
        type_id,
        block_score,
        mini_score,
        direction_margin,
        outline_delta,
        block_supports,
    ):
        return False
    if block_score >= BLOCKLIKE_MINI_SPIKE_BROAD_NOISE_BLOCK_SCORE:
        return True
    if (
        type_id == OBJ_MINI_SPIKE_LEFT
        and block_score >= BLOCKLIKE_LEFT_MINI_SPIKE_NOISE_BLOCK_SCORE
    ):
        return True
    if (
        type_id in (OBJ_MINI_SPIKE_RIGHT, OBJ_MINI_SPIKE_DOWN)
        and block_score >= BLOCKLIKE_DOWN_RIGHT_MINI_SPIKE_NOISE_BLOCK_SCORE
    ):
        return True
    return (
        block_score >= BLOCKLIKE_MINI_SPIKE_NOISE_BLOCK_SCORE
        and full_supports <= BLOCKLIKE_MINI_SPIKE_NOISE_MAX_FULL_SUPPORTS
    )


def _is_aggressive_mini_spike_recovery_candidate(
    type_id: int,
    block_score: float,
    mini_score: float,
    outline_delta: float,
    full_overlap_supports: int,
    block_supports: int,
    mini_neighbors: int,
) -> bool:
    if type_id == OBJ_MINI_SPIKE_DOWN:
        return (
            mini_score >= AGGRESSIVE_DOWN_MINI_RECOVERY_MIN_SCORE
            and outline_delta >= AGGRESSIVE_DOWN_MINI_RECOVERY_MIN_OUTLINE_DELTA
            and block_supports <= AGGRESSIVE_DOWN_MINI_RECOVERY_MAX_BLOCK_SUPPORTS
        ) or (
            mini_score >= AGGRESSIVE_STRONG_DOWN_MINI_RECOVERY_MIN_SCORE
            and outline_delta >= AGGRESSIVE_STRONG_DOWN_MINI_RECOVERY_MIN_OUTLINE_DELTA
            and full_overlap_supports
            <= AGGRESSIVE_STRONG_DOWN_MINI_RECOVERY_MAX_FULL_OVERLAP_SUPPORTS
        )
    if type_id == OBJ_MINI_SPIKE_UP:
        return (
            mini_score >= AGGRESSIVE_UP_MINI_RECOVERY_MIN_SCORE
            and block_score <= AGGRESSIVE_UP_MINI_RECOVERY_MAX_BLOCK_SCORE
            and full_overlap_supports
            >= AGGRESSIVE_UP_MINI_RECOVERY_MIN_FULL_OVERLAP_SUPPORTS
        )
    if type_id == OBJ_MINI_SPIKE_LEFT:
        return (
            mini_score >= AGGRESSIVE_LEFT_MINI_RECOVERY_MIN_SCORE
            and outline_delta >= AGGRESSIVE_LEFT_MINI_RECOVERY_MIN_OUTLINE_DELTA
            and block_score < AGGRESSIVE_LEFT_MINI_RECOVERY_MAX_BLOCK_SCORE
            and block_supports <= AGGRESSIVE_LEFT_MINI_RECOVERY_MAX_BLOCK_SUPPORTS
            and mini_neighbors >= AGGRESSIVE_LEFT_MINI_RECOVERY_MIN_NEIGHBORS
        )
    return False


def _is_crowded_blocklike_mini_spike_noise(
    type_id: int,
    block_score: float,
    mini_score: float,
    outline_delta: float,
    full_overlap_supports: int,
    mini_neighbors: int,
) -> bool:
    if (
        type_id in (OBJ_MINI_SPIKE_RIGHT, OBJ_MINI_SPIKE_DOWN)
        and mini_score >= CROWDED_BLOCKLIKE_DOWN_RIGHT_MINI_KEEP_MIN_SCORE
        and outline_delta >= CROWDED_BLOCKLIKE_DOWN_RIGHT_MINI_KEEP_MIN_OUTLINE_DELTA
        and full_overlap_supports
        <= CROWDED_BLOCKLIKE_DOWN_RIGHT_MINI_KEEP_MAX_FULL_OVERLAP_SUPPORTS
    ):
        return False
    return (
        block_score >= CROWDED_BLOCKLIKE_MINI_SPIKE_NOISE_BLOCK_SCORE
        and mini_neighbors >= CROWDED_BLOCKLIKE_MINI_SPIKE_NOISE_MIN_NEIGHBORS
    )


def _is_full_overlap_mini_spike_noise(full_overlap_supports: int) -> bool:
    return full_overlap_supports >= FULL_OVERLAP_MINI_SPIKE_NOISE_MIN_FULL_SUPPORTS


def _is_strong_mini_spike_geometry(
    mini_score: float,
    direction_margin: float,
    outline_delta: float,
) -> bool:
    return (
        mini_score >= STRONG_MINI_SPIKE_KEEP_MIN_SCORE
        and direction_margin >= STRONG_MINI_SPIKE_KEEP_MIN_DIRECTION_MARGIN
        and outline_delta >= STRONG_MINI_SPIKE_KEEP_MIN_OUTLINE_DELTA
    )


def _is_supported_blocklike_down_right_mini_spike(
    type_id: int,
    block_score: float,
    mini_score: float,
    direction_margin: float,
    outline_delta: float,
    block_supports: int,
) -> bool:
    if type_id not in (OBJ_MINI_SPIKE_RIGHT, OBJ_MINI_SPIKE_DOWN):
        return False
    if block_score < BLOCKLIKE_DOWN_RIGHT_MINI_SPIKE_NOISE_BLOCK_SCORE:
        return False
    if (
        mini_score >= BLOCKLIKE_DOWN_RIGHT_MINI_RECOVERY_MIN_SCORE
        and outline_delta >= BLOCKLIKE_DOWN_RIGHT_MINI_RECOVERY_MIN_OUTLINE_DELTA
        and block_supports <= BLOCKLIKE_DOWN_RIGHT_MINI_RECOVERY_MAX_BLOCK_SUPPORTS
    ):
        return True
    return (
        mini_score >= BLOCKLIKE_DOWN_RIGHT_STRONG_MINI_RECOVERY_MIN_SCORE
        and direction_margin
        >= BLOCKLIKE_DOWN_RIGHT_STRONG_MINI_RECOVERY_MIN_DIRECTION_MARGIN
        and outline_delta
        >= BLOCKLIKE_DOWN_RIGHT_STRONG_MINI_RECOVERY_MIN_OUTLINE_DELTA
        and block_supports
        <= BLOCKLIKE_DOWN_RIGHT_STRONG_MINI_RECOVERY_MAX_BLOCK_SUPPORTS
    )


def _normalize_full_spike_origin(type_id: int, x: int, y: int) -> tuple[int, int]:
    if type_id in (OBJ_SPIKE_UP, OBJ_SPIKE_DOWN):
        return round_to_step(x, FULL_SPIKE_AXIS_SNAP_STEP), y
    if type_id in (OBJ_SPIKE_LEFT, OBJ_SPIKE_RIGHT):
        return x, round_to_step(y, FULL_SPIKE_AXIS_SNAP_STEP)
    return x, y


def _grid_detection(
    kind: str,
    type_id: int,
    x: int,
    y: int,
    score: float,
    image: RGBImage,
    room: Box,
    size: int,
) -> Detection:
    return _geometry_detection(kind, type_id, x, y, score, image, room, size)


def _dedupe_geometry(detections: list[Detection]) -> list[Detection]:
    result: list[Detection] = []
    for det in sorted(
        detections,
        key=_geometry_dedupe_key,
    ):
        if any(_geometry_conflicts(det, existing) for existing in result):
            continue
        result.append(det)
    return sorted(result, key=lambda item: (item.y, item.x, -item.score))


def _geometry_dedupe_key(detection: Detection) -> tuple[bool, int, int, float]:
    return (
        detection.type_id in MINI_SPIKE_TYPES,
        _block_alignment_rank(detection),
        _full_spike_dedupe_rank(detection),
        -detection.score,
    )


def _full_spike_dedupe_rank(detection: Detection) -> int:
    if detection.type_id not in FULL_SPIKE_TYPES:
        return 0
    if detection.kind == "full_spike_support":
        return 2
    if _is_block_aligned_to(
        detection.x,
        detection.y,
        PREFERRED_BLOCK_ALIGNMENT_STEP,
    ):
        return 0
    return 1


def _block_alignment_rank(detection: Detection) -> int:
    if detection.type_id != OBJ_BLOCK:
        return 1
    if _is_block_aligned_to(detection.x, detection.y, PREFERRED_BLOCK_ALIGNMENT_STEP):
        return 0
    if _is_block_aligned(detection.x, detection.y):
        return 1
    return 2


def _is_block_aligned(x: int, y: int) -> bool:
    return _is_block_aligned_to(x, y, BLOCK_ALIGNMENT_STEP)


def _is_block_aligned_to(x: int, y: int, step: int) -> bool:
    return x % step == 0 and y % step == 0


def _geometry_conflicts(det: Detection, existing: Detection) -> bool:
    if det.type_id == OBJ_MINI_BLOCK and existing.type_id == OBJ_MINI_BLOCK:
        return distance((det.x, det.y), (existing.x, existing.y)) < 8
    if det.type_id in MINI_SPIKE_TYPES and existing.type_id in MINI_SPIKE_TYPES:
        return distance((det.x, det.y), (existing.x, existing.y)) < 14
    if det.type_id in MINI_SPIKE_TYPES or existing.type_id in MINI_SPIKE_TYPES:
        mini = det if det.type_id in MINI_SPIKE_TYPES else existing
        return (
            mini.score < MINI_SPIKE_COEXIST_SCORE
            and distance((det.x, det.y), (existing.x, existing.y)) < 20
        )
    return (
        det.type_id == existing.type_id
        and distance((det.x, det.y), (existing.x, existing.y)) < 28
    )


def _dedupe_overlapping_geometry(
    detections: list[Detection],
    anchor_types: frozenset[int] | None = None,
) -> list[Detection]:
    # Saves and warps are more reliable than the experimental geometry pass.
    anchors = [
        det
        for det in detections
        if det.type_id not in GEOMETRY_TYPES
        and (anchor_types is None or det.type_id in anchor_types)
    ]
    result: list[Detection] = []
    for det in detections:
        if det.type_id not in GEOMETRY_TYPES:
            result.append(det)
            continue
        if any(
            _geometry_anchor_conflicts(
                det,
                anchor,
                include_diagonal_overlap=anchor_types is not None,
            )
            for anchor in anchors
        ):
            continue
        result.append(det)
    return result


def _geometry_anchor_conflicts(
    det: Detection,
    anchor: Detection,
    *,
    include_diagonal_overlap: bool = False,
) -> bool:
    delta_x = abs(det.x - anchor.x)
    delta_y = abs(det.y - anchor.y)
    if (
        det.type_id in MINI_SPIKE_TYPES
        and anchor.type_id in {OBJ_SAVE, OBJ_WARP}
        and max(delta_x, delta_y) <= MINI_SPIKE_MARKER_NOISE_MAX_DISTANCE
        and det.score <= MINI_SPIKE_MARKER_NOISE_MAX_SCORE
    ):
        return True
    if include_diagonal_overlap:
        overlaps = max(delta_x, delta_y) < 20
    else:
        overlaps = distance((det.x, det.y), (anchor.x, anchor.y)) < 20
    if not overlaps:
        return False
    return not _can_geometry_coexist_with_anchor(det, anchor)


def _can_geometry_coexist_with_anchor(det: Detection, anchor: Detection) -> bool:
    if (
        det.type_id in FULL_SPIKE_TYPES
        and anchor.type_id == OBJ_PLATFORM
        and det.score <= FULL_SPIKE_PLATFORM_EDGE_TOUCH_MAX_SCORE
    ):
        horizontal_overlap = (
            min(det.x + GRID_SIZE, anchor.x + PLATFORM_WIDTH)
            > max(det.x, anchor.x)
        )
        edge_touch = (
            anchor.y + PLATFORM_HEIGHT == det.y
            or det.y + GRID_SIZE == anchor.y
        )
        # A platform and a hazard may share a boundary, but a spike whose
        # 32px body actually contains the platform is still competing
        # geometry and must lose to the reliable platform anchor.
        if horizontal_overlap and edge_touch:
            return True
    if (
        det.type_id in MINI_SPIKE_TYPES
        and anchor.type_id == OBJ_JUMP_REFRESHER
    ):
        # Jump refreshers are playable markers that can share the same 32px
        # cell as a deliberately half-cell mini-spike.  Their sprites overlap
        # in the source image, so treating every nearby mini-spike as marker
        # noise loses valid geometry (especially the common +16px vertical
        # placement).  Keep this coexistence rule object-class based rather
        # than tied to a room, palette, or coordinate.
        return True
    if det.type_id == OBJ_MINI_BLOCK and anchor.type_id in {OBJ_SAVE, OBJ_WARP}:
        # A save can share the edge of a 32px backing cell.  Preserve that
        # partial support instead of suppressing a legitimate neighbouring
        # miniblock merely because the save/warp is the more reliable marker.
        overlap = _box_overlap_area(det.x, det.y, anchor.x, anchor.y)
        if MINI_BLOCK_SIZE * GRID_SIZE <= overlap < GRID_SIZE * GRID_SIZE:
            return True
        # A scaled or 8px-phase capture can leave the two boxes touching only
        # at a cardinal half-cell boundary.  Keep that topology, but reject
        # diagonal proximity and cells more than one half-cell away.
        return (
            (
                abs(det.x - anchor.x) == MINI_BLOCK_SIZE
                and abs(det.y - anchor.y) <= MINI_BLOCK_SIZE // 2
            )
            or (
                abs(det.y - anchor.y) == MINI_BLOCK_SIZE
                and abs(det.x - anchor.x) <= MINI_BLOCK_SIZE // 2
            )
        )
    if det.type_id == OBJ_MINI_BLOCK and anchor.type_id in {
        OBJ_WATER,
        OBJ_WATER_2,
        OBJ_WATER_3,
    }:
        # A compact terrain cell can share a cardinal half-cell boundary with
        # a water sprite.  Keep that local support relationship, but do not
        # make arbitrary diagonal or nearby water texture an excuse to retain
        # every weak mini-block candidate.
        if (
            _sized_box_overlap_area(
                det.x,
                det.y,
                MINI_BLOCK_SIZE,
                anchor.x,
                anchor.y,
                GRID_SIZE,
            )
            != 0
        ):
            return False
        return (
            (
                abs(det.x - anchor.x) == MINI_BLOCK_SIZE
                and abs(det.y - anchor.y) <= MINI_BLOCK_SIZE // 2
            )
            or (
                abs(det.y - anchor.y) == MINI_BLOCK_SIZE
                and abs(det.x - anchor.x) <= MINI_BLOCK_SIZE // 2
            )
        )
    if det.type_id == OBJ_MINI_BLOCK and anchor.type_id in {
        OBJ_WALLJUMP_LEFT,
        OBJ_WALLJUMP_RIGHT,
    }:
        # Walljump sprites can share their cell boundary with the 16px
        # terrain column that supports the vine.  The miniblock-room recovery
        # adds this support explicitly, but late anchor arbitration used to
        # discard it as an incompatible geometry overlap.  Keep only the
        # canonical side: a left vine's backing cell is one half-cell to its
        # right, while a right vine's backing cell starts at the same x.
        expected_x = (
            anchor.x + MINI_BLOCK_SIZE
            if anchor.type_id == OBJ_WALLJUMP_LEFT
            else anchor.x
        )
        return det.x == expected_x and abs(det.y - anchor.y) <= MINI_BLOCK_SIZE
    if (
        det.type_id == OBJ_BLOCK
        and anchor.type_id in BLOCK_COLOR_ANCHOR_TYPES
        and det.score >= BLOCK_COLOR_ANCHOR_COEXIST_MIN_SCORE
    ):
        return True
    return (
        det.type_id in FULL_SPIKE_TYPES
        and anchor.type_id == OBJ_WATER_2
        and det.score >= FULL_SPIKE_WATER_COEXIST_MIN_SCORE
    )


def _near_anchor(
    x: int,
    y: int,
    anchors: list[Detection],
    max_distance: float,
) -> bool:
    return any(distance((x, y), (anchor.x, anchor.y)) < max_distance for anchor in anchors)


def _connected_components(
    image: RGBImage,
    room: Box,
    predicate,
) -> list[tuple[Box, list[tuple[int, int]]]]:
    left = max(0, room.x)
    top = max(0, room.y)
    right = min(image.width, room.right)
    bottom = min(image.height, room.bottom)
    width = right - left
    height = bottom - top
    mask = bytearray(width * height)

    for y in range(top, bottom):
        row = image.row(y)
        base = (y - top) * width
        for x in range(left, right):
            pos = x * 3
            if predicate(row[pos], row[pos + 1], row[pos + 2]):
                mask[base + (x - left)] = 1

    components: list[tuple[Box, list[tuple[int, int]]]] = []
    for index, value in enumerate(mask):
        if value != 1:
            continue
        stack = [index]
        mask[index] = 2
        pixels: list[tuple[int, int]] = []
        min_x = max_x = left + (index % width)
        min_y = max_y = top + (index // width)
        while stack:
            current = stack.pop()
            cx = current % width
            cy = current // width
            px = left + cx
            py = top + cy
            pixels.append((px, py))
            if px < min_x:
                min_x = px
            elif px > max_x:
                max_x = px
            if py < min_y:
                min_y = py
            elif py > max_y:
                max_y = py

            for nx, ny in ((cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)):
                if nx < 0 or ny < 0 or nx >= width or ny >= height:
                    continue
                neighbor = ny * width + nx
                if mask[neighbor] == 1:
                    mask[neighbor] = 2
                    stack.append(neighbor)
        if len(pixels) >= 8:
            components.append((Box(min_x, min_y, max_x - min_x + 1, max_y - min_y + 1), pixels))
    return components


def _image_box_to_jtool_origin(box: Box, room: Box, grid_step: int) -> tuple[int, int]:
    scale_x = room.width / ROOM_WIDTH
    scale_y = room.height / ROOM_HEIGHT
    raw_x = (box.center_x - room.x) / scale_x - GRID_SIZE / 2
    raw_y = (box.center_y - room.y) / scale_y - GRID_SIZE / 2
    return round_to_step(raw_x, grid_step), round_to_step(raw_y, grid_step)


def _image_box_to_jtool_center(box: Box, room: Box, grid_step: int) -> tuple[int, int]:
    scale_x = room.width / ROOM_WIDTH
    scale_y = room.height / ROOM_HEIGHT
    raw_x = (box.center_x - room.x) / scale_x
    raw_y = (box.center_y - room.y) / scale_y
    return round_to_step(raw_x, grid_step), round_to_step(raw_y, grid_step)


def _dedupe_detections(detections: list[Detection], min_distance: float = 24) -> list[Detection]:
    result: list[Detection] = []
    for det in sorted(detections, key=lambda item: item.score, reverse=True):
        if any(
            det.type_id == existing.type_id
            and distance((det.x, det.y), (existing.x, existing.y)) < min_distance
            for existing in result
        ):
            continue
        result.append(det)
    return sorted(result, key=lambda item: (item.y, item.x, -item.score))


def _average_pixel_color(
    image: RGBImage,
    pixels: list[tuple[int, int]],
) -> tuple[float, float, float]:
    total_r = total_g = total_b = 0
    for x, y in pixels:
        r, g, b = image.pixel(x, y)
        total_r += r
        total_g += g
        total_b += b
    count = max(1, len(pixels))
    return total_r / count, total_g / count, total_b / count


def _is_save_yellow(r: int, g: int, b: int) -> bool:
    return r > 170 and g > 130 and b < 90 and r > b * 2


def _is_save_red(r: int, g: int, b: int) -> bool:
    return r > 120 and g < 95 and b < 95 and r > g * 1.5


def _is_save_green(r: int, g: int, b: int) -> bool:
    return g > 120 and g > r + 35 and g > b + 20


def _is_save_header_pale(r: int, g: int, b: int) -> bool:
    return min(r, g, b) >= 125 and max(r, g, b) - min(r, g, b) <= 95


def _is_tinted_save_yellow(r: int, g: int, b: int) -> bool:
    return r > 95 and g > 145 and 80 < b < 215 and g > r + 25 and g > b + 20


def _is_apple_red(r: int, g: int, b: int) -> bool:
    return r > 150 and g < 95 and b < 95 and r > g * 1.8 and r > b * 1.8


def _is_relative_warm_apple_seed_color(r: int, g: int, b: int) -> bool:
    """Find warm apple remnants without assuming an absolute red palette."""

    return (
        r >= WATER_TINTED_APPLE_SEED_MIN_RED
        and r - g >= WATER_TINTED_APPLE_SEED_MIN_RED_OVER_GREEN
        and r - b >= WATER_TINTED_APPLE_SEED_MIN_RED_OVER_BLUE
    )


def _is_weak_room_corner_apple(x: int, y: int, score: float) -> bool:
    near_x_edge = x <= APPLE_ROOM_CORNER_MARGIN or x >= ROOM_WIDTH - APPLE_ROOM_CORNER_MARGIN
    near_y_edge = y <= APPLE_ROOM_CORNER_MARGIN or y >= ROOM_HEIGHT - APPLE_ROOM_CORNER_MARGIN
    return near_x_edge and near_y_edge and score < APPLE_ROOM_CORNER_KEEP_MIN_SCORE


def _is_outline_apple_dark_neutral(r: int, g: int, b: int) -> bool:
    return r < 170 and g < 170 and b < 170 and max(r, g, b) - min(r, g, b) < 60


def _is_pale_outline_apple_room(profile: _ColorProfile) -> bool:
    return (
        _profile_brightness(profile) >= OUTLINE_APPLE_ROOM_MIN_BRIGHTNESS
        and profile.saturation <= OUTLINE_APPLE_ROOM_MAX_SATURATION
    )


def _is_outline_apple_component(
    box: Box,
    density: float,
    features: _PatchFeatures,
    profile: _ColorProfile,
) -> bool:
    return (
        OUTLINE_APPLE_MIN_WIDTH <= box.width <= OUTLINE_APPLE_MAX_WIDTH
        and OUTLINE_APPLE_MIN_HEIGHT <= box.height <= OUTLINE_APPLE_MAX_HEIGHT
        and OUTLINE_APPLE_MIN_DENSITY <= density <= OUTLINE_APPLE_MAX_DENSITY
        and _profile_brightness(profile) >= OUTLINE_APPLE_MIN_PATCH_BRIGHTNESS
        and profile.saturation <= OUTLINE_APPLE_MAX_PATCH_SATURATION
        and features.edge_density >= OUTLINE_APPLE_MIN_EDGE_DENSITY
        and features.border_score <= OUTLINE_APPLE_MAX_BORDER_SCORE
        and features.center_score >= OUTLINE_APPLE_MIN_CENTER_SCORE
    )


def _is_fragmented_outline_apple_patch(
    features: _PatchFeatures,
    dark_density: float,
    contour_score: float,
    contour_support: float,
    contour_precision: float,
) -> bool:
    """Accept a complete neutral apple cell when its outline is fragmented."""

    return (
        OUTLINE_APPLE_FRAGMENT_MIN_DARK_DENSITY
        <= dark_density
        <= OUTLINE_APPLE_FRAGMENT_MAX_DARK_DENSITY
        and contour_score >= OUTLINE_APPLE_FRAGMENT_MIN_CONTOUR_SCORE
        and contour_support >= OUTLINE_APPLE_FRAGMENT_MIN_CONTOUR_SUPPORT
        and contour_precision >= OUTLINE_APPLE_FRAGMENT_MIN_CONTOUR_PRECISION
        and OUTLINE_APPLE_FRAGMENT_MIN_EDGE_DENSITY
        <= features.edge_density
        <= OUTLINE_APPLE_FRAGMENT_MAX_EDGE_DENSITY
        and features.border_score <= OUTLINE_APPLE_FRAGMENT_MAX_BORDER_SCORE
        and features.center_score >= OUTLINE_APPLE_FRAGMENT_MIN_CENTER_SCORE
    )


def _is_walljump_green(r: int, g: int, b: int) -> bool:
    return g > 115 and r < 90 and b < 105 and g > r + 55 and g > b + 35


def _is_sparse_walljump_green(r: int, g: int, b: int) -> bool:
    return g > 105 and r < 115 and b < 135 and g > r * 1.35 and g > b * 1.20


def _is_pastel_walljump_impostor_color(r: int, g: int, b: int) -> bool:
    """Separate muted green terrain fills from the vine sprite palette."""

    return g > 110 and r > 65 and g > r + 20 and g > b + 10


def _is_water_blue(r: int, g: int, b: int) -> bool:
    return (
        b > 118
        and g > 92
        and r < 190
        and b > r + 18
        and g > r + 3
        and b <= g + 58
    )


def _looks_cyan_tinted(image: RGBImage, room: Box) -> bool:
    total_r = total_g = total_b = count = 0
    step = 8
    for y in range(max(0, room.y), min(image.height, room.bottom), step):
        row = image.row(y)
        for x in range(max(0, room.x), min(image.width, room.right), step):
            offset = x * 3
            total_r += row[offset]
            total_g += row[offset + 1]
            total_b += row[offset + 2]
            count += 1
    if count == 0:
        return False
    avg_r = total_r / count
    avg_g = total_g / count
    avg_b = total_b / count
    return avg_b > avg_g + 15 and avg_g > avg_r + 55


def _light_sample_ratio(image: RGBImage, room: Box) -> float:
    light = count = 0
    step = 8
    for y in range(max(0, room.y), min(image.height, room.bottom), step):
        row = image.row(y)
        for x in range(max(0, room.x), min(image.width, room.right), step):
            offset = x * 3
            r = row[offset]
            g = row[offset + 1]
            b = row[offset + 2]
            count += 1
            if r > 145 and g > 145 and b > 145:
                light += 1
    return light / count if count else 0.0


def _is_warp_blue(r: int, g: int, b: int) -> bool:
    return b > 115 and r < 95 and g < 95 and b > r * 1.4


def _is_warp_purple(r: int, g: int, b: int) -> bool:
    return b > 120 and r > 55 and g < 80 and b > g * 1.7


def _has_dark_portal_core(image: RGBImage, box: Box) -> bool:
    center_x = int(round(box.center_x))
    center_y = int(round(box.center_y))
    total_r = total_g = total_b = count = 0
    for y in range(center_y - 2, center_y + 3):
        for x in range(center_x - 2, center_x + 3):
            if x < 0 or y < 0 or x >= image.width or y >= image.height:
                continue
            r, g, b = image.pixel(x, y)
            total_r += r
            total_g += g
            total_b += b
            count += 1
    if count == 0:
        return False
    avg_r = total_r / count
    avg_g = total_g / count
    avg_b = total_b / count
    return avg_b < 95 and avg_r < 95 and avg_g < 95
